    "Your Screen Time from the last 28 days plus today, as iOS reports it. Today is shown on its own and never counts in weekly comparisons.": "ਪਿਛਲੇ 28 ਦਿਨਾਂ ਅਤੇ ਅੱਜ ਦਾ ਤੁਹਾਡਾ ਸਕ੍ਰੀਨ ਟਾਈਮ, ਜਿਵੇਂ iOS ਦੱਸਦਾ ਹੈ। ਅੱਜ ਵੱਖਰਾ ਦਿਖਾਇਆ ਜਾਂਦਾ ਹੈ ਅਤੇ ਹਫ਼ਤਾਵਾਰੀ ਤੁਲਨਾਵਾਂ ਵਿੱਚ ਕਦੇ ਨਹੀਂ ਗਿਣਿਆ ਜਾਂਦਾ।",
    "Missing isn't zero": "ਗੁੰਮ ਦਾ ਮਤਲਬ ਜ਼ੀਰੋ ਨਹੀਂ",
    "iOS sometimes reports late or only part of a day. Days without data are marked, never counted as zero. If Insights looks empty, tap Refresh.": "iOS ਕਈ ਵਾਰ ਦੇਰ ਨਾਲ ਜਾਂ ਦਿਨ ਦਾ ਸਿਰਫ਼ ਹਿੱਸਾ ਦੱਸਦਾ ਹੈ। ਡੇਟਾ ਤੋਂ ਬਿਨਾਂ ਦਿਨਾਂ ਤੇ ਨਿਸ਼ਾਨ ਲੱਗਦਾ ਹੈ, ਉਨ੍ਹਾਂ ਨੂੰ ਕਦੇ ਜ਼ੀਰੋ ਨਹੀਂ ਗਿਣਿਆ ਜਾਂਦਾ। ਜੇ ਅੰਕੜੇ ਖ਼ਾਲੀ ਦਿਸਣ ਤਾਂ ਤਾਜ਼ਾ ਕਰੋ ਛੂਹੋ।",
    "Apps and totals": "ਐਪਾਂ ਅਤੇ ਕੁੱਲ ਜੋੜ",
    "App times overlap, so they won't add up to your total screen time.": "ਐਪਾਂ ਦੇ ਸਮੇਂ ਆਪਸ ਵਿੱਚ ਰਲਦੇ ਹਨ, ਇਸ ਲਈ ਉਹ ਤੁਹਾਡੇ ਕੁੱਲ ਸਕ੍ਰੀਨ ਟਾਈਮ ਦੇ ਬਰਾਬਰ ਨਹੀਂ ਹੋਣਗੇ।",
    "Other devices": "ਹੋਰ ਡਿਵਾਈਸ",
    "If Screen Time is shared over iCloud, other devices of the same kind may be included.": "ਜੇ ਸਕ੍ਰੀਨ ਟਾਈਮ iCloud ਤੇ ਸਾਂਝਾ ਕੀਤਾ ਹੋਵੇ, ਤਾਂ ਉਸੇ ਕਿਸਮ ਦੇ ਹੋਰ ਡਿਵਾਈਸ ਵੀ ਸ਼ਾਮਲ ਹੋ ਸਕਦੇ ਹਨ।",
    "Private by design": "ਬਣਤਰ ਤੋਂ ਹੀ ਨਿੱਜੀ",
    "Your usage stays inside Apple's Screen Time report. Demora can't read, save or send it.": "ਤੁਹਾਡੀ ਵਰਤੋਂ Apple ਦੀ ਸਕ੍ਰੀਨ ਟਾਈਮ ਰਿਪੋਰਟ ਦੇ ਅੰਦਰ ਹੀ ਰਹਿੰਦੀ ਹੈ। Demora ਇਸਨੂੰ ਪੜ੍ਹ, ਸੰਭਾਲ ਜਾਂ ਭੇਜ ਨਹੀਂ ਸਕਦਾ।",
    // Insights: comparison sentences, coverage and week names (report).
    "%@ h": "%@ ਘੰ",
    "%@ less than the week before": "ਪਿਛਲੇ ਹਫ਼ਤੇ ਨਾਲੋਂ %@ ਘੱਟ",
    "%@ more than the week before": "ਪਿਛਲੇ ਹਫ਼ਤੇ ਨਾਲੋਂ %@ ਵੱਧ",
    "%@: %@ less than your estimate.": "%@: ਤੁਹਾਡੇ ਅੰਦਾਜ਼ੇ ਨਾਲੋਂ %@ ਘੱਟ।",
    "%@: %@ more than your estimate.": "%@: ਤੁਹਾਡੇ ਅੰਦਾਜ਼ੇ ਨਾਲੋਂ %@ ਵੱਧ।",
    "%@: about the same as your estimate.": "%@: ਤੁਹਾਡੇ ਅੰਦਾਜ਼ੇ ਦੇ ਲਗਭਗ ਬਰਾਬਰ।",
    "(%@%%)": "(%@%%)",
    "About the same as the week before": "ਪਿਛਲੇ ਹਫ਼ਤੇ ਦੇ ਲਗਭਗ ਬਰਾਬਰ",
    "Day": "ਦਿਨ",
    "Last 7 full days": "ਪਿਛਲੇ 7 ਪੂਰੇ ਦਿਨ",
    "No comparison yet: both weeks need full data.": "ਅਜੇ ਤੁਲਨਾ ਨਹੀਂ: ਦੋਵਾਂ ਹਫ਼ਤਿਆਂ ਦਾ ਪੂਰਾ ਡੇਟਾ ਚਾਹੀਦਾ ਹੈ।",
    "No data": "ਡੇਟਾ ਨਹੀਂ",
    "No earlier week to compare.": "ਤੁਲਨਾ ਲਈ ਕੋਈ ਪਹਿਲਾਂ ਦਾ ਹਫ਼ਤਾ ਨਹੀਂ।",
    "No full week yet": "ਅਜੇ ਕੋਈ ਪੂਰਾ ਹਫ਼ਤਾ ਨਹੀਂ",
    "Partly reported": "ਅੰਸ਼ਕ ਤੌਰ ਤੇ ਦੱਸਿਆ",
    "The week before": "ਪਿਛਲਾ ਹਫ਼ਤਾ",
    // Trend dashboard.
    "Trends": "ਰੁਝਾਨ",
    "Weekday patterns": "ਹਫ਼ਤੇ ਦੇ ਦਿਨਾਂ ਦੇ ਪੈਟਰਨ",
    "Biggest app changes": "ਐਪਾਂ ਵਿੱਚ ਸਭ ਤੋਂ ਵੱਡੀਆਂ ਤਬਦੀਲੀਆਂ",
    "%d days": "%d ਦਿਨ",
    "No comparable app changes yet.": "ਅਜੇ ਤੁਲਨਾ ਯੋਗ ਕੋਈ ਐਪ ਤਬਦੀਲੀ ਨਹੀਂ।",
    "Selected period": "ਚੁਣਿਆ ਸਮਾਂ",
    // Usage dashboard navigation, chart hints, and duration totals.
    "Previous week": "ਪਿਛਲਾ ਹਫ਼ਤਾ",
    "Next week": "ਅਗਲਾ ਹਫ਼ਤਾ",
    "No trend yet": "ਅਜੇ ਕੋਈ ਰੁਝਾਨ ਨਹੀਂ",
    "%@ h %@ min": "%@ ਘੰ %@ ਮਿੰਟ",
    // Usage & trends and the practical Guide.
    "%@ min": "%@ ਮਿੰਟ",
    "%@ – %@": "%@ – %@",
    "A blank Screen Time report does not mean no usage. Try the refresh arrow, wait for iOS to load, and check access if it stays blank. If a schedule, daily reset or due change seems late, open Demora to reconcile state. An enforcement warning means monitoring needs attention; if a new rule exceeds capacity, reduce overlapping schedules rather than assuming it was saved.": "ਖ਼ਾਲੀ ਸਕ੍ਰੀਨ ਟਾਈਮ ਰਿਪੋਰਟ ਦਾ ਮਤਲਬ ਇਹ ਨਹੀਂ ਕਿ ਕੋਈ ਵਰਤੋਂ ਨਹੀਂ ਹੋਈ। ਤਾਜ਼ਾ ਕਰਨ ਵਾਲਾ ਤੀਰ ਅਜ਼ਮਾਓ, iOS ਦੇ ਲੋਡ ਹੋਣ ਦੀ ਉਡੀਕ ਕਰੋ, ਅਤੇ ਜੇ ਇਹ ਖ਼ਾਲੀ ਰਹੇ ਤਾਂ ਪਹੁੰਚ ਜਾਂਚੋ। ਜੇ ਕੋਈ ਸਮਾਂ-ਸਾਰਣੀ, ਰੋਜ਼ਾਨਾ ਰੀਸੈੱਟ ਜਾਂ ਹੋਣ ਵਾਲੀ ਤਬਦੀਲੀ ਦੇਰ ਨਾਲ ਲੱਗੇ, ਤਾਂ ਸਥਿਤੀ ਮਿਲਾਉਣ ਲਈ Demora ਖੋਲ੍ਹੋ। ਲਾਗੂ ਕਰਨ ਦੀ ਚੇਤਾਵਨੀ ਦਾ ਮਤਲਬ ਹੈ ਕਿ ਨਿਗਰਾਨੀ ਵੱਲ ਧਿਆਨ ਚਾਹੀਦਾ ਹੈ; ਜੇ ਕੋਈ ਨਵਾਂ ਨਿਯਮ ਸਮਰੱਥਾ ਤੋਂ ਵੱਧ ਹੋਵੇ, ਤਾਂ ਇਹ ਮੰਨਣ ਦੀ ਥਾਂ ਕਿ ਉਹ ਸੰਭਾਲਿਆ ਗਿਆ, ਆਪਸ ਵਿੱਚ ਰਲਦੀਆਂ ਸਮਾਂ-ਸਾਰਣੀਆਂ ਘਟਾਓ।",
    "A free period suspends daily limits within its scope, and usage during it is credited back using Screen Time checkpoints, not an exact live stopwatch. An unblock makes its selected apps usable but is not the same as free usage. Other overlapping rules can still block them. Recurring free periods live alongside recurring blocks. Edit apps on a recurring block keeps its identity and timing; the old selection stays active through the less-strict delay.": "ਖੁੱਲ੍ਹਾ ਸਮਾਂ ਆਪਣੇ ਦਾਇਰੇ ਵਿੱਚ ਰੋਜ਼ਾਨਾ ਹੱਦਾਂ ਨੂੰ ਰੋਕ ਦਿੰਦਾ ਹੈ, ਅਤੇ ਉਸ ਦੌਰਾਨ ਦੀ ਵਰਤੋਂ ਸਕ੍ਰੀਨ ਟਾਈਮ ਦੇ ਚੈੱਕਪੁਆਇੰਟਾਂ ਨਾਲ ਵਾਪਸ ਜੋੜੀ ਜਾਂਦੀ ਹੈ, ਕਿਸੇ ਸਟੀਕ ਲਾਈਵ ਸਟਾਪਵਾਚ ਨਾਲ ਨਹੀਂ। ਅਨਬਲੌਕ ਚੁਣੀਆਂ ਐਪਾਂ ਨੂੰ ਵਰਤਣਯੋਗ ਬਣਾਉਂਦਾ ਹੈ ਪਰ ਇਹ ਖੁੱਲ੍ਹੀ ਵਰਤੋਂ ਦੇ ਬਰਾਬਰ ਨਹੀਂ। ਰਲਦੇ ਹੋਰ ਨਿਯਮ ਫਿਰ ਵੀ ਉਨ੍ਹਾਂ ਨੂੰ ਬਲੌਕ ਕਰ ਸਕਦੇ ਹਨ। ਦੁਹਰਾਉਣ ਵਾਲੇ ਖੁੱਲ੍ਹੇ ਸਮੇਂ ਦੁਹਰਾਉਣ ਵਾਲੇ ਬਲੌਕਾਂ ਦੇ ਨਾਲ ਚੱਲਦੇ ਹਨ। ਦੁਹਰਾਉਣ ਵਾਲੇ ਬਲੌਕ ਦੀਆਂ ਐਪਾਂ ਬਦਲਣ ਨਾਲ ਉਸਦੀ ਪਛਾਣ ਅਤੇ ਸਮਾਂ ਕਾਇਮ ਰਹਿੰਦੇ ਹਨ; ਪੁਰਾਣੀ ਚੋਣ ਘੱਟ ਸਖ਼ਤ ਦੇਰੀ ਤੱਕ ਲਾਗੂ ਰਹਿੰਦੀ ਹੈ।",
    "About how much time do you spend on your phone each week?": "ਤੁਸੀਂ ਹਰ ਹਫ਼ਤੇ ਫ਼ੋਨ ਤੇ ਲਗਭਗ ਕਿੰਨਾ ਸਮਾਂ ਬਿਤਾਉਂਦੇ ਹੋ?",
    "Add an optional weekly estimate": "ਹਫ਼ਤੇ ਦਾ ਵਿਕਲਪਿਕ ਅੰਦਾਜ਼ਾ ਜੋੜੋ",
    "App choices and usage stay on-device. Demora has no accounts, advertising or analytics. Optional contact invitations and approval requests relay the names, descriptions and notes you send through CloudKit or Cloudflare and Resend; the email provider receives the readable message and code. Time checks contact Apple's website, and email requests use App Attest verification. Widgets use a small local summary, not app-selection tokens or raw usage.": "ਐਪਾਂ ਦੀ ਚੋਣ ਅਤੇ ਵਰਤੋਂ ਡਿਵਾਈਸ ਤੇ ਹੀ ਰਹਿੰਦੀ ਹੈ। Demora ਵਿੱਚ ਕੋਈ ਖਾਤੇ, ਇਸ਼ਤਿਹਾਰ ਜਾਂ ਐਨਾਲਿਟਿਕਸ ਨਹੀਂ ਹਨ। ਵਿਕਲਪਿਕ ਸੰਪਰਕ-ਸੱਦੇ ਅਤੇ ਮਨਜ਼ੂਰੀ ਦੀਆਂ ਬੇਨਤੀਆਂ ਤੁਹਾਡੇ ਭੇਜੇ ਨਾਮ, ਵੇਰਵੇ ਅਤੇ ਨੋਟ CloudKit ਜਾਂ Cloudflare ਅਤੇ Resend ਰਾਹੀਂ ਅੱਗੇ ਪਹੁੰਚਾਉਂਦੀਆਂ ਹਨ; ਈਮੇਲ ਪ੍ਰਦਾਤਾ ਪੜ੍ਹਨਯੋਗ ਸੁਨੇਹਾ ਅਤੇ ਕੋਡ ਪ੍ਰਾਪਤ ਕਰਦਾ ਹੈ। ਸਮੇਂ ਦੀ ਜਾਂਚ Apple ਦੀ ਵੈੱਬਸਾਈਟ ਨਾਲ ਸੰਪਰਕ ਕਰਦੀ ਹੈ, ਅਤੇ ਈਮੇਲ ਬੇਨਤੀਆਂ App Attest ਤਸਦੀਕ ਵਰਤਦੀਆਂ ਹਨ। ਵਿਜਟ ਇੱਕ ਛੋਟਾ ਸਥਾਨਕ ਸਾਰ ਵਰਤਦੇ ਹਨ, ਐਪ-ਚੋਣ ਟੋਕਨ ਜਾਂ ਕੱਚੀ ਵਰਤੋਂ ਨਹੀਂ।",
    "Blocking needs Screen Time permission. You may finish setup after declining it; Demora respects denial and does not automatically redirect you to iOS Settings. If you want to enable access later, use Demora's permission prompt or open iOS Settings yourself. iOS controls authorization and background callbacks, so blocking is not an unbypassable guarantee.": "ਬਲੌਕ ਕਰਨ ਲਈ ਸਕ੍ਰੀਨ ਟਾਈਮ ਦੀ ਇਜਾਜ਼ਤ ਚਾਹੀਦੀ ਹੈ। ਇਨਕਾਰ ਕਰਨ ਤੋਂ ਬਾਅਦ ਵੀ ਤੁਸੀਂ ਸੈੱਟਅੱਪ ਪੂਰਾ ਕਰ ਸਕਦੇ ਹੋ; Demora ਇਨਕਾਰ ਦਾ ਆਦਰ ਕਰਦਾ ਹੈ ਅਤੇ ਤੁਹਾਨੂੰ ਆਪਣੇ ਆਪ iOS ਸੈਟਿੰਗਾਂ ਵੱਲ ਨਹੀਂ ਭੇਜਦਾ। ਜੇ ਬਾਅਦ ਵਿੱਚ ਪਹੁੰਚ ਚਾਲੂ ਕਰਨੀ ਹੋਵੇ, ਤਾਂ Demora ਦਾ ਇਜਾਜ਼ਤ ਵਾਲਾ ਸੁਨੇਹਾ ਵਰਤੋ ਜਾਂ iOS ਸੈਟਿੰਗਾਂ ਆਪ ਖੋਲ੍ਹੋ। ਅਧਿਕਾਰ ਅਤੇ ਬੈਕਗ੍ਰਾਊਂਡ ਕਾਲਬੈਕ iOS ਦੇ ਹੱਥ ਵਿੱਚ ਹਨ, ਇਸ ਲਈ ਬਲੌਕ ਕਰਨਾ ਅਟੁੱਟ ਗਾਰੰਟੀ ਨਹੀਂ ਹੈ।",
    "Change: %@%%": "ਤਬਦੀਲੀ: %@%%",
    "Choose approval permissions separately for each contact. Extra-time permission is opt-in, including for existing contacts, and a limit's extra-time step must also require contact approval. Demora-user contacts accept an invitation before approving in their app. For email approval, enter the short code in your Demora. Permission edits are delay-gated; an approval skips only the eligible request's wait, not every rule.": "ਹਰ ਭਰੋਸੇਯੋਗ ਸੰਪਰਕ ਲਈ ਮਨਜ਼ੂਰੀ ਦੀਆਂ ਇਜਾਜ਼ਤਾਂ ਵੱਖਰੀਆਂ ਚੁਣੋ। ਵੱਧ ਸਮੇਂ ਦੀ ਇਜਾਜ਼ਤ ਆਪਣੀ ਮਰਜ਼ੀ ਨਾਲ ਦਿੱਤੀ ਜਾਂਦੀ ਹੈ, ਮੌਜੂਦਾ ਸੰਪਰਕਾਂ ਲਈ ਵੀ, ਅਤੇ ਹੱਦ ਦੇ ਵੱਧ ਸਮੇਂ ਦੇ ਕਦਮ ਲਈ ਵੀ ਸੰਪਰਕ ਦੀ ਮਨਜ਼ੂਰੀ ਲਾਜ਼ਮੀ ਹੋਣੀ ਚਾਹੀਦੀ ਹੈ। Demora ਵਰਤਣ ਵਾਲੇ ਸੰਪਰਕ ਆਪਣੀ ਐਪ ਵਿੱਚ ਮਨਜ਼ੂਰੀ ਦੇਣ ਤੋਂ ਪਹਿਲਾਂ ਸੱਦਾ ਸਵੀਕਾਰ ਕਰਦੇ ਹਨ। ਈਮੇਲ ਮਨਜ਼ੂਰੀ ਲਈ ਆਪਣੇ Demora ਵਿੱਚ ਛੋਟਾ ਕੋਡ ਭਰੋ। ਇਜਾਜ਼ਤਾਂ ਦੀਆਂ ਤਬਦੀਲੀਆਂ ਦੇਰੀ ਦੇ ਅਧੀਨ ਹਨ; ਇੱਕ ਮਨਜ਼ੂਰੀ ਸਿਰਫ਼ ਯੋਗ ਬੇਨਤੀ ਦੀ ਉਡੀਕ ਛੱਡਦੀ ਹੈ, ਹਰ ਨਿਯਮ ਦੀ ਨਹੀਂ।",
    "Completed-day comparison": "ਪੂਰੇ ਦਿਨਾਂ ਦੀ ਤੁਲਨਾ",
    "Couldn't save your estimate. Try again.": "ਤੁਹਾਡਾ ਅੰਦਾਜ਼ਾ ਸੰਭਾਲਿਆ ਨਹੀਂ ਜਾ ਸਕਿਆ। ਦੁਬਾਰਾ ਕੋਸ਼ਿਸ਼ ਕਰੋ।",
    "Delay policy": "ਦੇਰੀ ਦੀ ਨੀਤੀ",
    "Expand Split daily budget to divide the allowance into time-of-day portions, with optional carryover of unused early minutes. New limits can use three portions; existing two-portion limits remain editable. Spending an early portion blocks until its next boundary, even if later portions have minutes left. Editing a spent limit does not give it a fresh daily allowance. Selection edits follow the less-strict delay and can discard free-period credit tied to the old selection.": "ਰੋਜ਼ਾਨਾ ਸਮੇਂ ਨੂੰ ਦਿਨ ਦੇ ਹਿੱਸਿਆਂ ਵਿੱਚ ਵੰਡਣ ਲਈ, ਅਤੇ ਅਣਵਰਤੇ ਸ਼ੁਰੂਆਤੀ ਮਿੰਟ ਅੱਗੇ ਲਿਜਾਣ ਦੇ ਵਿਕਲਪ ਲਈ, ਰੋਜ਼ਾਨਾ ਸਮਾਂ ਵੰਡੋ ਨੂੰ ਖੋਲ੍ਹੋ। ਨਵੀਆਂ ਹੱਦਾਂ ਤਿੰਨ ਹਿੱਸੇ ਵਰਤ ਸਕਦੀਆਂ ਹਨ; ਮੌਜੂਦਾ ਦੋ ਹਿੱਸਿਆਂ ਵਾਲੀਆਂ ਹੱਦਾਂ ਬਦਲੀਆਂ ਜਾ ਸਕਦੀਆਂ ਹਨ। ਸ਼ੁਰੂਆਤੀ ਹਿੱਸਾ ਮੁੱਕਣ ਤੇ ਅਗਲੀ ਹੱਦ ਤੱਕ ਬਲੌਕ ਰਹਿੰਦਾ ਹੈ, ਭਾਵੇਂ ਬਾਅਦ ਦੇ ਹਿੱਸਿਆਂ ਵਿੱਚ ਮਿੰਟ ਬਚੇ ਹੋਣ। ਮੁੱਕ ਚੁੱਕੀ ਹੱਦ ਨੂੰ ਬਦਲਣ ਨਾਲ ਰੋਜ਼ਾਨਾ ਸਮਾਂ ਨਵੇਂ ਸਿਰਿਓਂ ਨਹੀਂ ਮਿਲਦਾ। ਚੋਣ ਦੀਆਂ ਤਬਦੀਲੀਆਂ ਘੱਟ ਸਖ਼ਤ ਦੇਰੀ ਮੁਤਾਬਕ ਚੱਲਦੀਆਂ ਹਨ ਅਤੇ ਪੁਰਾਣੀ ਚੋਣ ਨਾਲ ਜੁੜਿਆ ਖੁੱਲ੍ਹੇ ਸਮੇਂ ਦਾ ਹਿਸਾਬ ਮਿਟ ਸਕਦਾ ਹੈ।",
    "Hours and minutes per week, not per day.": "ਘੰਟੇ ਅਤੇ ਮਿੰਟ ਪ੍ਰਤੀ ਹਫ਼ਤਾ, ਪ੍ਰਤੀ ਦਿਨ ਨਹੀਂ।",
    "Notifications & widgets": "ਸੂਚਨਾਵਾਂ ਤੇ ਵਿਜਟ",
    "Partial source coverage": "ਅੰਸ਼ਕ ਸਰੋਤ ਕਵਰੇਜ",
    "Passwords & phrases": "ਪਾਸਵਰਡ ਤੇ ਵਾਕ",
    "Privacy": "ਪਰਦੇਦਾਰੀ",
    "Screen Time reports and a personal baseline": "ਸਕ੍ਰੀਨ ਟਾਈਮ ਰਿਪੋਰਟਾਂ ਅਤੇ ਨਿੱਜੀ ਆਧਾਰ",
    "Self-reported weekly baseline": "ਆਪ ਦੱਸਿਆ ਹਫ਼ਤਾਵਾਰੀ ਆਧਾਰ",
    "Sleep starts on the selected evening and ends at the following morning's wake-up start, using that morning's custom time. Group edits follow your delay policy. Wake timing edits preserve spent usage, split accounting, extra-time grants and a running wait's deadline; a new wait applies to the next tap. A delayed latest-time change can end today's gate once it applies. Turning the gate off is delay-gated too.": "ਨੀਂਦ ਚੁਣੀ ਸ਼ਾਮ ਨੂੰ ਸ਼ੁਰੂ ਹੁੰਦੀ ਹੈ ਅਤੇ ਅਗਲੀ ਸਵੇਰ ਦੇ ਜਾਗਣ ਦੇ ਸ਼ੁਰੂ ਤੇ ਮੁੱਕਦੀ ਹੈ, ਉਸ ਸਵੇਰ ਦਾ ਆਪਣਾ ਸਮਾਂ ਵਰਤ ਕੇ। ਗਰੁੱਪ ਦੀਆਂ ਤਬਦੀਲੀਆਂ ਤੁਹਾਡੀ ਦੇਰੀ ਦੀ ਨੀਤੀ ਮੁਤਾਬਕ ਚੱਲਦੀਆਂ ਹਨ। ਜਾਗਣ ਦੇ ਸਮੇਂ ਦੀਆਂ ਤਬਦੀਲੀਆਂ ਲੱਗ ਚੁੱਕੀ ਵਰਤੋਂ, ਵੰਡੇ ਹਿਸਾਬ, ਵੱਧ ਸਮੇਂ ਦੀਆਂ ਛੋਟਾਂ ਅਤੇ ਚੱਲ ਰਹੀ ਉਡੀਕ ਦੀ ਆਖ਼ਰੀ ਤਾਰੀਖ਼ ਨੂੰ ਕਾਇਮ ਰੱਖਦੀਆਂ ਹਨ; ਨਵੀਂ ਉਡੀਕ ਅਗਲੀ ਛੂਹ ਤੋਂ ਲਾਗੂ ਹੁੰਦੀ ਹੈ। ਦੇਰੀ ਨਾਲ ਲੱਗਣ ਵਾਲੀ ਆਖ਼ਰੀ-ਸਮੇਂ ਦੀ ਤਬਦੀਲੀ ਲੱਗਣ ਤੇ ਅੱਜ ਦਾ ਗੇਟ ਖ਼ਤਮ ਕਰ ਸਕਦੀ ਹੈ। ਗੇਟ ਬੰਦ ਕਰਨਾ ਵੀ ਦੇਰੀ ਦੇ ਅਧੀਨ ਹੈ।",
    "The app deletion lock asks iOS to prevent deleting apps, including Demora. Turning it off is a less-strict change. It discourages one bypass route but does not make Screen Time permissions or the device impossible to change. Notifications and widgets are optional aids, not the enforcement mechanism.": "ਐਪ ਮਿਟਾਉਣ ਦਾ ਤਾਲਾ iOS ਨੂੰ ਐਪਾਂ, Demora ਸਮੇਤ, ਮਿਟਾਉਣ ਤੋਂ ਰੋਕਣ ਲਈ ਕਹਿੰਦਾ ਹੈ। ਇਸਨੂੰ ਬੰਦ ਕਰਨਾ ਘੱਟ ਸਖ਼ਤ ਤਬਦੀਲੀ ਹੈ। ਇਹ ਬਚ ਨਿਕਲਣ ਦਾ ਇੱਕ ਰਾਹ ਔਖਾ ਕਰਦਾ ਹੈ, ਪਰ ਸਕ੍ਰੀਨ ਟਾਈਮ ਦੀਆਂ ਇਜਾਜ਼ਤਾਂ ਜਾਂ ਡਿਵਾਈਸ ਨੂੰ ਬਦਲਣਾ ਨਾਮੁਮਕਿਨ ਨਹੀਂ ਬਣਾਉਂਦਾ। ਸੂਚਨਾਵਾਂ ਅਤੇ ਵਿਜਟ ਵਿਕਲਪਿਕ ਸਹਾਇਕ ਹਨ, ਲਾਗੂ ਕਰਨ ਦਾ ਢੰਗ ਨਹੀਂ।",
    "Today is not included in this comparison.": "ਅੱਜ ਇਸ ਤੁਲਨਾ ਵਿੱਚ ਸ਼ਾਮਲ ਨਹੀਂ ਹੈ।",
    "Today so far": "ਅੱਜ ਹੁਣ ਤੱਕ",
    "Troubleshooting": "ਸਮੱਸਿਆ ਹੱਲ",
    "Usage reports": "ਵਰਤੋਂ ਰਿਪੋਰਟਾਂ",
    "Most used apps": "ਸਭ ਤੋਂ ਵੱਧ ਵਰਤੀਆਂ ਐਪਾਂ",
    "All apps": "ਸਾਰੀਆਂ ਐਪਾਂ",
    "Use Prioritize this to apply a rule after rules at default priority, or Restore default priority to undo that choice. Both actions always queue a less-strict change, even if you expect a stricter result. Among prioritized rules, the last one promoted applies last. Priority changes ordering, not a rule's app selection or your spent daily allowance.": "ਕਿਸੇ ਨਿਯਮ ਨੂੰ ਮੂਲ ਤਰਜੀਹ ਵਾਲੇ ਨਿਯਮਾਂ ਤੋਂ ਬਾਅਦ ਲਾਗੂ ਕਰਨ ਲਈ ਇਸਨੂੰ ਤਰਜੀਹ ਦਿਓ ਵਰਤੋ, ਜਾਂ ਉਹ ਚੋਣ ਪਲਟਣ ਲਈ ਮੂਲ ਤਰਜੀਹ ਬਹਾਲ ਕਰੋ। ਦੋਵੇਂ ਕਾਰਵਾਈਆਂ ਹਮੇਸ਼ਾ ਘੱਟ ਸਖ਼ਤ ਤਬਦੀਲੀ ਕਤਾਰ ਵਿੱਚ ਲਾਉਂਦੀਆਂ ਹਨ, ਭਾਵੇਂ ਤੁਸੀਂ ਵੱਧ ਸਖ਼ਤ ਨਤੀਜਾ ਸੋਚਦੇ ਹੋਵੋ। ਤਰਜੀਹ ਵਾਲੇ ਨਿਯਮਾਂ ਵਿੱਚੋਂ ਆਖ਼ਰੀ ਚੁਣਿਆ ਹੋਇਆ ਸਭ ਤੋਂ ਬਾਅਦ ਲਾਗੂ ਹੁੰਦਾ ਹੈ। ਤਰਜੀਹ ਕ੍ਰਮ ਬਦਲਦੀ ਹੈ, ਨਿਯਮ ਦੀ ਐਪ-ਚੋਣ ਜਾਂ ਤੁਹਾਡਾ ਵਰਤਿਆ ਰੋਜ਼ਾਨਾ ਸਮਾਂ ਨਹੀਂ।",
    "Weekly baseline": "ਹਫ਼ਤਾਵਾਰੀ ਆਧਾਰ",
    "Your starting point": "ਤੁਹਾਡਾ ਸ਼ੁਰੂਆਤੀ ਬਿੰਦੂ",
    "choose a policy, manage pending changes": "ਨੀਤੀ ਚੁਣੋ, ਉਡੀਕ ਵਿੱਚ ਪਈਆਂ ਤਬਦੀਲੀਆਂ ਸੰਭਾਲੋ",
    "optional reminders and privacy": "ਵਿਕਲਪਿਕ ਯਾਦ-ਦਹਾਨੀਆਂ ਅਤੇ ਪਰਦੇਦਾਰੀ",
    "overlaps, scopes and priority": "ਰਲਦੇ ਨਿਯਮ, ਦਾਇਰੇ ਅਤੇ ਤਰਜੀਹ",
    "permissions, blank reports and false blocks": "ਇਜਾਜ਼ਤਾਂ, ਖ਼ਾਲੀ ਰਿਪੋਰਟਾਂ ਅਤੇ ਗ਼ਲਤ ਬਲੌਕ",
    "wake waits, latest times and sleep": "ਜਾਗਣ ਦੀਆਂ ਉਡੀਕਾਂ, ਆਖ਼ਰੀ ਸਮੇਂ ਅਤੇ ਨੀਂਦ",
    "Latest wake-up: %@": "ਸਭ ਤੋਂ ਦੇਰ ਨਾਲ ਜਾਗਣਾ: %@",
    // Home report controls and default wake-up timing.
    "Expand": "ਫੈਲਾਓ",
    "Collapse": "ਸਮੇਟੋ",
    "Expanded": "ਫੈਲਿਆ ਹੋਇਆ",
    "Compact": "ਸੰਖੇਪ",
    "Start your morning": "ਆਪਣੀ ਸਵੇਰ ਸ਼ੁਰੂ ਕਰੋ",
    "Usage stays in the Screen Time report. Scroll to see more groups. If it looks empty, try Refresh; an empty report does not mean zero usage.": "ਵਰਤੋਂ ਸਕ੍ਰੀਨ ਟਾਈਮ ਰਿਪੋਰਟ ਵਿੱਚ ਹੀ ਰਹਿੰਦੀ ਹੈ। ਹੋਰ ਗਰੁੱਪ ਦੇਖਣ ਲਈ ਸਕ੍ਰੋਲ ਕਰੋ। ਜੇ ਇਹ ਖ਼ਾਲੀ ਦਿਸੇ ਤਾਂ ਤਾਜ਼ਾ ਕਰੋ ਅਜ਼ਮਾਓ; ਖ਼ਾਲੀ ਰਿਪੋਰਟ ਦਾ ਮਤਲਬ ਜ਼ੀਰੋ ਵਰਤੋਂ ਨਹੀਂ।",
    "Days without custom times use the default start, wait and latest time above.": "ਬਿਨਾਂ ਆਪਣੇ ਸਮੇਂ ਵਾਲੇ ਦਿਨ ਉੱਪਰ ਦਿੱਤੀ ਮੂਲ ਸ਼ੁਰੂਆਤ, ਉਡੀਕ ਅਤੇ ਆਖ਼ਰੀ ਸਮਾਂ ਵਰਤਦੇ ਹਨ।",
    "Wake-up overlaps are estimates until you tap Wake up. Allowlisted apps still obey other specific blocks and daily limits.": "ਜਾਗੋ ਛੂਹਣ ਤੱਕ ਜਾਗਣ ਦੇ ਰਲਾਅ ਸਿਰਫ਼ ਅੰਦਾਜ਼ੇ ਹਨ। ਮਨਜ਼ੂਰ ਸੂਚੀ ਵਾਲੀਆਂ ਐਪਾਂ ਫਿਰ ਵੀ ਹੋਰ ਖ਼ਾਸ ਬਲੌਕਾਂ ਅਤੇ ਰੋਜ਼ਾਨਾ ਹੱਦਾਂ ਨੂੰ ਮੰਨਦੀਆਂ ਹਨ।",
    "Restore default priority": "ਮੂਲ ਤਰਜੀਹ ਬਹਾਲ ਕਰੋ",
    // Migration delay choices, wake-up ceilings, and schedule priority.
    "Optional. Keep separate waits, use one shared wait, or tighten immediately and wait only when loosening rules. If you skip this, your delay settings stay unchanged.": "ਵਿਕਲਪਿਕ। ਵੱਖਰੀਆਂ ਉਡੀਕਾਂ ਰੱਖੋ, ਇੱਕ ਸਾਂਝੀ ਉਡੀਕ ਵਰਤੋ, ਜਾਂ ਤੁਰੰਤ ਸਖ਼ਤ ਕਰੋ ਅਤੇ ਸਿਰਫ਼ ਨਿਯਮ ਢਿੱਲੇ ਕਰਨ ਵੇਲੇ ਉਡੀਕੋ। ਜੇ ਇਹ ਛੱਡੋ, ਤਾਂ ਤੁਹਾਡੀਆਂ ਦੇਰੀ ਦੀਆਂ ਸੈਟਿੰਗਾਂ ਜਿਉਂ ਦੀਆਂ ਤਿਉਂ ਰਹਿੰਦੀਆਂ ਹਨ।",
    "Your saved rules and pending changes are retained. Unless you queue a change, your existing delay settings stay unchanged.": "ਤੁਹਾਡੇ ਸੰਭਾਲੇ ਨਿਯਮ ਅਤੇ ਉਡੀਕ ਵਿੱਚ ਪਈਆਂ ਤਬਦੀਲੀਆਂ ਕਾਇਮ ਹਨ। ਜਦ ਤੱਕ ਤੁਸੀਂ ਕੋਈ ਤਬਦੀਲੀ ਕਤਾਰ ਵਿੱਚ ਨਾ ਲਾਓ, ਤੁਹਾਡੀਆਂ ਮੌਜੂਦਾ ਦੇਰੀ ਸੈਟਿੰਗਾਂ ਨਹੀਂ ਬਦਲਦੀਆਂ।",
    "Demo only. Try the delay choices here; nothing is queued or saved. Go back to keep exploring the welcome.": "ਸਿਰਫ਼ ਡੈਮੋ। ਇੱਥੇ ਦੇਰੀ ਦੇ ਵਿਕਲਪ ਅਜ਼ਮਾਓ; ਕੁਝ ਵੀ ਕਤਾਰ ਵਿੱਚ ਨਹੀਂ ਲੱਗਦਾ ਜਾਂ ਸੰਭਾਲਿਆ ਨਹੀਂ ਜਾਂਦਾ। ਸੁਆਗਤ ਦੇਖਦੇ ਰਹਿਣ ਲਈ ਪਿੱਛੇ ਜਾਓ।",
    "A new wait applies to the next tap. A latest wake-up time can end today's gate once this delayed change applies. Turning this off still follows your less-strict delay.": "ਨਵੀਂ ਉਡੀਕ ਅਗਲੀ ਛੂਹ ਤੋਂ ਲਾਗੂ ਹੁੰਦੀ ਹੈ। ਇਹ ਦੇਰੀ ਵਾਲੀ ਤਬਦੀਲੀ ਲੱਗਣ ਤੇ ਸਭ ਤੋਂ ਦੇਰ ਨਾਲ ਜਾਗਣ ਦਾ ਸਮਾਂ ਅੱਜ ਦਾ ਗੇਟ ਖ਼ਤਮ ਕਰ ਸਕਦਾ ਹੈ। ਇਸਨੂੰ ਬੰਦ ਕਰਨਾ ਵੀ ਤੁਹਾਡੀ ਘੱਟ ਸਖ਼ਤ ਦੇਰੀ ਮੁਤਾਬਕ ਚੱਲਦਾ ਹੈ।",
    "A running wait keeps its deadline, but never extends past its configured latest wake-up time. Other blocks still apply.": "ਚੱਲ ਰਹੀ ਉਡੀਕ ਆਪਣੀ ਆਖ਼ਰੀ ਤਾਰੀਖ਼ ਰੱਖਦੀ ਹੈ, ਪਰ ਤੈਅ ਕੀਤੇ ਸਭ ਤੋਂ ਦੇਰ ਨਾਲ ਜਾਗਣ ਦੇ ਸਮੇਂ ਤੋਂ ਅੱਗੇ ਨਹੀਂ ਵਧਦੀ। ਹੋਰ ਬਲੌਕ ਫਿਰ ਵੀ ਲਾਗੂ ਰਹਿੰਦੇ ਹਨ।",
    "Set a latest wake-up time": "ਸਭ ਤੋਂ ਦੇਰ ਨਾਲ ਜਾਗਣ ਦਾ ਸਮਾਂ ਤੈਅ ਕਰੋ",
    "Wake blocking ends by": "ਜਾਗਣ ਦੀ ਬਲੌਕਿੰਗ ਇਸ ਤੱਕ ਮੁੱਕਦੀ ਹੈ",
    "At this time, this wake-up block ends even if you haven't tapped Wake up or its wait is still running.": "ਇਸ ਸਮੇਂ ਇਹ ਜਾਗਣ ਦਾ ਬਲੌਕ ਮੁੱਕ ਜਾਂਦਾ ਹੈ, ਭਾਵੇਂ ਤੁਸੀਂ ਜਾਗੋ ਨਾ ਛੂਹਿਆ ਹੋਵੇ ਜਾਂ ਉਡੀਕ ਅਜੇ ਚੱਲ ਰਹੀ ਹੋਵੇ।",
    "Choose a latest time after the wake-up day begins.": "ਜਾਗਣ ਦਾ ਦਿਨ ਸ਼ੁਰੂ ਹੋਣ ਤੋਂ ਬਾਅਦ ਦਾ ਆਖ਼ਰੀ ਸਮਾਂ ਚੁਣੋ।",
    "Prioritize %@": "%@ ਨੂੰ ਤਰਜੀਹ ਦਿਓ",
    "Restore default priority for %@": "%@ ਲਈ ਮੂਲ ਤਰਜੀਹ ਬਹਾਲ ਕਰੋ",
    "Schedule conflicts": "ਸਮਾਂ-ਸਾਰਣੀਆਂ ਦਾ ਟਕਰਾਅ",
    "Potential overlaps": "ਸੰਭਾਵੀ ਰਲਾਅ",
    "No conflicting schedules found.": "ਕੋਈ ਟਕਰਾਉਂਦੀ ਸਮਾਂ-ਸਾਰਣੀ ਨਹੀਂ ਮਿਲੀ।",
    "Default order: wake-up → recurring → planned → sessions.": "ਮੂਲ ਕ੍ਰਮ: ਜਾਗਣਾ → ਦੁਹਰਾਉਣ ਵਾਲੇ → ਯੋਜਨਾਬੱਧ → ਸੈਸ਼ਨ।",
    "Prioritize this": "ਇਸਨੂੰ ਤਰਜੀਹ ਦਿਓ",
    "Default priority": "ਮੂਲ ਤਰਜੀਹ",
    "Prioritized": "ਤਰਜੀਹ ਵਾਲਾ",
    "Priority changes follow your less-strict delay.": "ਤਰਜੀਹ ਦੀਆਂ ਤਬਦੀਲੀਆਂ ਤੁਹਾਡੀ ਘੱਟ ਸਖ਼ਤ ਦੇਰੀ ਮੁਤਾਬਕ ਚੱਲਦੀਆਂ ਹਨ।",
    "When several rules are prioritized, the last one promoted is applied last.": "ਜਦੋਂ ਕਈ ਨਿਯਮਾਂ ਨੂੰ ਤਰਜੀਹ ਦਿੱਤੀ ਹੋਵੇ, ਤਾਂ ਆਖ਼ਰੀ ਚੁਣਿਆ ਹੋਇਆ ਸਭ ਤੋਂ ਬਾਅਦ ਲਾਗੂ ਹੁੰਦਾ ਹੈ।",
    "These rules overlap in time. Apple hides category membership, so some app overlaps cannot be confirmed.": "ਇਹ ਨਿਯਮ ਸਮੇਂ ਵਿੱਚ ਆਪਸ ਵਿੱਚ ਰਲਦੇ ਹਨ। Apple ਸ਼੍ਰੇਣੀਆਂ ਦੀ ਮੈਂਬਰੀ ਲੁਕਾਉਂਦਾ ਹੈ, ਇਸ ਲਈ ਕੁਝ ਐਪਾਂ ਦੇ ਰਲਾਅ ਪੱਕੇ ਨਹੀਂ ਕੀਤੇ ਜਾ ਸਕਦੇ।",
    "Next occurrence": "ਅਗਲੀ ਵਾਰ",
    "Possible overlap": "ਸੰਭਾਵੀ ਰਲਾਅ",
    "Applies last": "ਸਭ ਤੋਂ ਬਾਅਦ ਲਾਗੂ",
    "Priority": "ਤਰਜੀਹ",
    "See overlapping rules": "ਰਲਦੇ ਨਿਯਮ ਦੇਖੋ",
    "Change wake-up schedule for %@": "%@ ਲਈ ਜਾਗਣ ਦੀ ਸਮਾਂ-ਸਾਰਣੀ ਬਦਲੋ",
    "Customize wake-up by day": "ਦਿਨ ਮੁਤਾਬਕ ਜਾਗਣ ਨੂੰ ਆਪਣੇ ਹਿਸਾਬ ਨਾਲ ਬਦਲੋ",
    "Days without custom times use the default start and wait above.": "ਬਿਨਾਂ ਆਪਣੇ ਸਮੇਂ ਵਾਲੇ ਦਿਨ ਉੱਪਰ ਦਿੱਤੀ ਮੂਲ ਸ਼ੁਰੂਆਤ ਅਤੇ ਉਡੀਕ ਵਰਤਦੇ ਹਨ।",
    "A wake-up wait already in progress keeps its original deadline.": "ਪਹਿਲਾਂ ਹੀ ਚੱਲ ਰਹੀ ਜਾਗਣ ਦੀ ਉਡੀਕ ਆਪਣੀ ਅਸਲੀ ਆਖ਼ਰੀ ਤਾਰੀਖ਼ ਰੱਖਦੀ ਹੈ।",
    "Give each limit or group its own wake-up start, wait and weekdays. One Wake up tap starts all eligible waits. Overlapping rules still apply.": "ਹਰ ਹੱਦ ਜਾਂ ਗਰੁੱਪ ਨੂੰ ਉਸਦੀ ਆਪਣੀ ਜਾਗਣ ਦੀ ਸ਼ੁਰੂਆਤ, ਉਡੀਕ ਅਤੇ ਹਫ਼ਤੇ ਦੇ ਦਿਨ ਦਿਓ। ਇੱਕ ਜਾਗੋ ਛੂਹ ਸਾਰੀਆਂ ਯੋਗ ਉਡੀਕਾਂ ਸ਼ੁਰੂ ਕਰ ਦਿੰਦੀ ਹੈ। ਰਲਦੇ ਨਿਯਮ ਫਿਰ ਵੀ ਲਾਗੂ ਰਹਿੰਦੇ ਹਨ।",
    "Sleep ends at the following wake-up start, using that day's custom time if set.": "ਨੀਂਦ ਅਗਲੀ ਜਾਗਣ ਦੀ ਸ਼ੁਰੂਆਤ ਤੇ ਮੁੱਕਦੀ ਹੈ, ਜੇ ਉਸ ਦਿਨ ਦਾ ਆਪਣਾ ਸਮਾਂ ਤੈਅ ਹੋਵੇ ਤਾਂ ਉਹ ਵਰਤ ਕੇ।",
    "Custom wake-up times by day": "ਦਿਨ ਮੁਤਾਬਕ ਜਾਗਣ ਦੇ ਆਪਣੇ ਸਮੇਂ",
    "Discard day/night drafts": "ਦਿਨ/ਰਾਤ ਦੇ ਖਰੜੇ ਰੱਦ ਕਰੋ",
    // Named day/night groups, shared wake-up, and additive setup.
    "%d apps, %d categories, %d websites": "%d ਐਪਾਂ, %d ਸ਼੍ਰੇਣੀਆਂ, %d ਵੈੱਬਸਾਈਟਾਂ",
    "%d day/night groups": "%d ਦਿਨ/ਰਾਤ ਗਰੁੱਪ",
    "%d limits · %d apps, %d categories, %d websites": "%d ਹੱਦਾਂ · %d ਐਪਾਂ, %d ਸ਼੍ਰੇਣੀਆਂ, %d ਵੈੱਬਸਾਈਟਾਂ",
    "A change for this group is pending. Its current rules stay in place until that change applies.": "ਇਸ ਗਰੁੱਪ ਲਈ ਇੱਕ ਤਬਦੀਲੀ ਉਡੀਕ ਵਿੱਚ ਹੈ। ਉਹ ਲੱਗਣ ਤੱਕ ਇਸਦੇ ਮੌਜੂਦਾ ਨਿਯਮ ਕਾਇਮ ਰਹਿੰਦੇ ਹਨ।",
    "Add a group to give its apps their own wake-up wait and sleep time.": "ਕਿਸੇ ਗਰੁੱਪ ਦੀਆਂ ਐਪਾਂ ਨੂੰ ਉਨ੍ਹਾਂ ਦੀ ਆਪਣੀ ਜਾਗਣ ਦੀ ਉਡੀਕ ਅਤੇ ਨੀਂਦ ਦਾ ਸਮਾਂ ਦੇਣ ਲਈ ਗਰੁੱਪ ਜੋੜੋ।",
    "Add day/night group": "ਦਿਨ/ਰਾਤ ਗਰੁੱਪ ਜੋੜੋ",
    "All other apps except…": "ਇਨ੍ਹਾਂ ਤੋਂ ਇਲਾਵਾ ਬਾਕੀ ਸਾਰੀਆਂ ਐਪਾਂ…",
    "An all-other-apps fallback automatically excludes apps targeted by your named selected groups. Category-based groups cannot be combined with this fallback.": "ਬਾਕੀ-ਸਾਰੀਆਂ-ਐਪਾਂ ਵਾਲਾ ਬਦਲ ਤੁਹਾਡੇ ਨਾਮ ਵਾਲੇ ਚੁਣੇ ਗਰੁੱਪਾਂ ਦੀਆਂ ਐਪਾਂ ਨੂੰ ਆਪਣੇ ਆਪ ਬਾਹਰ ਰੱਖਦਾ ਹੈ। ਸ਼੍ਰੇਣੀਆਂ ਵਾਲੇ ਗਰੁੱਪ ਇਸ ਬਦਲ ਨਾਲ ਨਹੀਂ ਜੋੜੇ ਜਾ ਸਕਦੇ।",
    "App scope": "ਐਪ ਦਾਇਰਾ",
    "App selection is unavailable until Screen Time access is allowed.": "ਜਦ ਤੱਕ ਸਕ੍ਰੀਨ ਟਾਈਮ ਦੀ ਪਹੁੰਚ ਨਹੀਂ ਦਿੱਤੀ ਜਾਂਦੀ, ਐਪ ਚੋਣ ਉਪਲਬਧ ਨਹੀਂ।",
    "Apps to exclude": "ਬਾਹਰ ਰੱਖਣ ਵਾਲੀਆਂ ਐਪਾਂ",
    "Category exceptions are not supported. Choose individual apps or limits without categories; choosing a category cannot allow all of its apps.": "ਸ਼੍ਰੇਣੀ ਦੀਆਂ ਛੋਟਾਂ ਸਮਰਥਿਤ ਨਹੀਂ। ਵੱਖਰੀਆਂ ਐਪਾਂ ਜਾਂ ਬਿਨਾਂ ਸ਼੍ਰੇਣੀਆਂ ਵਾਲੀਆਂ ਹੱਦਾਂ ਚੁਣੋ; ਸ਼੍ਰੇਣੀ ਚੁਣਨ ਨਾਲ ਉਸਦੀਆਂ ਸਾਰੀਆਂ ਐਪਾਂ ਨੂੰ ਇਜਾਜ਼ਤ ਨਹੀਂ ਮਿਲ ਸਕਦੀ।",
    "Check existing limits and choose extra apps for this group's boundaries.": "ਮੌਜੂਦਾ ਹੱਦਾਂ ਜਾਂਚੋ ਅਤੇ ਇਸ ਗਰੁੱਪ ਦੀਆਂ ਹੱਦਾਂ ਲਈ ਵਾਧੂ ਐਪਾਂ ਚੁਣੋ।",
    "Choose a name, at least one boundary, weekdays and a valid app scope. Sleep and wake-up times must differ.": "ਨਾਮ, ਘੱਟੋ-ਘੱਟ ਇੱਕ ਹੱਦ, ਹਫ਼ਤੇ ਦੇ ਦਿਨ ਅਤੇ ਠੀਕ ਐਪ ਦਾਇਰਾ ਚੁਣੋ। ਨੀਂਦ ਅਤੇ ਜਾਗਣ ਦੇ ਸਮੇਂ ਵੱਖਰੇ ਹੋਣੇ ਚਾਹੀਦੇ ਹਨ।",
    "Contains categories — cannot be a fallback exception.": "ਸ਼੍ਰੇਣੀਆਂ ਸ਼ਾਮਲ ਹਨ — ਬਦਲ ਵਾਲੀ ਛੋਟ ਨਹੀਂ ਬਣ ਸਕਦਾ।",
    "Day/night group": "ਦਿਨ/ਰਾਤ ਗਰੁੱਪ",
    "Demo: select sample limits above. The real app picker is not opened.": "ਡੈਮੋ: ਉੱਪਰੋਂ ਨਮੂਨੇ ਦੀਆਂ ਹੱਦਾਂ ਚੁਣੋ। ਅਸਲੀ ਐਪ ਚੋਣਕਾਰ ਨਹੀਂ ਖੁੱਲ੍ਹਦਾ।",
    "Existing limits": "ਮੌਜੂਦਾ ਹੱਦਾਂ",
    "Existing sleep settings": "ਮੌਜੂਦਾ ਨੀਂਦ ਦੀਆਂ ਸੈਟਿੰਗਾਂ",
    "Existing wake-up settings": "ਮੌਜੂਦਾ ਜਾਗਣ ਦੀਆਂ ਸੈਟਿੰਗਾਂ",
    "Existing wake/sleep settings": "ਮੌਜੂਦਾ ਜਾਗਣ/ਨੀਂਦ ਦੀਆਂ ਸੈਟਿੰਗਾਂ",
    "Extra apps": "ਵਾਧੂ ਐਪਾਂ",
    "Give each group its own wake-up wait and sleep time.": "ਹਰ ਗਰੁੱਪ ਨੂੰ ਉਸਦੀ ਆਪਣੀ ਜਾਗਣ ਦੀ ਉਡੀਕ ਅਤੇ ਨੀਂਦ ਦਾ ਸਮਾਂ ਦਿਓ।",
    "Limits to exclude": "ਬਾਹਰ ਰੱਖਣ ਵਾਲੀਆਂ ਹੱਦਾਂ",
    "No existing limits. You can choose apps below.": "ਕੋਈ ਮੌਜੂਦਾ ਹੱਦ ਨਹੀਂ। ਤੁਸੀਂ ਹੇਠਾਂ ਐਪਾਂ ਚੁਣ ਸਕਦੇ ਹੋ।",
    "Not selected": "ਚੁਣਿਆ ਨਹੀਂ",
    "One Wake up tap on Today starts every eligible group's wait together. Each group unlocks after its own wait; sleep blocking ends at its wake-up start time.": "ਅੱਜ ਟੈਬ ਤੇ ਇੱਕ ਜਾਗੋ ਛੂਹ ਹਰ ਯੋਗ ਗਰੁੱਪ ਦੀ ਉਡੀਕ ਇਕੱਠੇ ਸ਼ੁਰੂ ਕਰ ਦਿੰਦੀ ਹੈ। ਹਰ ਗਰੁੱਪ ਆਪਣੀ ਉਡੀਕ ਤੋਂ ਬਾਅਦ ਖੁੱਲ੍ਹਦਾ ਹੈ; ਨੀਂਦ ਦੀ ਬਲੌਕਿੰਗ ਉਸਦੇ ਜਾਗਣ ਦੀ ਸ਼ੁਰੂਆਤ ਤੇ ਮੁੱਕਦੀ ਹੈ।",
    "Only one all-other-apps fallback is allowed.": "ਸਿਰਫ਼ ਇੱਕ ਬਾਕੀ-ਸਾਰੀਆਂ-ਐਪਾਂ ਵਾਲਾ ਬਦਲ ਮਨਜ਼ੂਰ ਹੈ।",
    "Optional — add day/night groups now, or set them up later in Rules.": "ਵਿਕਲਪਿਕ — ਦਿਨ/ਰਾਤ ਗਰੁੱਪ ਹੁਣੇ ਜੋੜੋ, ਜਾਂ ਬਾਅਦ ਵਿੱਚ ਨਿਯਮ ਵਿੱਚ ਸੈੱਟ ਕਰੋ।",
    "Overlapping rules use the strictest boundary. An exception here does not bypass another group or limit.": "ਰਲਦੇ ਨਿਯਮ ਸਭ ਤੋਂ ਸਖ਼ਤ ਹੱਦ ਵਰਤਦੇ ਹਨ। ਇੱਥੇ ਦੀ ਛੋਟ ਕਿਸੇ ਹੋਰ ਗਰੁੱਪ ਜਾਂ ਹੱਦ ਨੂੰ ਪਾਰ ਨਹੀਂ ਕਰਦੀ।",
    "Remove category exceptions": "ਸ਼੍ਰੇਣੀ ਦੀਆਂ ਛੋਟਾਂ ਹਟਾਓ",
    "Remove category exceptions before saving this fallback group.": "ਇਸ ਬਦਲ ਵਾਲੇ ਗਰੁੱਪ ਨੂੰ ਸੰਭਾਲਣ ਤੋਂ ਪਹਿਲਾਂ ਸ਼੍ਰੇਣੀ ਦੀਆਂ ਛੋਟਾਂ ਹਟਾਓ।",
    "Remove day/night group?": "ਦਿਨ/ਰਾਤ ਗਰੁੱਪ ਹਟਾਉਣਾ ਹੈ?",
    "Remove group": "ਗਰੁੱਪ ਹਟਾਓ",
    "Remove missing limits": "ਗੁੰਮ ਹੱਦਾਂ ਹਟਾਓ",
    "Review these groups: choose valid apps, timings and exceptions before continuing.": "ਇਨ੍ਹਾਂ ਗਰੁੱਪਾਂ ਦੀ ਸਮੀਖਿਆ ਕਰੋ: ਅੱਗੇ ਵਧਣ ਤੋਂ ਪਹਿਲਾਂ ਠੀਕ ਐਪਾਂ, ਸਮੇਂ ਅਤੇ ਛੋਟਾਂ ਚੁਣੋ।",
    "Selected": "ਚੁਣਿਆ",
    "Selected limits and extra apps": "ਚੁਣੀਆਂ ਹੱਦਾਂ ਅਤੇ ਵਾਧੂ ਐਪਾਂ",
    "Sleep %@–%@": "ਨੀਂਦ %@–%@",
    "Some selected limits no longer exist. Remove their references before saving.": "ਕੁਝ ਚੁਣੀਆਂ ਹੱਦਾਂ ਹੁਣ ਮੌਜੂਦ ਨਹੀਂ। ਸੰਭਾਲਣ ਤੋਂ ਪਹਿਲਾਂ ਉਨ੍ਹਾਂ ਦੇ ਹਵਾਲੇ ਹਟਾਓ।",
    "The all-other-apps fallback cannot exclude whole categories used by these groups: %@. Choose individual apps instead, or remove the fallback.": "ਬਾਕੀ-ਸਾਰੀਆਂ-ਐਪਾਂ ਵਾਲਾ ਬਦਲ ਇਨ੍ਹਾਂ ਗਰੁੱਪਾਂ ਵਿੱਚ ਵਰਤੀਆਂ ਪੂਰੀਆਂ ਸ਼੍ਰੇਣੀਆਂ ਨੂੰ ਬਾਹਰ ਨਹੀਂ ਰੱਖ ਸਕਦਾ: %@। ਇਸ ਦੀ ਥਾਂ ਵੱਖਰੀਆਂ ਐਪਾਂ ਚੁਣੋ, ਜਾਂ ਬਦਲ ਹਟਾ ਦਿਓ।",
    "The fallback automatically excludes apps targeted by your other named day/night groups. Check limits and choose individual apps for additional exceptions. Other rules still apply.": "ਇਹ ਬਦਲ ਤੁਹਾਡੇ ਹੋਰ ਨਾਮ ਵਾਲੇ ਦਿਨ/ਰਾਤ ਗਰੁੱਪਾਂ ਦੀਆਂ ਐਪਾਂ ਨੂੰ ਆਪਣੇ ਆਪ ਬਾਹਰ ਰੱਖਦਾ ਹੈ। ਹੱਦਾਂ ਜਾਂਚੋ ਅਤੇ ਵਾਧੂ ਛੋਟਾਂ ਲਈ ਵੱਖਰੀਆਂ ਐਪਾਂ ਚੁਣੋ। ਹੋਰ ਨਿਯਮ ਫਿਰ ਵੀ ਲਾਗੂ ਰਹਿੰਦੇ ਹਨ।",
    "These existing settings still apply alongside your day/night groups.": "ਇਹ ਮੌਜੂਦਾ ਸੈਟਿੰਗਾਂ ਤੁਹਾਡੇ ਦਿਨ/ਰਾਤ ਗਰੁੱਪਾਂ ਦੇ ਨਾਲ ਹੀ ਲਾਗੂ ਰਹਿੰਦੀਆਂ ਹਨ।",
    "This group could not be saved. Review pending changes and your app selection, then try again.": "ਇਹ ਗਰੁੱਪ ਸੰਭਾਲਿਆ ਨਹੀਂ ਜਾ ਸਕਿਆ। ਉਡੀਕ ਵਿੱਚ ਪਈਆਂ ਤਬਦੀਲੀਆਂ ਅਤੇ ਆਪਣੀ ਐਪ ਚੋਣ ਦੇਖੋ, ਫਿਰ ਦੁਬਾਰਾ ਕੋਸ਼ਿਸ਼ ਕਰੋ।",
    "Use a name of 80 characters or fewer.": "80 ਜਾਂ ਘੱਟ ਅੱਖਰਾਂ ਦਾ ਨਾਮ ਵਰਤੋ।",
    "Wait for the pending day/night change before adding, editing or removing another group.": "ਹੋਰ ਗਰੁੱਪ ਜੋੜਨ, ਬਦਲਣ ਜਾਂ ਹਟਾਉਣ ਤੋਂ ਪਹਿਲਾਂ ਉਡੀਕ ਵਿੱਚ ਪਈ ਦਿਨ/ਰਾਤ ਦੀ ਤਬਦੀਲੀ ਦੀ ਉਡੀਕ ਕਰੋ।",
    "Wake from %@ · wait %d minutes after tap": "%@ ਤੋਂ ਜਾਗਣਾ · ਛੂਹਣ ਤੋਂ %d ਮਿੰਟ ਬਾਅਦ ਤੱਕ ਉਡੀਕ",
    "Weekdays apply to the wake-up morning and the evening when sleep begins.": "ਹਫ਼ਤੇ ਦੇ ਦਿਨ ਜਾਗਣ ਦੀ ਸਵੇਰ ਅਤੇ ਨੀਂਦ ਸ਼ੁਰੂ ਹੋਣ ਵਾਲੀ ਸ਼ਾਮ ਤੇ ਲਾਗੂ ਹੁੰਦੇ ਹਨ।",
    "You can create up to five day/night groups.": "ਤੁਸੀਂ ਪੰਜ ਤੱਕ ਦਿਨ/ਰਾਤ ਗਰੁੱਪ ਬਣਾ ਸਕਦੇ ਹੋ।",
    "e.g. Social apps at night": "ਜਿਵੇਂ ਰਾਤ ਨੂੰ ਸੋਸ਼ਲ ਐਪਾਂ",
    "Wake-up tap needed": "ਜਾਗੋ ਛੂਹਣਾ ਲੋੜੀਂਦਾ ਹੈ",
    "Wake-up could not be saved. Try again.": "ਜਾਗਣਾ ਸੰਭਾਲਿਆ ਨਹੀਂ ਜਾ ਸਕਿਆ। ਦੁਬਾਰਾ ਕੋਸ਼ਿਸ਼ ਕਰੋ।",
    "Make room for your mornings and nights.": "ਆਪਣੀਆਂ ਸਵੇਰਾਂ ਅਤੇ ਰਾਤਾਂ ਲਈ ਥਾਂ ਬਣਾਓ।",
    "Optional: choose your limit groups and extra apps, then give each day/night group its own timing. One Wake up tap starts all eligible waits.": "ਵਿਕਲਪਿਕ: ਆਪਣੇ ਹੱਦ ਗਰੁੱਪ ਅਤੇ ਵਾਧੂ ਐਪਾਂ ਚੁਣੋ, ਫਿਰ ਹਰ ਦਿਨ/ਰਾਤ ਗਰੁੱਪ ਨੂੰ ਉਸਦਾ ਆਪਣਾ ਸਮਾਂ ਦਿਓ। ਇੱਕ ਜਾਗੋ ਛੂਹ ਸਾਰੀਆਂ ਯੋਗ ਉਡੀਕਾਂ ਸ਼ੁਰੂ ਕਰ ਦਿੰਦੀ ਹੈ।",
    "Review your day/night groups after changing your limits.": "ਹੱਦਾਂ ਬਦਲਣ ਤੋਂ ਬਾਅਦ ਆਪਣੇ ਦਿਨ/ਰਾਤ ਗਰੁੱਪਾਂ ਦੀ ਸਮੀਖਿਆ ਕਰੋ।",
    "You can change this later in Rules → Day & night. Later changes follow your delays.": "ਤੁਸੀਂ ਇਸਨੂੰ ਬਾਅਦ ਵਿੱਚ ਨਿਯਮ → ਦਿਨ ਤੇ ਰਾਤ ਵਿੱਚ ਬਦਲ ਸਕਦੇ ਹੋ। ਬਾਅਦ ਦੀਆਂ ਤਬਦੀਲੀਆਂ ਤੁਹਾਡੀਆਂ ਦੇਰੀਆਂ ਮੁਤਾਬਕ ਚੱਲਦੀਆਂ ਹਨ।",
    "One Wake up tap starts all eligible groups together. Give each group its own wait and sleep time.": "ਇੱਕ ਜਾਗੋ ਛੂਹ ਸਾਰੇ ਯੋਗ ਗਰੁੱਪਾਂ ਨੂੰ ਇਕੱਠੇ ਸ਼ੁਰੂ ਕਰਦੀ ਹੈ। ਹਰ ਗਰੁੱਪ ਨੂੰ ਉਸਦੀ ਆਪਣੀ ਉਡੀਕ ਅਤੇ ਨੀਂਦ ਦਾ ਸਮਾਂ ਦਿਓ।",
    "You can add your initial day/night groups now without waiting. Existing rules and wake-up countdowns stay unchanged. Later changes follow your delays.": "ਤੁਸੀਂ ਆਪਣੇ ਸ਼ੁਰੂਆਤੀ ਦਿਨ/ਰਾਤ ਗਰੁੱਪ ਹੁਣੇ ਬਿਨਾਂ ਉਡੀਕ ਜੋੜ ਸਕਦੇ ਹੋ। ਮੌਜੂਦਾ ਨਿਯਮ ਅਤੇ ਜਾਗਣ ਦੀਆਂ ਕਾਊਂਟਡਾਊਨਾਂ ਨਹੀਂ ਬਦਲਦੀਆਂ। ਬਾਅਦ ਦੀਆਂ ਤਬਦੀਲੀਆਂ ਤੁਹਾਡੀਆਂ ਦੇਰੀਆਂ ਮੁਤਾਬਕ ਚੱਲਦੀਆਂ ਹਨ।",
    "Your day/night groups are ready.": "ਤੁਹਾਡੇ ਦਿਨ/ਰਾਤ ਗਰੁੱਪ ਤਿਆਰ ਹਨ।",
    "Add or change day/night group: %@": "ਦਿਨ/ਰਾਤ ਗਰੁੱਪ ਜੋੜੋ ਜਾਂ ਬਦਲੋ: %@",
    "Remove day/night group: %@": "ਦਿਨ/ਰਾਤ ਗਰੁੱਪ ਹਟਾਓ: %@",
    "more powerful, more intuitive": "ਵੱਧ ਤਾਕਤਵਰ, ਵੱਧ ਸਹਿਜ",
    // Wake/sleep schedules, group gates, and one-time math-to-phrase replacement.
    "Wake-up for %@: %d minutes": "%@ ਲਈ ਜਾਗਣਾ: %d ਮਿੰਟ",
    "Turn off wake-up for %@": "%@ ਲਈ ਜਾਗਣਾ ਬੰਦ ਕਰੋ",
    "Review a limit when you're ready; edits still follow your delays.": "ਜਦੋਂ ਤੁਸੀਂ ਤਿਆਰ ਹੋਵੋ ਤਾਂ ਕਿਸੇ ਹੱਦ ਦੀ ਸਮੀਖਿਆ ਕਰੋ; ਤਬਦੀਲੀਆਂ ਫਿਰ ਵੀ ਤੁਹਾਡੀਆਂ ਦੇਰੀਆਂ ਮੁਤਾਬਕ ਚੱਲਦੀਆਂ ਹਨ।",
    "Add a limit group first.": "ਪਹਿਲਾਂ ਇੱਕ ਹੱਦ ਗਰੁੱਪ ਜੋੜੋ।",
    "Add replacement phrases": "ਬਦਲਵੇਂ ਵਾਕ ਜੋੜੋ",
    "An excluded group still keeps its normal daily limit.": "ਬਾਹਰ ਰੱਖਿਆ ਗਰੁੱਪ ਫਿਰ ਵੀ ਆਪਣੀ ਆਮ ਰੋਜ਼ਾਨਾ ਹੱਦ ਰੱਖਦਾ ਹੈ।",
    "Blocking schedule": "ਬਲੌਕ ਕਰਨ ਦੀ ਸਮਾਂ-ਸਾਰਣੀ",
    "Choose what each phrase can approve. This one-time offer covers pending changes, not extra time. Later additions and edits follow your delays.": "ਚੁਣੋ ਕਿ ਹਰ ਵਾਕ ਕੀ ਮਨਜ਼ੂਰ ਕਰ ਸਕਦਾ ਹੈ। ਇਹ ਇੱਕ-ਵਾਰ ਦੀ ਪੇਸ਼ਕਸ਼ ਉਡੀਕ ਵਿੱਚ ਪਈਆਂ ਤਬਦੀਲੀਆਂ ਲਈ ਹੈ, ਵੱਧ ਸਮੇਂ ਲਈ ਨਹੀਂ। ਬਾਅਦ ਦੇ ਵਾਧੇ ਅਤੇ ਬਦਲਾਅ ਤੁਹਾਡੀਆਂ ਦੇਰੀਆਂ ਮੁਤਾਬਕ ਚੱਲਦੇ ਹਨ।",
    "Create a group in Limits & blocks first.": "ਪਹਿਲਾਂ ਹੱਦਾਂ ਤੇ ਬਲੌਕ ਵਿੱਚ ਇੱਕ ਗਰੁੱਪ ਬਣਾਓ।",
    "Day & night": "ਦਿਨ ਤੇ ਰਾਤ",
    "Days": "ਦਿਨ",
    "Enable sleep blocking": "ਨੀਂਦ ਦੀ ਬਲੌਕਿੰਗ ਚਾਲੂ ਕਰੋ",
    "Enable wake-up blocking": "ਜਾਗਣ ਦੀ ਬਲੌਕਿੰਗ ਚਾਲੂ ਕਰੋ",
    "Ends at %02d:00, when the wake-up day begins.": "%02d:00 ਤੇ ਮੁੱਕਦੀ ਹੈ, ਜਦੋਂ ਜਾਗਣ ਦਾ ਦਿਨ ਸ਼ੁਰੂ ਹੁੰਦਾ ਹੈ।",
    "Exclude limit groups from this boundary": "ਇਸ ਹੱਦ ਤੋਂ ਹੱਦ ਗਰੁੱਪ ਬਾਹਰ ਰੱਖੋ",
    "From math to phrases": "ਗਣਿਤ ਤੋਂ ਵਾਕਾਂ ਤੱਕ",
    "General blocks": "ਆਮ ਬਲੌਕ",
    "General wake-up schedule": "ਆਮ ਜਾਗਣ ਦੀ ਸਮਾਂ-ਸਾਰਣੀ",
    "Get extra time": "ਵੱਧ ਸਮਾਂ ਲਓ",
    "Give each group its own daily wake-up tap and wait. These group gates begin at midnight; the general schedule has its own start time and weekdays. If both cover an app, both waits apply.": "ਹਰ ਗਰੁੱਪ ਨੂੰ ਉਸਦੀ ਆਪਣੀ ਰੋਜ਼ਾਨਾ ਜਾਗਣ ਦੀ ਛੂਹ ਅਤੇ ਉਡੀਕ ਦਿਓ। ਇਹ ਗਰੁੱਪ ਗੇਟ ਅੱਧੀ ਰਾਤ ਨੂੰ ਸ਼ੁਰੂ ਹੁੰਦੇ ਹਨ; ਆਮ ਸਮਾਂ-ਸਾਰਣੀ ਦਾ ਆਪਣਾ ਸ਼ੁਰੂਆਤੀ ਸਮਾਂ ਅਤੇ ਹਫ਼ਤੇ ਦੇ ਦਿਨ ਹਨ। ਜੇ ਦੋਵੇਂ ਕਿਸੇ ਐਪ ਨੂੰ ਕਵਰ ਕਰਨ, ਤਾਂ ਦੋਵੇਂ ਉਡੀਕਾਂ ਲਾਗੂ ਹੁੰਦੀਆਂ ਹਨ।",
    "Group wake-up": "ਗਰੁੱਪ ਜਾਗਣਾ",
    "Group wake-up waits": "ਗਰੁੱਪ ਜਾਗਣ ਦੀਆਂ ਉਡੀਕਾਂ",
    "Hour": "ਘੰਟਾ",
    "Math problems have been replaced with phrases. Since you used math overrides, you can add replacement phrases now without waiting.": "ਗਣਿਤ ਦੇ ਸਵਾਲ ਵਾਕਾਂ ਨਾਲ ਬਦਲ ਦਿੱਤੇ ਗਏ ਹਨ। ਕਿਉਂਕਿ ਤੁਸੀਂ ਗਣਿਤ ਵਾਲੇ ਤਰੀਕੇ ਵਰਤੇ ਸਨ, ਤੁਸੀਂ ਹੁਣੇ ਬਿਨਾਂ ਉਡੀਕ ਬਦਲਵੇਂ ਵਾਕ ਜੋੜ ਸਕਦੇ ਹੋ।",
    "Minute": "ਮਿੰਟ",
    "Next use: %d usage minutes after entering %@": "ਅਗਲੀ ਵਰਤੋਂ: %2$@ ਭਰਨ ਤੋਂ ਬਾਅਦ %1$d ਵਰਤੋਂ ਮਿੰਟ",
    "Optional. After this welcome, adding phrases follows your delay settings.": "ਵਿਕਲਪਿਕ। ਇਸ ਸੁਆਗਤ ਤੋਂ ਬਾਅਦ ਵਾਕ ਜੋੜਨਾ ਤੁਹਾਡੀਆਂ ਦੇਰੀ ਸੈਟਿੰਗਾਂ ਮੁਤਾਬਕ ਚੱਲਦਾ ਹੈ।",
    "Recurring session": "ਦੁਹਰਾਉਣ ਵਾਲਾ ਸੈਸ਼ਨ",
    "Refresh": "ਤਾਜ਼ਾ ਕਰੋ",
    "See all": "ਸਭ ਦੇਖੋ",
    "Selected apps stay usable; other apps are blocked.": "ਚੁਣੀਆਂ ਐਪਾਂ ਵਰਤਣਯੋਗ ਰਹਿੰਦੀਆਂ ਹਨ; ਬਾਕੀ ਐਪਾਂ ਬਲੌਕ ਹਨ।",
    "Set the usage minutes and gate for each use. Extra time is available only after the full daily limit is spent, and resets at midnight.": "ਹਰ ਵਰਤੋਂ ਲਈ ਵਰਤੋਂ ਦੇ ਮਿੰਟ ਅਤੇ ਗੇਟ ਤੈਅ ਕਰੋ। ਵੱਧ ਸਮਾਂ ਪੂਰੀ ਰੋਜ਼ਾਨਾ ਹੱਦ ਮੁੱਕਣ ਤੋਂ ਬਾਅਦ ਹੀ ਮਿਲਦਾ ਹੈ, ਅਤੇ ਅੱਧੀ ਰਾਤ ਨੂੰ ਰੀਸੈੱਟ ਹੋ ਜਾਂਦਾ ਹੈ।",
    "Set weekday allowances. Manage wake-up and sleep in Schedules → Day & night.": "ਹਫ਼ਤੇ ਦੇ ਦਿਨਾਂ ਲਈ ਸਮਾਂ ਤੈਅ ਕਰੋ। ਜਾਗਣਾ ਅਤੇ ਨੀਂਦ ਸਮਾਂ-ਸਾਰਣੀਆਂ → ਦਿਨ ਤੇ ਰਾਤ ਵਿੱਚ ਸੰਭਾਲੋ।",
    "Sleep": "ਨੀਂਦ",
    "Sleep begins": "ਨੀਂਦ ਸ਼ੁਰੂ ਹੁੰਦੀ ਹੈ",
    "Sleep blocking ends at this time, even if the wake-up tap is off.": "ਨੀਂਦ ਦੀ ਬਲੌਕਿੰਗ ਇਸ ਸਮੇਂ ਮੁੱਕਦੀ ਹੈ, ਭਾਵੇਂ ਜਾਗਣ ਦੀ ਛੂਹ ਬੰਦ ਹੋਵੇ।",
    "The current day's wake-up countdown stays unchanged. A new wait applies to the next tap. Turning this off still waits through your less-strict delay.": "ਮੌਜੂਦਾ ਦਿਨ ਦੀ ਜਾਗਣ ਦੀ ਕਾਊਂਟਡਾਊਨ ਨਹੀਂ ਬਦਲਦੀ। ਨਵੀਂ ਉਡੀਕ ਅਗਲੀ ਛੂਹ ਤੋਂ ਲਾਗੂ ਹੁੰਦੀ ਹੈ। ਇਸਨੂੰ ਬੰਦ ਕਰਨ ਲਈ ਵੀ ਤੁਹਾਡੀ ਘੱਟ ਸਖ਼ਤ ਦੇਰੀ ਦੀ ਉਡੀਕ ਕਰਨੀ ਪੈਂਦੀ ਹੈ।",
    "This week": "ਇਹ ਹਫ਼ਤਾ",
    "Unavailable password": "ਅਣਉਪਲਬਧ ਪਾਸਵਰਡ",
    "Usage already spent, split budgets and extra-time grants are not reset by this change.": "ਇਸ ਤਬਦੀਲੀ ਨਾਲ ਵਰਤਿਆ ਜਾ ਚੁੱਕਾ ਸਮਾਂ, ਵੰਡੇ ਹਿਸਾਬ ਅਤੇ ਵੱਧ ਸਮੇਂ ਦੀਆਂ ਛੋਟਾਂ ਰੀਸੈੱਟ ਨਹੀਂ ਹੁੰਦੀਆਂ।",
    "Use these phrases now": "ਇਹ ਵਾਕ ਹੁਣੇ ਵਰਤੋ",
    "Wait": "ਉਡੀਕ",
    "Wait after tapping Wake up": "ਜਾਗੋ ਛੂਹਣ ਤੋਂ ਬਾਅਦ ਉਡੀਕ",
    "Wait for the pending wake/sleep change before editing another.": "ਕੋਈ ਹੋਰ ਬਦਲਣ ਤੋਂ ਪਹਿਲਾਂ ਉਡੀਕ ਵਿੱਚ ਪਈ ਜਾਗਣ/ਨੀਂਦ ਦੀ ਤਬਦੀਲੀ ਦੀ ਉਡੀਕ ਕਰੋ।",
    "Wait for this group's pending change before editing its wake-up wait.": "ਜਾਗਣ ਦੀ ਉਡੀਕ ਬਦਲਣ ਤੋਂ ਪਹਿਲਾਂ ਇਸ ਗਰੁੱਪ ਦੀ ਉਡੀਕ ਵਿੱਚ ਪਈ ਤਬਦੀਲੀ ਦੀ ਉਡੀਕ ਕਰੋ।",
    "Wake-up day begins": "ਜਾਗਣ ਦਾ ਦਿਨ ਸ਼ੁਰੂ ਹੁੰਦਾ ਹੈ",
    "Wake-up time must differ from when sleep begins.": "ਜਾਗਣ ਦਾ ਸਮਾਂ ਨੀਂਦ ਸ਼ੁਰੂ ਹੋਣ ਦੇ ਸਮੇਂ ਤੋਂ ਵੱਖਰਾ ਹੋਣਾ ਚਾਹੀਦਾ ਹੈ।",
    "Wake-up wait": "ਜਾਗਣ ਦੀ ਉਡੀਕ",
    "What to block": "ਕੀ ਬਲੌਕ ਕਰਨਾ ਹੈ",
    "Wrong password or this extra-time use is no longer available.": "ਗ਼ਲਤ ਪਾਸਵਰਡ ਜਾਂ ਵੱਧ ਸਮੇਂ ਦੀ ਇਹ ਵਰਤੋਂ ਹੁਣ ਉਪਲਬਧ ਨਹੀਂ।",
    "Your replacement phrases are ready.": "ਤੁਹਾਡੇ ਬਦਲਵੇਂ ਵਾਕ ਤਿਆਰ ਹਨ।",
    "block only or block except": "ਸਿਰਫ਼ ਬਲੌਕ ਜਾਂ ਇਨ੍ਹਾਂ ਤੋਂ ਇਲਾਵਾ ਬਲੌਕ",
    "iOS cannot exempt an entire app category from 'block except'; category-based groups cannot be excluded here.": "iOS ਕਿਸੇ ਪੂਰੀ ਐਪ ਸ਼੍ਰੇਣੀ ਨੂੰ 'ਇਨ੍ਹਾਂ ਤੋਂ ਇਲਾਵਾ ਬਲੌਕ' ਤੋਂ ਛੋਟ ਨਹੀਂ ਦੇ ਸਕਦਾ; ਸ਼੍ਰੇਣੀਆਂ ਵਾਲੇ ਗਰੁੱਪ ਇੱਥੇ ਬਾਹਰ ਨਹੀਂ ਰੱਖੇ ਜਾ ਸਕਦੇ।",
    "repeat a break from limits": "ਹੱਦਾਂ ਤੋਂ ਛੁੱਟੀ ਦੁਹਰਾਓ",
    "start time, weekdays, apps and default wait": "ਸ਼ੁਰੂਆਤੀ ਸਮਾਂ, ਹਫ਼ਤੇ ਦੇ ਦਿਨ, ਐਪਾਂ ਅਤੇ ਮੂਲ ਉਡੀਕ",
    // Demora 2.0: delay modes, setup, welcome, and safe recovery.
    "%d of %d": "%d ਵਿੱਚੋਂ %d",
    "A change can wait without taking away your ability to choose.": "ਤਬਦੀਲੀ ਤੁਹਾਡੀ ਚੋਣ ਦੀ ਤਾਕਤ ਖੋਹੇ ਬਿਨਾਂ ਉਡੀਕ ਕਰ ਸਕਦੀ ਹੈ।",
    "A clearer place for your intentions.": "ਤੁਹਾਡੇ ਇਰਾਦਿਆਂ ਲਈ ਇੱਕ ਸਾਫ਼ ਥਾਂ।",
    "A new layout. The same idea: your considered choices deserve time to hold.": "ਨਵੀਂ ਬਣਤਰ। ਉਹੀ ਵਿਚਾਰ: ਤੁਹਾਡੇ ਸੋਚੇ-ਵਿਚਾਰੇ ਫ਼ੈਸਲੇ ਟਿਕਣ ਲਈ ਸਮੇਂ ਦੇ ਹੱਕਦਾਰ ਹਨ।",
    "A note about older features": "ਪੁਰਾਣੀਆਂ ਸਹੂਲਤਾਂ ਬਾਰੇ ਇੱਕ ਗੱਲ",
    "A pause, on your terms.": "ਇੱਕ ਠਹਿਰਾਅ, ਤੁਹਾਡੀਆਂ ਸ਼ਰਤਾਂ ਤੇ।",
    "App color": "ਐਪ ਦਾ ਰੰਗ",
    "Blue": "ਨੀਲਾ",
    "Carried with you": "ਤੁਹਾਡੇ ਨਾਲ",
    "Change delays: %@": "ਦੇਰੀਆਂ ਬਦਲੋ: %@",
    "Changes still wait": "ਤਬਦੀਲੀਆਂ ਫਿਰ ਵੀ ਉਡੀਕ ਕਰਦੀਆਂ ਹਨ",
    "Changing your delay mode follows your current delays. Countdowns already running keep their original deadline.": "ਦੇਰੀ ਦਾ ਢੰਗ ਬਦਲਣਾ ਤੁਹਾਡੀਆਂ ਮੌਜੂਦਾ ਦੇਰੀਆਂ ਮੁਤਾਬਕ ਚੱਲਦਾ ਹੈ। ਪਹਿਲਾਂ ਹੀ ਚੱਲ ਰਹੀਆਂ ਕਾਊਂਟਡਾਊਨਾਂ ਆਪਣੀ ਅਸਲੀ ਆਖ਼ਰੀ ਤਾਰੀਖ਼ ਰੱਖਦੀਆਂ ਹਨ।",
    "Choose a delay of at least one minute.": "ਘੱਟੋ-ਘੱਟ ਇੱਕ ਮਿੰਟ ਦੀ ਦੇਰੀ ਚੁਣੋ।",
    "Choose a different wait for tightening and loosening your rules.": "ਆਪਣੇ ਨਿਯਮ ਸਖ਼ਤ ਕਰਨ ਅਤੇ ਢਿੱਲੇ ਕਰਨ ਲਈ ਵੱਖਰੀ ਉਡੀਕ ਚੁਣੋ।",
    "Choose separate waits, one shared wait, or a wait only when loosening rules.": "ਵੱਖਰੀਆਂ ਉਡੀਕਾਂ, ਇੱਕ ਸਾਂਝੀ ਉਡੀਕ, ਜਾਂ ਸਿਰਫ਼ ਨਿਯਮ ਢਿੱਲੇ ਕਰਨ ਵੇਲੇ ਉਡੀਕ ਚੁਣੋ।",
    "Choose what each trusted contact can approve, instead of giving everyone the same permissions.": "ਸਭ ਨੂੰ ਇੱਕੋ ਜਿਹੀਆਂ ਇਜਾਜ਼ਤਾਂ ਦੇਣ ਦੀ ਥਾਂ, ਚੁਣੋ ਕਿ ਹਰ ਭਰੋਸੇਯੋਗ ਸੰਪਰਕ ਕੀ ਮਨਜ਼ੂਰ ਕਰ ਸਕਦਾ ਹੈ।",
    "Choose your boundaries now. Give yourself time before changing them later.": "ਹੁਣੇ ਆਪਣੀਆਂ ਹੱਦਾਂ ਚੁਣੋ। ਬਾਅਦ ਵਿੱਚ ਉਨ੍ਹਾਂ ਨੂੰ ਬਦਲਣ ਤੋਂ ਪਹਿਲਾਂ ਆਪਣੇ ਆਪ ਨੂੰ ਸਮਾਂ ਦਿਓ।",
    "Daily allowance": "ਰੋਜ਼ਾਨਾ ਸਮਾਂ",
    "Daily allowance: %d min": "ਰੋਜ਼ਾਨਾ ਸਮਾਂ: %d ਮਿੰਟ",
    "Daily boundaries in Limits. Recurring and planned time in Schedules.": "ਰੋਜ਼ਾਨਾ ਹੱਦਾਂ ਹੱਦਾਂ ਵਿੱਚ। ਦੁਹਰਾਉਣ ਵਾਲਾ ਅਤੇ ਯੋਜਨਾਬੱਧ ਸਮਾਂ ਸਮਾਂ-ਸਾਰਣੀਆਂ ਵਿੱਚ।",
    "Decide with a clear head": "ਸਾਫ਼ ਦਿਮਾਗ਼ ਨਾਲ ਫ਼ੈਸਲਾ ਕਰੋ",
    "Delay for every change": "ਹਰ ਤਬਦੀਲੀ ਲਈ ਦੇਰੀ",
    "Demora 2.0": "Demora 2.0",
    "Demora could not finish reading or backing up your saved setup. Nothing has been reset. Try again, or contact hello@getdemora.app before reinstalling.": "Demora ਤੁਹਾਡਾ ਸੰਭਾਲਿਆ ਸੈੱਟਅੱਪ ਪੜ੍ਹਨਾ ਜਾਂ ਉਸਦਾ ਬੈਕਅੱਪ ਲੈਣਾ ਪੂਰਾ ਨਹੀਂ ਕਰ ਸਕਿਆ। ਕੁਝ ਵੀ ਰੀਸੈੱਟ ਨਹੀਂ ਹੋਇਆ। ਦੁਬਾਰਾ ਕੋਸ਼ਿਸ਼ ਕਰੋ, ਜਾਂ ਮੁੜ ਇੰਸਟਾਲ ਕਰਨ ਤੋਂ ਪਹਿਲਾਂ hello@getdemora.app ਨਾਲ ਸੰਪਰਕ ਕਰੋ।",
    "Different days, different budgets": "ਵੱਖ-ਵੱਖ ਦਿਨ, ਵੱਖ-ਵੱਖ ਸਮਾਂ",
    "Edit your selection": "ਆਪਣੀ ਚੋਣ ਬਦਲੋ",
    "Editing override permissions follows your delays. This welcome doesn't change them.": "ਉਡੀਕ ਛੱਡਣ ਦੀਆਂ ਇਜਾਜ਼ਤਾਂ ਬਦਲਣਾ ਤੁਹਾਡੀਆਂ ਦੇਰੀਆਂ ਮੁਤਾਬਕ ਚੱਲਦਾ ਹੈ। ਇਹ ਸੁਆਗਤ ਉਨ੍ਹਾਂ ਨੂੰ ਨਹੀਂ ਬਦਲਦਾ।",
    "Every change": "ਹਰ ਤਬਦੀਲੀ",
    "Existing contacts keep their pending-change permissions. They don't automatically gain extra-time access.": "ਮੌਜੂਦਾ ਸੰਪਰਕ ਆਪਣੀਆਂ ਉਡੀਕ-ਵਿੱਚ-ਤਬਦੀਲੀ ਦੀਆਂ ਇਜਾਜ਼ਤਾਂ ਰੱਖਦੇ ਹਨ। ਉਨ੍ਹਾਂ ਨੂੰ ਵੱਧ ਸਮੇਂ ਦੀ ਪਹੁੰਚ ਆਪਣੇ ਆਪ ਨਹੀਂ ਮਿਲਦੀ।",
    "Extra time with intention": "ਸੋਚ-ਸਮਝ ਕੇ ਵੱਧ ਸਮਾਂ",
    "Free. No account, ads, or analytics. Your app choices and usage stay on your device.": "ਮੁਫ਼ਤ। ਕੋਈ ਖਾਤਾ, ਇਸ਼ਤਿਹਾਰ ਜਾਂ ਐਨਾਲਿਟਿਕਸ ਨਹੀਂ। ਤੁਹਾਡੀਆਂ ਐਪਾਂ ਦੀ ਚੋਣ ਅਤੇ ਵਰਤੋਂ ਤੁਹਾਡੇ ਡਿਵਾਈਸ ਤੇ ਹੀ ਰਹਿੰਦੀ ਹੈ।",
    "Give your day a little shape.": "ਆਪਣੇ ਦਿਨ ਨੂੰ ਥੋੜ੍ਹੀ ਸ਼ਕਲ ਦਿਓ।",
    "How changes wait": "ਤਬਦੀਲੀਆਂ ਕਿਵੇਂ ਉਡੀਕਦੀਆਂ ਹਨ",
    "Immediately": "ਤੁਰੰਤ",
    "Keep a simple daily allowance, or make a limit fit the way your day unfolds.": "ਸਾਦਾ ਰੋਜ਼ਾਨਾ ਸਮਾਂ ਰੱਖੋ, ਜਾਂ ਹੱਦ ਨੂੰ ਆਪਣੇ ਦਿਨ ਦੇ ਢੰਗ ਮੁਤਾਬਕ ਢਾਲੋ।",
    "Keep separate waits, use one shared wait, or wait only when loosening rules. Your current delay mode and durations stay unchanged.": "ਵੱਖਰੀਆਂ ਉਡੀਕਾਂ ਰੱਖੋ, ਇੱਕ ਸਾਂਝੀ ਉਡੀਕ ਵਰਤੋ, ਜਾਂ ਸਿਰਫ਼ ਨਿਯਮ ਢਿੱਲੇ ਕਰਨ ਵੇਲੇ ਉਡੀਕੋ। ਤੁਹਾਡਾ ਮੌਜੂਦਾ ਦੇਰੀ ਢੰਗ ਅਤੇ ਮਿਆਦਾਂ ਨਹੀਂ ਬਦਲਦੇ।",
    "Language & appearance": "ਭਾਸ਼ਾ ਤੇ ਦਿੱਖ",
    "Legacy usage-burst pacing and math overrides have been removed. Daily limits remain. Split budgets and extra-time steps are optional alternatives, not automatic replacements.": "ਪੁਰਾਣੀ ਵਰਤੋਂ-ਧਮਾਕੇ ਦੀ ਗਤੀ ਅਤੇ ਗਣਿਤ ਵਾਲੇ ਤਰੀਕੇ ਹਟਾ ਦਿੱਤੇ ਗਏ ਹਨ। ਰੋਜ਼ਾਨਾ ਹੱਦਾਂ ਕਾਇਮ ਹਨ। ਵੰਡੇ ਸਮੇਂ ਅਤੇ ਵੱਧ ਸਮੇਂ ਦੇ ਕਦਮ ਵਿਕਲਪਿਕ ਬਦਲ ਹਨ, ਆਪਣੇ ਆਪ ਵਾਲੇ ਬਦਲ ਨਹੀਂ।",
    "Let the impulse pass": "ਇੱਛਾ ਨੂੰ ਲੰਘ ਜਾਣ ਦਿਓ",
    "Limit name": "ਹੱਦ ਦਾ ਨਾਮ",
    "Limits & schedules": "ਹੱਦਾਂ ਤੇ ਸਮਾਂ-ਸਾਰਣੀਆਂ",
    "Make room for what matters.": "ਜੋ ਜ਼ਰੂਰੀ ਹੈ ਉਸ ਲਈ ਥਾਂ ਬਣਾਓ।",
    "More-strict changes apply immediately.": "ਵੱਧ ਸਖ਼ਤ ਤਬਦੀਲੀਆਂ ਤੁਰੰਤ ਲਾਗੂ ਹੁੰਦੀਆਂ ਹਨ।",
    "My first limit": "ਮੇਰੀ ਪਹਿਲੀ ਹੱਦ",
    "No limit yet. Add one whenever you're ready in Limits & blocks.": "ਅਜੇ ਕੋਈ ਹੱਦ ਨਹੀਂ। ਜਦੋਂ ਚਾਹੋ ਹੱਦਾਂ ਤੇ ਬਲੌਕ ਵਿੱਚ ਇੱਕ ਜੋੜੋ।",
    "No silent new permissions": "ਚੁੱਪ-ਚਾਪ ਕੋਈ ਨਵੀਂ ਇਜਾਜ਼ਤ ਨਹੀਂ",
