    "One delay for all changes": "ਸਭ ਤਬਦੀਲੀਆਂ ਲਈ ਇੱਕ ਦੇਰੀ",
    "One wait for all changes: %@": "ਸਭ ਤਬਦੀਲੀਆਂ ਲਈ ਇੱਕ ਉਡੀਕ: %@",
    "Only less-strict changes wait": "ਸਿਰਫ਼ ਘੱਟ ਸਖ਼ਤ ਤਬਦੀਲੀਆਂ ਉਡੀਕਦੀਆਂ ਹਨ",
    "Open my limits": "ਮੇਰੀਆਂ ਹੱਦਾਂ ਖੋਲ੍ਹੋ",
    "Optional: choose an app or a group and a daily allowance. This will be a real limit, not a demo.": "ਵਿਕਲਪਿਕ: ਇੱਕ ਐਪ ਜਾਂ ਗਰੁੱਪ ਅਤੇ ਰੋਜ਼ਾਨਾ ਸਮਾਂ ਚੁਣੋ। ਇਹ ਅਸਲੀ ਹੱਦ ਹੋਵੇਗੀ, ਡੈਮੋ ਨਹੀਂ।",
    "Permission by person": "ਵਿਅਕਤੀ ਮੁਤਾਬਕ ਇਜਾਜ਼ਤ",
    "Plan ordered extra-time steps, each with its own wait or approval method.": "ਵੱਧ ਸਮੇਂ ਦੇ ਕ੍ਰਮਵਾਰ ਕਦਮ ਬਣਾਓ, ਹਰ ਇੱਕ ਦੀ ਆਪਣੀ ਉਡੀਕ ਜਾਂ ਮਨਜ਼ੂਰੀ ਦਾ ਤਰੀਕਾ।",
    "Planned windows": "ਯੋਜਨਾਬੱਧ ਸਮਾਂ",
    "Red": "ਲਾਲ",
    "Scope approvals to the pending changes you choose. Extra-time approval is a separate opt-in.": "ਮਨਜ਼ੂਰੀਆਂ ਨੂੰ ਤੁਹਾਡੀਆਂ ਚੁਣੀਆਂ ਉਡੀਕ-ਵਿੱਚ-ਤਬਦੀਲੀਆਂ ਤੱਕ ਸੀਮਤ ਕਰੋ। ਵੱਧ ਸਮੇਂ ਦੀ ਮਨਜ਼ੂਰੀ ਵੱਖਰੀ ਮਰਜ਼ੀ ਦੀ ਚੋਣ ਹੈ।",
    "See what's active, what's next, and which changes are waiting.": "ਦੇਖੋ ਕੀ ਚੱਲ ਰਿਹਾ ਹੈ, ਅੱਗੇ ਕੀ ਹੈ, ਅਤੇ ਕਿਹੜੀਆਂ ਤਬਦੀਲੀਆਂ ਉਡੀਕ ਵਿੱਚ ਹਨ।",
    "Set a limit later": "ਹੱਦ ਬਾਅਦ ਵਿੱਚ ਤੈਅ ਕਰੋ",
    "Set limits for an app or a group, and plan time away.": "ਕਿਸੇ ਐਪ ਜਾਂ ਗਰੁੱਪ ਲਈ ਹੱਦਾਂ ਤੈਅ ਕਰੋ, ਅਤੇ ਦੂਰ ਰਹਿਣ ਦਾ ਸਮਾਂ ਬਣਾਓ।",
    "Set weekday allowances and an optional wake-up wait.": "ਹਫ਼ਤੇ ਦੇ ਦਿਨਾਂ ਲਈ ਸਮਾਂ ਅਤੇ ਵਿਕਲਪਿਕ ਜਾਗਣ ਦੀ ਉਡੀਕ ਤੈਅ ਕਰੋ।",
    "Setup couldn't be saved": "ਸੈੱਟਅੱਪ ਸੰਭਾਲਿਆ ਨਹੀਂ ਜਾ ਸਕਿਆ",
    "Split an allowance across your day, with optional carryover.": "ਸਮੇਂ ਨੂੰ ਆਪਣੇ ਦਿਨ ਵਿੱਚ ਵੰਡੋ, ਅਣਵਰਤਿਆ ਅੱਗੇ ਲਿਜਾਣ ਦੇ ਵਿਕਲਪ ਨਾਲ।",
    "Start with one boundary.": "ਇੱਕ ਹੱਦ ਨਾਲ ਸ਼ੁਰੂ ਕਰੋ।",
    "Step %d of %d": "ਕਦਮ %d ਵਿੱਚੋਂ %d",
    "The same wait applies whether you tighten or loosen a rule.": "ਨਿਯਮ ਸਖ਼ਤ ਕਰੋ ਜਾਂ ਢਿੱਲਾ, ਉਹੀ ਉਡੀਕ ਲਾਗੂ ਹੁੰਦੀ ਹੈ।",
    "The selected apps share this allowance. You can fine-tune it later in Limits & blocks.": "ਚੁਣੀਆਂ ਐਪਾਂ ਇਹ ਸਮਾਂ ਸਾਂਝਾ ਵਰਤਦੀਆਂ ਹਨ। ਤੁਸੀਂ ਇਸਨੂੰ ਬਾਅਦ ਵਿੱਚ ਹੱਦਾਂ ਤੇ ਬਲੌਕ ਵਿੱਚ ਬਾਰੀਕੀ ਨਾਲ ਬਦਲ ਸਕਦੇ ਹੋ।",
    "These are your starting settings. Later changes to rules and delay settings follow your delay policy.": "ਇਹ ਤੁਹਾਡੀਆਂ ਸ਼ੁਰੂਆਤੀ ਸੈਟਿੰਗਾਂ ਹਨ। ਨਿਯਮਾਂ ਅਤੇ ਦੇਰੀ ਸੈਟਿੰਗਾਂ ਦੀਆਂ ਬਾਅਦ ਦੀਆਂ ਤਬਦੀਲੀਆਂ ਤੁਹਾਡੀ ਦੇਰੀ ਦੀ ਨੀਤੀ ਮੁਤਾਬਕ ਚੱਲਦੀਆਂ ਹਨ।",
    "This limit will be saved when you start. Your initial setup doesn't need to wait.": "ਇਹ ਹੱਦ ਤੁਹਾਡੇ ਸ਼ੁਰੂ ਕਰਨ ਤੇ ਸੰਭਾਲੀ ਜਾਵੇਗੀ। ਤੁਹਾਡੇ ਸ਼ੁਰੂਆਤੀ ਸੈੱਟਅੱਪ ਨੂੰ ਉਡੀਕ ਕਰਨ ਦੀ ਲੋੜ ਨਹੀਂ।",
    "Three ways to wait": "ਉਡੀਕ ਦੇ ਤਿੰਨ ਤਰੀਕੇ",
    "Tighten a rule immediately. Loosening it still waits.": "ਨਿਯਮ ਤੁਰੰਤ ਸਖ਼ਤ ਕਰੋ। ਉਸਨੂੰ ਢਿੱਲਾ ਕਰਨ ਲਈ ਫਿਰ ਵੀ ਉਡੀਕਣਾ ਪੈਂਦਾ ਹੈ।",
    "Tightening is immediate · Loosening: %@": "ਸਖ਼ਤ ਕਰਨਾ ਤੁਰੰਤ · ਢਿੱਲਾ ਕਰਨਾ: %@",
    "Tightening: %@ · Loosening: %@": "ਸਖ਼ਤ ਕਰਨਾ: %@ · ਢਿੱਲਾ ਕਰਨਾ: %@",
    "Trust, with clear boundaries.": "ਭਰੋਸਾ, ਸਾਫ਼ ਹੱਦਾਂ ਨਾਲ।",
    "Try again": "ਦੁਬਾਰਾ ਕੋਸ਼ਿਸ਼ ਕਰੋ",
    "Two delays": "ਦੋ ਦੇਰੀਆਂ",
    "Want a practice run? The optional walkthrough and extra safeguards are in Settings → Help.": "ਅਭਿਆਸ ਕਰਨਾ ਚਾਹੁੰਦੇ ਹੋ? ਵਿਕਲਪਿਕ ਵਾਕਥਰੂ ਅਤੇ ਵਾਧੂ ਸੁਰੱਖਿਆਵਾਂ ਸੈਟਿੰਗਾਂ → ਮਦਦ ਵਿੱਚ ਹਨ।",
    "Welcome back": "ਮੁੜ ਜੀ ਆਇਆਂ",
    "You can add a limit after enabling Screen Time access. For now, continue without one.": "ਸਕ੍ਰੀਨ ਟਾਈਮ ਦੀ ਪਹੁੰਚ ਚਾਲੂ ਕਰਨ ਤੋਂ ਬਾਅਦ ਤੁਸੀਂ ਹੱਦ ਜੋੜ ਸਕਦੇ ਹੋ। ਹੁਣ ਲਈ ਇਸਦੇ ਬਿਨਾਂ ਅੱਗੇ ਵਧੋ।",
    "You're ready. Your rules are still yours.": "ਤੁਸੀਂ ਤਿਆਰ ਹੋ। ਤੁਹਾਡੇ ਨਿਯਮ ਅਜੇ ਵੀ ਤੁਹਾਡੇ ਹੀ ਹਨ।",
    "Your choices are still here. Please try again.": "ਤੁਹਾਡੀਆਂ ਚੋਣਾਂ ਅਜੇ ਇੱਥੇ ਹੀ ਹਨ। ਕਿਰਪਾ ਕਰਕੇ ਦੁਬਾਰਾ ਕੋਸ਼ਿਸ਼ ਕਰੋ।",
    "Your delay policy": "ਤੁਹਾਡੀ ਦੇਰੀ ਦੀ ਨੀਤੀ",
    "Your next chapter.": "ਤੁਹਾਡਾ ਅਗਲਾ ਪੜਾਅ।",
    "Your saved rules and pending changes are retained. Your existing delay settings are unchanged.": "ਤੁਹਾਡੇ ਸੰਭਾਲੇ ਨਿਯਮ ਅਤੇ ਉਡੀਕ ਵਿੱਚ ਪਈਆਂ ਤਬਦੀਲੀਆਂ ਕਾਇਮ ਹਨ। ਤੁਹਾਡੀਆਂ ਮੌਜੂਦਾ ਦੇਰੀ ਸੈਟਿੰਗਾਂ ਨਹੀਂ ਬਦਲੀਆਂ।",
    "Your setup is safe": "ਤੁਹਾਡਾ ਸੈੱਟਅੱਪ ਸੁਰੱਖਿਅਤ ਹੈ",
    "Your waits and trusted contacts now have their own place.": "ਤੁਹਾਡੀਆਂ ਉਡੀਕਾਂ ਅਤੇ ਭਰੋਸੇਯੋਗ ਸੰਪਰਕਾਂ ਨੂੰ ਹੁਣ ਆਪਣੀ ਵੱਖਰੀ ਥਾਂ ਮਿਲ ਗਈ ਹੈ।",
