    // Per-contact approval permissions and schedule app editing.
    "All pending changes": "ਉਡੀਕ ਵਿੱਚ ਪਈਆਂ ਸਾਰੀਆਂ ਤਬਦੀਲੀਆਂ",
    "None": "ਕੋਈ ਨਹੀਂ",
    "Edit": "ਬਦਲੋ",
    "This contact must confirm before they can approve.": "ਇਸ ਸੰਪਰਕ ਨੂੰ ਮਨਜ਼ੂਰੀ ਦੇਣ ਤੋਂ ਪਹਿਲਾਂ ਪੁਸ਼ਟੀ ਕਰਨੀ ਪਵੇਗੀ।",
    "Queued": "ਕਤਾਰ ਵਿੱਚ",
    "Changing apps, categories, or websites always uses the less-strict delay. The current schedule stays in effect until the change applies.": "ਐਪਾਂ, ਸ਼੍ਰੇਣੀਆਂ ਜਾਂ ਵੈੱਬਸਾਈਟਾਂ ਬਦਲਣ ਲਈ ਹਮੇਸ਼ਾ ਘੱਟ ਸਖ਼ਤ ਦੇਰੀ ਵਰਤੀ ਜਾਂਦੀ ਹੈ। ਤਬਦੀਲੀ ਲੱਗਣ ਤੱਕ ਮੌਜੂਦਾ ਸਮਾਂ-ਸਾਰਣੀ ਲਾਗੂ ਰਹਿੰਦੀ ਹੈ।",
    "Limit changes": "ਹੱਦ ਦੀਆਂ ਤਬਦੀਲੀਆਂ",
    "Schedule changes": "ਸਮਾਂ-ਸਾਰਣੀ ਦੀਆਂ ਤਬਦੀਲੀਆਂ",
    "Session changes": "ਸੈਸ਼ਨ ਦੀਆਂ ਤਬਦੀਲੀਆਂ",
    "Delay changes": "ਦੇਰੀ ਦੀਆਂ ਤਬਦੀਲੀਆਂ",
    "Protection changes": "ਸੁਰੱਖਿਆ ਦੀਆਂ ਤਬਦੀਲੀਆਂ",
    "Contact changes": "ਸੰਪਰਕ ਦੀਆਂ ਤਬਦੀਲੀਆਂ",
    "Waiting for a trusted contact": "ਭਰੋਸੇਯੋਗ ਸੰਪਰਕ ਦੀ ਉਡੀਕ",
    "Trusted-contact approvals are turned off.": "ਭਰੋਸੇਯੋਗ ਸੰਪਰਕ ਦੀਆਂ ਮਨਜ਼ੂਰੀਆਂ ਬੰਦ ਹਨ।",
    "Next use: %d usage minutes after contact approval": "ਅਗਲੀ ਵਰਤੋਂ: ਸੰਪਰਕ ਦੀ ਮਨਜ਼ੂਰੀ ਤੋਂ ਬਾਅਦ %d ਵਰਤੋਂ ਮਿੰਟ",
    "Extra time for %@: %d usage minutes": "%@ ਲਈ ਵੱਧ ਸਮਾਂ: %d ਵਰਤੋਂ ਮਿੰਟ",
    "Cancel and start again": "ਰੱਦ ਕਰੋ ਤੇ ਦੁਬਾਰਾ ਸ਼ੁਰੂ ਕਰੋ",
    "Cancel this request, then reopen extra time to choose contacts again.": "ਇਹ ਬੇਨਤੀ ਰੱਦ ਕਰੋ, ਫਿਰ ਸੰਪਰਕ ਦੁਬਾਰਾ ਚੁਣਨ ਲਈ ਵੱਧ ਸਮਾਂ ਮੁੜ ਖੋਲ੍ਹੋ।",
    "This contact approval could not grant extra time. Cancel and try again.": "ਇਸ ਸੰਪਰਕ ਦੀ ਮਨਜ਼ੂਰੀ ਵੱਧ ਸਮਾਂ ਨਹੀਂ ਦੇ ਸਕੀ। ਰੱਦ ਕਰਕੇ ਦੁਬਾਰਾ ਕੋਸ਼ਿਸ਼ ਕਰੋ।",
    "Phrases": "ਵਾਕ",
    "Phrase type": "ਵਾਕ ਦੀ ਕਿਸਮ",
    "Random words": "ਬੇਤਰਤੀਬ ਸ਼ਬਦ",
    "Custom phrase": "ਆਪਣਾ ਵਾਕ",
    "Words": "ਸ਼ਬਦ",
    "%d words": "%d ਸ਼ਬਦ",
    "Wrong words before reset": "ਰੀਸੈੱਟ ਤੋਂ ਪਹਿਲਾਂ ਗ਼ਲਤ ਸ਼ਬਦ",
    "Unlimited": "ਬੇਹੱਦ",
    "Add phrase": "ਵਾਕ ਜੋੜੋ",
    "Edit phrase": "ਵਾਕ ਬਦਲੋ",
    "Remove phrase": "ਵਾਕ ਹਟਾਓ",
    "Add or change phrase: %@": "ਵਾਕ ਜੋੜੋ ਜਾਂ ਬਦਲੋ: %@",
    "Remove phrase: %@": "ਵਾਕ ਹਟਾਓ: %@",
    "phrase": "ਵਾਕ",
    "The exact custom phrase is saved on this device. Choose something you would not type impulsively.": "ਸਹੀ ਆਪਣਾ ਵਾਕ ਇਸ ਡਿਵਾਈਸ ਤੇ ਸੰਭਾਲਿਆ ਜਾਂਦਾ ਹੈ। ਅਜਿਹਾ ਕੁਝ ਚੁਣੋ ਜੋ ਤੁਸੀਂ ਜੋਸ਼ ਵਿੱਚ ਨਾ ਲਿਖੋ।",
    "Word %d of %d": "ਸ਼ਬਦ %d ਵਿੱਚੋਂ %d",
    "Mistakes: %d": "ਗ਼ਲਤੀਆਂ: %d",
    "Type the highlighted word": "ਚਮਕਦਾਰ ਸ਼ਬਦ ਲਿਖੋ",
    "Check word": "ਸ਼ਬਦ ਜਾਂਚੋ",
    "That word was incorrect. Try again.": "ਉਹ ਸ਼ਬਦ ਗ਼ਲਤ ਸੀ। ਦੁਬਾਰਾ ਕੋਸ਼ਿਸ਼ ਕਰੋ।",
    "Too many mistakes. Start again.": "ਬਹੁਤ ਗ਼ਲਤੀਆਂ। ਦੁਬਾਰਾ ਸ਼ੁਰੂ ਕਰੋ।",
    "Phrase unavailable. Close this screen and try again.": "ਵਾਕ ਉਪਲਬਧ ਨਹੀਂ। ਇਹ ਸਕ੍ਰੀਨ ਬੰਦ ਕਰਕੇ ਦੁਬਾਰਾ ਕੋਸ਼ਿਸ਼ ਕਰੋ।",
    "This change is no longer available. Please try again.": "ਇਹ ਤਬਦੀਲੀ ਹੁਣ ਉਪਲਬਧ ਨਹੀਂ। ਕਿਰਪਾ ਕਰਕੇ ਦੁਬਾਰਾ ਕੋਸ਼ਿਸ਼ ਕਰੋ।",
    "Type every word to receive this use of extra time.": "ਵੱਧ ਸਮੇਂ ਦੀ ਇਹ ਵਰਤੋਂ ਲੈਣ ਲਈ ਹਰ ਸ਼ਬਦ ਲਿਖੋ।",
    "This extra-time use is no longer available.": "ਵੱਧ ਸਮੇਂ ਦੀ ਇਹ ਵਰਤੋਂ ਹੁਣ ਉਪਲਬਧ ਨਹੀਂ।",
    "Unavailable phrase": "ਅਣਉਪਲਬਧ ਵਾਕ",
    "Next use: %d usage minutes after typing %@": "ਅਗਲੀ ਵਰਤੋਂ: %2$@ ਲਿਖਣ ਤੋਂ ਬਾਅਦ %1$d ਵਰਤੋਂ ਮਿੰਟ",
    "Approval permissions": "ਮਨਜ਼ੂਰੀ ਦੀਆਂ ਇਜਾਜ਼ਤਾਂ",
    "Change trusted-contact permissions: %@": "ਭਰੋਸੇਯੋਗ ਸੰਪਰਕ ਦੀਆਂ ਇਜਾਜ਼ਤਾਂ ਬਦਲੋ: %@",
    "This contact can no longer approve these changes. Send a new request.": "ਇਹ ਸੰਪਰਕ ਹੁਣ ਇਨ੍ਹਾਂ ਤਬਦੀਲੀਆਂ ਨੂੰ ਮਨਜ਼ੂਰ ਨਹੀਂ ਕਰ ਸਕਦਾ। ਨਵੀਂ ਬੇਨਤੀ ਭੇਜੋ।",
    "Today's limits": "ਅੱਜ ਦੀਆਂ ਹੱਦਾਂ",
    "View usage": "ਵਰਤੋਂ ਦੇਖੋ",
    "Active sessions": "ਚਾਲੂ ਸੈਸ਼ਨ",
    "Limits & blocks": "ਹੱਦਾਂ ਤੇ ਬਲੌਕ",
    "Your limits": "ਤੁਹਾਡੀਆਂ ਹੱਦਾਂ",
    "More blocking tools": "ਹੋਰ ਬਲੌਕ ਕਰਨ ਦੇ ਸਾਧਨ",
    "App & website blocking": "ਐਪ ਤੇ ਵੈੱਬਸਾਈਟ ਬਲੌਕਿੰਗ",
    "deletion, adult sites, custom domains": "ਮਿਟਾਉਣਾ, ਬਾਲਗ ਸਾਈਟਾਂ, ਆਪਣੇ ਡੋਮੇਨ",
    "Delays & overrides": "ਦੇਰੀਆਂ ਤੇ ਛੋਟਾਂ",
    "Your rules can change—just not in the moment.": "ਤੁਹਾਡੇ ਨਿਯਮ ਬਦਲ ਸਕਦੇ ਹਨ — ਬੱਸ ਉਸੇ ਪਲ ਨਹੀਂ।",
    "Only someone you trust can approve skipping a pending change's wait.": "ਸਿਰਫ਼ ਕੋਈ ਭਰੋਸੇਯੋਗ ਵਿਅਕਤੀ ਹੀ ਉਡੀਕ ਵਿੱਚ ਪਈ ਤਬਦੀਲੀ ਦੀ ਉਡੀਕ ਛੱਡਣ ਨੂੰ ਮਨਜ਼ੂਰ ਕਰ ਸਕਦਾ ਹੈ।",
    "Three time portions": "ਸਮੇਂ ਦੇ ਤਿੰਨ ਹਿੱਸੇ",
    "First cutoff": "ਪਹਿਲਾ ਕਟਆਫ਼",
    "Second cutoff": "ਦੂਜਾ ਕਟਆਫ਼",
    "First portion: %d minutes": "ਪਹਿਲਾ ਹਿੱਸਾ: %d ਮਿੰਟ",
    "Middle portion: %d minutes": "ਵਿਚਕਾਰਲਾ ਹਿੱਸਾ: %d ਮਿੰਟ",
    "Final portion: %d minutes": "ਆਖ਼ਰੀ ਹਿੱਸਾ: %d ਮਿੰਟ",
    "Divide today's usage into time-of-day portions. Unused minutes can carry into later portions if you choose.": "ਅੱਜ ਦੀ ਵਰਤੋਂ ਨੂੰ ਦਿਨ ਦੇ ਹਿੱਸਿਆਂ ਵਿੱਚ ਵੰਡੋ। ਚਾਹੋ ਤਾਂ ਅਣਵਰਤੇ ਮਿੰਟ ਬਾਅਦ ਦੇ ਹਿੱਸਿਆਂ ਵਿੱਚ ਜਾ ਸਕਦੇ ਹਨ।",
    "Manual extra time": "ਹੱਥੀਂ ਵੱਧ ਸਮਾਂ",
    "A limit is a daily usage budget for selected apps or categories. When it runs out, those apps are blocked until midnight.": "ਹੱਦ ਚੁਣੀਆਂ ਐਪਾਂ ਜਾਂ ਸ਼੍ਰੇਣੀਆਂ ਦਾ ਰੋਜ਼ਾਨਾ ਵਰਤੋਂ ਦਾ ਸਮਾਂ ਹੈ। ਇਹ ਮੁੱਕ ਜਾਵੇ ਤਾਂ ਉਹ ਐਪਾਂ ਅੱਧੀ ਰਾਤ ਤੱਕ ਬਲੌਕ ਰਹਿੰਦੀਆਂ ਹਨ।",
    "Home shows today's Screen Time usage. Limits & Blocks lists your configured limits; tap one to see its apps and categories. Usage from before you created a limit still counts that day. Raising or removing a limit is less strict; adding one or lowering its minutes is stricter.": "ਹੋਮ ਅੱਜ ਦੀ ਸਕ੍ਰੀਨ ਟਾਈਮ ਵਰਤੋਂ ਦਿਖਾਉਂਦਾ ਹੈ। ਹੱਦਾਂ ਤੇ ਬਲੌਕ ਤੁਹਾਡੀਆਂ ਤੈਅ ਕੀਤੀਆਂ ਹੱਦਾਂ ਦੱਸਦਾ ਹੈ; ਕਿਸੇ ਨੂੰ ਛੂਹ ਕੇ ਉਸਦੀਆਂ ਐਪਾਂ ਅਤੇ ਸ਼੍ਰੇਣੀਆਂ ਦੇਖੋ। ਹੱਦ ਬਣਾਉਣ ਤੋਂ ਪਹਿਲਾਂ ਦੀ ਵਰਤੋਂ ਵੀ ਉਸ ਦਿਨ ਗਿਣੀ ਜਾਂਦੀ ਹੈ। ਹੱਦ ਵਧਾਉਣਾ ਜਾਂ ਹਟਾਉਣਾ ਘੱਟ ਸਖ਼ਤ ਹੈ; ਇੱਕ ਜੋੜਨਾ ਜਾਂ ਮਿੰਟ ਘਟਾਉਣਾ ਵੱਧ ਸਖ਼ਤ ਹੈ।",
    "Use %d": "ਵਰਤੋਂ %d",
    "Extra usage: %d minutes": "ਵਾਧੂ ਵਰਤੋਂ: %d ਮਿੰਟ",
    "Wait: %d minutes": "ਉਡੀਕ: %d ਮਿੰਟ",
    "Add another use": "ਇੱਕ ਹੋਰ ਵਰਤੋਂ ਜੋੜੋ",
    "Set the usage minutes and wait for each use. Extra time is available only after the full daily limit is spent, and resets at midnight.": "ਹਰ ਵਰਤੋਂ ਲਈ ਵਰਤੋਂ ਦੇ ਮਿੰਟ ਅਤੇ ਉਡੀਕ ਤੈਅ ਕਰੋ। ਵੱਧ ਸਮਾਂ ਪੂਰੀ ਰੋਜ਼ਾਨਾ ਹੱਦ ਮੁੱਕਣ ਤੋਂ ਬਾਅਦ ਹੀ ਮਿਲਦਾ ਹੈ, ਅਤੇ ਅੱਧੀ ਰਾਤ ਨੂੰ ਰੀਸੈੱਟ ਹੋ ਜਾਂਦਾ ਹੈ।",
    "Next use: %d usage minutes after a %d-minute wait": "ਅਗਲੀ ਵਰਤੋਂ: %d ਮਿੰਟ ਦੀ ਉਡੀਕ ਤੋਂ ਬਾਅਦ %d ਵਰਤੋਂ ਮਿੰਟ",
    "Extra usage per request: %d minutes": "ਹਰ ਬੇਨਤੀ ਤੇ ਵਾਧੂ ਵਰਤੋਂ: %d ਮਿੰਟ",
    "Requests per day: %d": "ਰੋਜ਼ਾਨਾ ਬੇਨਤੀਆਂ: %d",
    "Wait after request: %d minutes": "ਬੇਨਤੀ ਤੋਂ ਬਾਅਦ ਉਡੀਕ: %d ਮਿੰਟ",
    "After the full daily limit is spent, request more actual usage minutes. The apps remain blocked until the wait ends. The daily request count resets at midnight.": "ਪੂਰੀ ਰੋਜ਼ਾਨਾ ਹੱਦ ਮੁੱਕਣ ਤੋਂ ਬਾਅਦ ਹੋਰ ਅਸਲੀ ਵਰਤੋਂ ਮਿੰਟ ਮੰਗੋ। ਉਡੀਕ ਮੁੱਕਣ ਤੱਕ ਐਪਾਂ ਬਲੌਕ ਰਹਿੰਦੀਆਂ ਹਨ। ਰੋਜ਼ਾਨਾ ਬੇਨਤੀਆਂ ਦੀ ਗਿਣਤੀ ਅੱਧੀ ਰਾਤ ਨੂੰ ਰੀਸੈੱਟ ਹੁੰਦੀ ਹੈ।",
    "iOS Screen Time callbacks can arrive late. Wake-up, split, and extra-time boundaries may not switch at the exact minute.": "iOS ਸਕ੍ਰੀਨ ਟਾਈਮ ਕਾਲਬੈਕ ਦੇਰ ਨਾਲ ਆ ਸਕਦੇ ਹਨ। ਜਾਗਣ, ਵੰਡ ਅਤੇ ਵੱਧ ਸਮੇਂ ਦੀਆਂ ਹੱਦਾਂ ਠੀਕ ਉਸੇ ਮਿੰਟ ਨਹੀਂ ਬਦਲ ਸਕਦੀਆਂ।",
    "Extra-time requests left today: %d": "ਅੱਜ ਵੱਧ ਸਮੇਂ ਦੀਆਂ ਬਾਕੀ ਬੇਨਤੀਆਂ: %d",
    "Request extra time (%d left)": "ਵੱਧ ਸਮਾਂ ਮੰਗੋ (%d ਬਾਕੀ)",
    "Extra time available in": "ਵੱਧ ਸਮਾਂ ਉਪਲਬਧ ਹੋਵੇਗਾ",
    "(%d requests left)": "(%d ਬੇਨਤੀਆਂ ਬਾਕੀ)",
    "Extra usage active · %d requests left": "ਵਾਧੂ ਵਰਤੋਂ ਚਾਲੂ · %d ਬੇਨਤੀਆਂ ਬਾਕੀ",
    "No extra-time requests left today": "ਅੱਜ ਵੱਧ ਸਮੇਂ ਦੀ ਕੋਈ ਬੇਨਤੀ ਬਾਕੀ ਨਹੀਂ",
    "Extra time": "ਵੱਧ ਸਮਾਂ",
    "Extra time could not be started safely. Your limit is still in place; try again later.": "ਵੱਧ ਸਮਾਂ ਸੁਰੱਖਿਅਤ ਢੰਗ ਨਾਲ ਸ਼ੁਰੂ ਨਹੀਂ ਹੋ ਸਕਿਆ। ਤੁਹਾਡੀ ਹੱਦ ਅਜੇ ਲਾਗੂ ਹੈ; ਬਾਅਦ ਵਿੱਚ ਦੁਬਾਰਾ ਕੋਸ਼ਿਸ਼ ਕਰੋ।",
    "Split-budget blocks cannot be manually rechecked. They remain until their scheduled boundary.": "ਵੰਡੇ ਸਮੇਂ ਵਾਲੇ ਬਲੌਕ ਹੱਥੀਂ ਦੁਬਾਰਾ ਨਹੀਂ ਜਾਂਚੇ ਜਾ ਸਕਦੇ। ਉਹ ਆਪਣੀ ਤੈਅ ਹੱਦ ਤੱਕ ਰਹਿੰਦੇ ਹਨ।",
    "Change limit: %@": "ਹੱਦ ਬਦਲੋ: %@",
    "Unlock immediately after tap": "ਛੂਹਣ ਤੇ ਤੁਰੰਤ ਖੋਲ੍ਹੋ",
    "Wake up": "ਜਾਗੋ",
    "Available after %@": "%@ ਤੋਂ ਬਾਅਦ ਉਪਲਬਧ",
    "Awake for today": "ਅੱਜ ਲਈ ਜਾਗ ਚੁੱਕੇ",
    "Different limits by weekday": "ਹਫ਼ਤੇ ਦੇ ਦਿਨ ਮੁਤਾਬਕ ਵੱਖਰੀਆਂ ਹੱਦਾਂ",
    "Each weekday's budget replaces the daily limit for that day.": "ਹਰ ਦਿਨ ਦਾ ਸਮਾਂ ਉਸ ਦਿਨ ਲਈ ਰੋਜ਼ਾਨਾ ਹੱਦ ਦੀ ਥਾਂ ਲੈਂਦਾ ਹੈ।",
    "Require wake-up tap": "ਜਾਗੋ ਛੂਹਣਾ ਲਾਜ਼ਮੀ ਕਰੋ",
    "Wait %d minutes after tap": "ਛੂਹਣ ਤੋਂ ਬਾਅਦ %d ਮਿੰਟ ਉਡੀਕ ਕਰੋ",
    "After your first tap each day, wait before this limit becomes available.": "ਹਰ ਦਿਨ ਤੁਹਾਡੀ ਪਹਿਲੀ ਛੂਹ ਤੋਂ ਬਾਅਦ, ਇਹ ਹੱਦ ਉਪਲਬਧ ਹੋਣ ਤੋਂ ਪਹਿਲਾਂ ਉਡੀਕ ਕਰੋ।",
    "Split daily budget": "ਰੋਜ਼ਾਨਾ ਸਮਾਂ ਵੰਡੋ",
    "Cutoff time": "ਕਟਆਫ਼ ਸਮਾਂ",
    "%d minutes before cutoff": "ਕਟਆਫ਼ ਤੋਂ %d ਮਿੰਟ ਪਹਿਲਾਂ",
    "Carry unused early minutes forward": "ਅਣਵਰਤੇ ਸ਼ੁਰੂਆਤੀ ਮਿੰਟ ਅੱਗੇ ਲੈ ਜਾਓ",
    "Reserve part of today's budget before the cutoff. The rest is available afterward.": "ਕਟਆਫ਼ ਤੋਂ ਪਹਿਲਾਂ ਅੱਜ ਦੇ ਸਮੇਂ ਦਾ ਇੱਕ ਹਿੱਸਾ ਰੱਖੋ। ਬਾਕੀ ਉਸ ਤੋਂ ਬਾਅਦ ਉਪਲਬਧ ਹੈ।",
    "Usage bursts and breaks": "ਵਰਤੋਂ ਦੇ ਧਮਾਕੇ ਅਤੇ ਵਿਰਾਮ",
    "Burst quota: %d minutes": "ਧਮਾਕੇ ਦਾ ਕੋਟਾ: %d ਮਿੰਟ",
    "Fresh allowance interval: %d minutes": "ਨਵੇਂ ਸਮੇਂ ਦਾ ਵਕਫ਼ਾ: %d ਮਿੰਟ",
    "Cooldown / break: %d minutes": "ਠੰਢਾ ਹੋਣਾ / ਵਿਰਾਮ: %d ਮਿੰਟ",
    "Practical approximation, not an exact rolling window: a usage burst, a minimum interval before a fresh allowance, then a break. iOS may deliver usage callbacks late.": "ਅਮਲੀ ਅੰਦਾਜ਼ਾ, ਸਟੀਕ ਚੱਲਦੀ ਖਿੜਕੀ ਨਹੀਂ: ਵਰਤੋਂ ਦਾ ਧਮਾਕਾ, ਨਵੇਂ ਸਮੇਂ ਤੋਂ ਪਹਿਲਾਂ ਘੱਟੋ-ਘੱਟ ਵਕਫ਼ਾ, ਫਿਰ ਵਿਰਾਮ। iOS ਵਰਤੋਂ ਕਾਲਬੈਕ ਦੇਰ ਨਾਲ ਭੇਜ ਸਕਦਾ ਹੈ।",
    "iOS Screen Time callbacks can arrive late. Wake-up, split, and pacing boundaries may not switch at the exact minute.": "iOS ਸਕ੍ਰੀਨ ਟਾਈਮ ਕਾਲਬੈਕ ਦੇਰ ਨਾਲ ਆ ਸਕਦੇ ਹਨ। ਜਾਗਣ, ਵੰਡ ਅਤੇ ਗਤੀ ਦੀਆਂ ਹੱਦਾਂ ਠੀਕ ਉਸੇ ਮਿੰਟ ਨਹੀਂ ਬਦਲ ਸਕਦੀਆਂ।",
    "Edit apps": "ਐਪਾਂ ਬਦਲੋ",
    "Change apps in %@": "%@ ਵਿੱਚ ਐਪਾਂ ਬਦਲੋ",
    "Change apps and daily limit for %@ to %d min/day": "%@ ਲਈ ਐਪਾਂ ਅਤੇ ਰੋਜ਼ਾਨਾ ਹੱਦ %d ਮਿੰਟ/ਦਿਨ ਕਰੋ",
    "Change limit": "ਹੱਦ ਬਦਲੋ",
    "Notifications": "ਸੂਚਨਾਵਾਂ",
    "5 minutes left for a limit": "ਹੱਦ ਦੇ 5 ਮਿੰਟ ਬਾਕੀ",
    "Only for limits longer than 5 minutes. No alert is sent during a free period.": "ਸਿਰਫ਼ 5 ਮਿੰਟ ਤੋਂ ਲੰਮੀਆਂ ਹੱਦਾਂ ਲਈ। ਖੁੱਲ੍ਹੇ ਸਮੇਂ ਦੌਰਾਨ ਕੋਈ ਚੇਤਾਵਨੀ ਨਹੀਂ ਭੇਜੀ ਜਾਂਦੀ।",
    "Free period starts or ends in 5 minutes": "ਖੁੱਲ੍ਹਾ ਸਮਾਂ 5 ਮਿੰਟ ਵਿੱਚ ਸ਼ੁਰੂ ਜਾਂ ਖ਼ਤਮ ਹੁੰਦਾ ਹੈ",
    "Optional reminders for scheduled free periods and free-session endings.": "ਤੈਅ ਖੁੱਲ੍ਹੇ ਸਮਿਆਂ ਅਤੇ ਖੁੱਲ੍ਹੇ ਸੈਸ਼ਨਾਂ ਦੇ ਅੰਤ ਲਈ ਵਿਕਲਪਿਕ ਯਾਦ-ਦਹਾਨੀਆਂ।",
    "5 minutes left": "5 ਮਿੰਟ ਬਾਕੀ",
    "About 5 minutes remain for %@ today.": "ਅੱਜ %@ ਲਈ ਲਗਭਗ 5 ਮਿੰਟ ਬਾਕੀ ਹਨ।",
    "Free period starts in 5 minutes": "ਖੁੱਲ੍ਹਾ ਸਮਾਂ 5 ਮਿੰਟ ਵਿੱਚ ਸ਼ੁਰੂ ਹੁੰਦਾ ਹੈ",
    "Free period ends in 5 minutes": "ਖੁੱਲ੍ਹਾ ਸਮਾਂ 5 ਮਿੰਟ ਵਿੱਚ ਖ਼ਤਮ ਹੁੰਦਾ ਹੈ",
    "Now": "ਹੁਣ",
    "Next": "ਅੱਗੇ",
    "No timed rule active": "ਕੋਈ ਸਮੇਂ ਵਾਲਾ ਨਿਯਮ ਚਾਲੂ ਨਹੀਂ",
    "Nothing coming up": "ਅੱਗੇ ਕੁਝ ਨਹੀਂ",
    "Limit reached": "ਹੱਦ ਪੂਰੀ ਹੋਈ",
    "Demora now speaks more languages": "Demora ਹੁਣ ਹੋਰ ਭਾਸ਼ਾਵਾਂ ਬੋਲਦਾ ਹੈ",
    "We've added support for German, French, Portuguese, Polish, Turkish, and Hindi.": "ਅਸੀਂ ਜਰਮਨ, ਫ਼੍ਰੈਂਚ, ਪੁਰਤਗਾਲੀ, ਪੋਲਿਸ਼, ਤੁਰਕੀ ਅਤੇ ਹਿੰਦੀ ਲਈ ਸਹਾਇਤਾ ਜੋੜੀ ਹੈ।",
    "Apply language": "ਭਾਸ਼ਾ ਲਾਗੂ ਕਰੋ",
    "Translation in beta": "ਅਨੁਵਾਦ ਬੀਟਾ ਵਿੱਚ",
    "This language is in beta. Please report any mistranslations or unclear phrasing to hello@getdemora.app.": "ਇਹ ਭਾਸ਼ਾ ਬੀਟਾ ਵਿੱਚ ਹੈ। ਕਿਸੇ ਵੀ ਗ਼ਲਤ ਅਨੁਵਾਦ ਜਾਂ ਅਸਪਸ਼ਟ ਸ਼ਬਦਾਂ ਦੀ ਸੂਚਨਾ hello@getdemora.app ਤੇ ਦਿਓ।",
    "Dismiss": "ਬੰਦ ਕਰੋ",
    "Recheck blocked limits": "ਬਲੌਕ ਹੱਦਾਂ ਦੁਬਾਰਾ ਜਾਂਚੋ",
    "Takes around 30 seconds": "ਲਗਭਗ 30 ਸਕਿੰਟ ਲੱਗਦੇ ਹਨ",
    "Recheck keeps current blocks in place while iOS verifies today's usage. Limits iOS confirms stay blocked.": "iOS ਅੱਜ ਦੀ ਵਰਤੋਂ ਦੀ ਪੁਸ਼ਟੀ ਕਰਦਾ ਹੈ ਤਾਂ ਦੁਬਾਰਾ ਜਾਂਚ ਮੌਜੂਦਾ ਬਲੌਕ ਕਾਇਮ ਰੱਖਦੀ ਹੈ। ਜਿਨ੍ਹਾਂ ਹੱਦਾਂ ਦੀ iOS ਪੁਸ਼ਟੀ ਕਰੇ, ਉਹ ਬਲੌਕ ਰਹਿੰਦੀਆਂ ਹਨ।",
    "Limit recheck": "ਹੱਦ ਦੁਬਾਰਾ ਜਾਂਚ",
    "Released %d stale limit blocks. %d limits were freshly confirmed by iOS.": "%d ਪੁਰਾਣੇ ਹੱਦ ਬਲੌਕ ਛੱਡੇ ਗਏ। %d ਹੱਦਾਂ ਦੀ iOS ਨੇ ਤਾਜ਼ਾ ਪੁਸ਼ਟੀ ਕੀਤੀ।",
    "iOS freshly confirmed all current limit blocks.": "iOS ਨੇ ਸਾਰੇ ਮੌਜੂਦਾ ਹੱਦ ਬਲੌਕਾਂ ਦੀ ਤਾਜ਼ਾ ਪੁਸ਼ਟੀ ਕੀਤੀ।",
    "No blocked limits need to be rechecked.": "ਕਿਸੇ ਬਲੌਕ ਹੱਦ ਨੂੰ ਦੁਬਾਰਾ ਜਾਂਚਣ ਦੀ ਲੋੜ ਨਹੀਂ।",
    "Wait until the active free period ends, then recheck again.": "ਚਾਲੂ ਖੁੱਲ੍ਹਾ ਸਮਾਂ ਮੁੱਕਣ ਦੀ ਉਡੀਕ ਕਰੋ, ਫਿਰ ਦੁਬਾਰਾ ਜਾਂਚੋ।",
    "You can recheck again in %@.": "ਤੁਸੀਂ %@ ਵਿੱਚ ਦੁਬਾਰਾ ਜਾਂਚ ਸਕਦੇ ਹੋ।",
    "The recheck was interrupted. No blocks were changed.": "ਦੁਬਾਰਾ ਜਾਂਚ ਵਿਚਾਲੇ ਰੁਕ ਗਈ। ਕੋਈ ਬਲੌਕ ਨਹੀਂ ਬਦਲਿਆ।",
    "iOS couldn't complete the verification safely. No blocks were changed. Try again later.": "iOS ਪੁਸ਼ਟੀ ਸੁਰੱਖਿਅਤ ਢੰਗ ਨਾਲ ਪੂਰੀ ਨਹੀਂ ਕਰ ਸਕਿਆ। ਕੋਈ ਬਲੌਕ ਨਹੀਂ ਬਦਲਿਆ। ਬਾਅਦ ਵਿੱਚ ਦੁਬਾਰਾ ਕੋਸ਼ਿਸ਼ ਕਰੋ।",
    "Safe limit rechecking requires iOS 17.4 or later. No blocks were changed.": "ਸੁਰੱਖਿਅਤ ਹੱਦ ਦੁਬਾਰਾ ਜਾਂਚ ਲਈ iOS 17.4 ਜਾਂ ਨਵਾਂ ਚਾਹੀਦਾ ਹੈ। ਕੋਈ ਬਲੌਕ ਨਹੀਂ ਬਦਲਿਆ।",
    "This is a demo — nothing you do here is saved or actually blocked.": "ਇਹ ਡੈਮੋ ਹੈ — ਤੁਸੀਂ ਇੱਥੇ ਜੋ ਵੀ ਕਰੋ, ਉਹ ਸੰਭਾਲਿਆ ਜਾਂ ਸੱਚਮੁੱਚ ਬਲੌਕ ਨਹੀਂ ਹੁੰਦਾ।",
    "Limitations": "ਸੀਮਾਵਾਂ",
    "iOS reporting notes": "iOS ਰਿਪੋਰਟਿੰਗ ਨੋਟ",
    "Today's usage reporting": "ਅੱਜ ਦੀ ਵਰਤੋਂ ਦੀ ਰਿਪੋਰਟਿੰਗ",
    "Daily counting on older iOS": "ਪੁਰਾਣੇ iOS ਤੇ ਰੋਜ਼ਾਨਾ ਗਿਣਤੀ",
    "%@ #%d of every month": "ਹਰ ਮਹੀਨੇ ਦਾ %@ #%d",
    "%d / %d min": "%d / %d ਮਿੰਟ",
    "blocked until midnight": "ਅੱਧੀ ਰਾਤ ਤੱਕ ਬਲੌਕ",
    "now & next": "ਹੁਣ ਤੇ ਅੱਗੇ",
