    "Manage": "ਸੰਭਾਲੋ",
    "Monday": "ਸੋਮਵਾਰ",
    "Sunday": "ਐਤਵਾਰ",
    "Calendar": "ਕੈਲੰਡਰ",
    "week / month": "ਹਫ਼ਤਾ / ਮਹੀਨਾ",
    "month": "ਮਹੀਨਾ",
    "Solve math problems to skip a countdown.": "ਕਾਊਂਟਡਾਊਨ ਛੱਡਣ ਲਈ ਗਣਿਤ ਦੇ ਸਵਾਲ ਹੱਲ ਕਰੋ।",
    "Enter a password to skip a countdown.": "ਕਾਊਂਟਡਾਊਨ ਛੱਡਣ ਲਈ ਪਾਸਵਰਡ ਭਰੋ।",
    "How schedules work": "ਸਮਾਂ-ਸਾਰਣੀਆਂ ਕਿਵੇਂ ਕੰਮ ਕਰਦੀਆਂ ਹਨ",
    "Help": "ਮਦਦ",
    "thank you": "ਧੰਨਵਾਦ",
    "Guide": "ਗਾਈਡ",
    "Contact": "ਸੰਪਰਕ",
    "About": "ਬਾਰੇ",
    "how each part works": "ਹਰ ਹਿੱਸਾ ਕਿਵੇਂ ਕੰਮ ਕਰਦਾ ਹੈ",
    "links": "ਲਿੰਕ",
    "Report a bug": "ਗੜਬੜ ਦੱਸੋ",
    "Request a feature": "ਕਿਸੇ ਸਹੂਲਤ ਦੀ ਬੇਨਤੀ ਕਰੋ",
    "General help": "ਆਮ ਮਦਦ",
    "Website": "ਵੈੱਬਸਾਈਟ",
    "Instagram": "Instagram",
    "What Demora is": "Demora ਕੀ ਹੈ",
    "Demora protects your screen-time rules with a delay instead of a password. Every change you make waits out a countdown before it takes effect, so you can always change your mind — just not instantly, in a moment of weakness. Blocking itself is enforced by iOS through Screen Time.": "Demora ਤੁਹਾਡੇ ਸਕ੍ਰੀਨ ਟਾਈਮ ਨਿਯਮਾਂ ਨੂੰ ਪਾਸਵਰਡ ਦੀ ਥਾਂ ਦੇਰੀ ਨਾਲ ਸੁਰੱਖਿਅਤ ਕਰਦਾ ਹੈ। ਤੁਹਾਡੀ ਹਰ ਤਬਦੀਲੀ ਲਾਗੂ ਹੋਣ ਤੋਂ ਪਹਿਲਾਂ ਇੱਕ ਕਾਊਂਟਡਾਊਨ ਉਡੀਕਦੀ ਹੈ, ਇਸ ਲਈ ਤੁਸੀਂ ਹਮੇਸ਼ਾ ਮਨ ਬਦਲ ਸਕਦੇ ਹੋ — ਬੱਸ ਕਮਜ਼ੋਰ ਪਲ ਵਿੱਚ ਤੁਰੰਤ ਨਹੀਂ। ਬਲੌਕ ਕਰਨਾ ਆਪ iOS ਸਕ੍ਰੀਨ ਟਾਈਮ ਰਾਹੀਂ ਲਾਗੂ ਕਰਦਾ ਹੈ।",
    "There are two delays. The more-strict delay gates changes that tighten your rules (adding a limit, lowering minutes, adding a schedule). The less-strict delay gates changes that loosen them (raising a limit, removing a block, adding a free period) — usually set longer. Pending changes show on the Home tab with a live countdown and can be cancelled before they apply.": "ਦੋ ਦੇਰੀਆਂ ਹਨ। ਵੱਧ ਸਖ਼ਤ ਦੇਰੀ ਉਨ੍ਹਾਂ ਤਬਦੀਲੀਆਂ ਨੂੰ ਰੋਕਦੀ ਹੈ ਜੋ ਨਿਯਮ ਕੱਸਦੀਆਂ ਹਨ (ਹੱਦ ਜੋੜਨਾ, ਮਿੰਟ ਘਟਾਉਣਾ, ਸਮਾਂ-ਸਾਰਣੀ ਜੋੜਨਾ)। ਘੱਟ ਸਖ਼ਤ ਦੇਰੀ ਉਨ੍ਹਾਂ ਨੂੰ ਰੋਕਦੀ ਹੈ ਜੋ ਨਿਯਮ ਢਿੱਲੇ ਕਰਦੀਆਂ ਹਨ (ਹੱਦ ਵਧਾਉਣਾ, ਬਲੌਕ ਹਟਾਉਣਾ, ਖੁੱਲ੍ਹਾ ਸਮਾਂ ਜੋੜਨਾ) — ਆਮ ਤੌਰ ਤੇ ਲੰਮੀ ਰੱਖੀ ਜਾਂਦੀ ਹੈ। ਉਡੀਕ ਵਿੱਚ ਪਈਆਂ ਤਬਦੀਲੀਆਂ ਹੋਮ ਟੈਬ ਤੇ ਚੱਲਦੀ ਕਾਊਂਟਡਾਊਨ ਨਾਲ ਦਿਸਦੀਆਂ ਹਨ ਅਤੇ ਲਾਗੂ ਹੋਣ ਤੋਂ ਪਹਿਲਾਂ ਰੱਦ ਕੀਤੀਆਂ ਜਾ ਸਕਦੀਆਂ ਹਨ।",
    "A limit is a daily time budget for the apps or categories you choose. When the minutes run out, those apps are blocked until midnight. The Limits tab shows today's usage per limit, and tapping a limit shows exactly which apps it covers.": "ਹੱਦ ਤੁਹਾਡੀ ਚੁਣੀਆਂ ਐਪਾਂ ਜਾਂ ਸ਼੍ਰੇਣੀਆਂ ਲਈ ਰੋਜ਼ਾਨਾ ਸਮੇਂ ਦੀ ਹੱਦ ਹੈ। ਮਿੰਟ ਮੁੱਕਣ ਤੇ ਉਹ ਐਪਾਂ ਅੱਧੀ ਰਾਤ ਤੱਕ ਬਲੌਕ ਹੋ ਜਾਂਦੀਆਂ ਹਨ। ਹੱਦਾਂ ਟੈਬ ਹਰ ਹੱਦ ਦੀ ਅੱਜ ਦੀ ਵਰਤੋਂ ਦਿਖਾਉਂਦੀ ਹੈ, ਅਤੇ ਕਿਸੇ ਹੱਦ ਨੂੰ ਛੂਹਣ ਤੇ ਠੀਕ ਪਤਾ ਲੱਗਦਾ ਹੈ ਕਿ ਉਹ ਕਿਹੜੀਆਂ ਐਪਾਂ ਨੂੰ ਕਵਰ ਕਰਦੀ ਹੈ।",
    "Schedules block apps on a repeating or one-off basis. Recurring schedules repeat daily, on chosen weekdays, or monthly. Planned windows are one-offs for specific dates. Sessions are immediate timed blocks or unblocks. Free periods are windows where limits don't block and usage doesn't count.": "ਸਮਾਂ-ਸਾਰਣੀਆਂ ਐਪਾਂ ਨੂੰ ਦੁਹਰਾਉਣ ਵਾਲੇ ਜਾਂ ਇੱਕ ਵਾਰ ਦੇ ਆਧਾਰ ਤੇ ਬਲੌਕ ਕਰਦੀਆਂ ਹਨ। ਦੁਹਰਾਉਣ ਵਾਲੀਆਂ ਰੋਜ਼ਾਨਾ, ਚੁਣੇ ਹਫ਼ਤੇ ਦੇ ਦਿਨਾਂ ਤੇ ਜਾਂ ਮਹੀਨਾਵਾਰ ਦੁਹਰਾਈਆਂ ਜਾਂਦੀਆਂ ਹਨ। ਯੋਜਨਾਬੱਧ ਸਮੇਂ ਖ਼ਾਸ ਤਾਰੀਖ਼ਾਂ ਲਈ ਇੱਕ ਵਾਰ ਦੇ ਹੁੰਦੇ ਹਨ। ਸੈਸ਼ਨ ਤੁਰੰਤ ਸਮੇਂ ਵਾਲੇ ਬਲੌਕ ਜਾਂ ਅਨਬਲੌਕ ਹਨ। ਖੁੱਲ੍ਹੇ ਸਮੇਂ ਉਹ ਖਿੜਕੀਆਂ ਹਨ ਜਿੱਥੇ ਹੱਦਾਂ ਬਲੌਕ ਨਹੀਂ ਕਰਦੀਆਂ ਅਤੇ ਵਰਤੋਂ ਗਿਣੀ ਨਹੀਂ ਜਾਂਦੀ।",
    "A trusted contact can approve skipping a countdown — by email code or from their own Demora app. People you add must accept before they can approve, and you can revoke them at any time.": "ਭਰੋਸੇਯੋਗ ਸੰਪਰਕ ਕਾਊਂਟਡਾਊਨ ਛੱਡਣ ਨੂੰ ਮਨਜ਼ੂਰ ਕਰ ਸਕਦਾ ਹੈ — ਈਮੇਲ ਕੋਡ ਨਾਲ ਜਾਂ ਆਪਣੀ Demora ਐਪ ਤੋਂ। ਤੁਹਾਡੇ ਜੋੜੇ ਲੋਕਾਂ ਨੂੰ ਮਨਜ਼ੂਰੀ ਦੇਣ ਤੋਂ ਪਹਿਲਾਂ ਸਵੀਕਾਰ ਕਰਨਾ ਪੈਂਦਾ ਹੈ, ਅਤੇ ਤੁਸੀਂ ਕਿਸੇ ਵੀ ਸਮੇਂ ਉਨ੍ਹਾਂ ਨੂੰ ਹਟਾ ਸਕਦੇ ਹੋ।",
    "App deletion lock": "ਐਪ ਮਿਟਾਉਣ ਦਾ ਤਾਲਾ",
    "the core idea": "ਮੂਲ ਵਿਚਾਰ",
    "the two countdowns": "ਦੋ ਕਾਊਂਟਡਾਊਨ",
    "daily app budgets": "ਐਪਾਂ ਦੇ ਰੋਜ਼ਾਨਾ ਸਮੇਂ",
    "recurring, planned, sessions": "ਦੁਹਰਾਉਣ ਵਾਲੇ, ਯੋਜਨਾਬੱਧ, ਸੈਸ਼ਨ",
    "escape hatches": "ਬਚ ਨਿਕਲਣ ਦੇ ਰਾਹ",
    "approval by a person": "ਕਿਸੇ ਵਿਅਕਤੀ ਦੀ ਮਨਜ਼ੂਰੀ",
    "can't uninstall to bypass": "ਬਚਣ ਲਈ ਅਣਇੰਸਟਾਲ ਨਹੀਂ ਕਰ ਸਕਦੇ",
    "Most screen-time apps lock your rules behind a password. Because you know the password, you can undo your own rules the moment you feel the urge — so they rarely stick.\n\nDemora protects your rules with time instead. Every change waits out a countdown you set in advance before it takes effect. You stay in full control of your rules, but you can't change them in a single impulsive moment. The blocking itself is enforced by iOS through Screen Time — the same system parental controls use — so it can't be quietly bypassed.": "ਜ਼ਿਆਦਾਤਰ ਸਕ੍ਰੀਨ ਟਾਈਮ ਐਪਾਂ ਤੁਹਾਡੇ ਨਿਯਮਾਂ ਨੂੰ ਪਾਸਵਰਡ ਦੇ ਪਿੱਛੇ ਤਾਲਾ ਲਾਉਂਦੀਆਂ ਹਨ। ਪਾਸਵਰਡ ਤੁਹਾਨੂੰ ਪਤਾ ਹੁੰਦਾ ਹੈ, ਇਸ ਲਈ ਇੱਛਾ ਉੱਠਦਿਆਂ ਹੀ ਤੁਸੀਂ ਆਪਣੇ ਨਿਯਮ ਪਲਟ ਸਕਦੇ ਹੋ — ਇਸੇ ਲਈ ਉਹ ਘੱਟ ਹੀ ਟਿਕਦੇ ਹਨ।\n\nDemora ਤੁਹਾਡੇ ਨਿਯਮਾਂ ਨੂੰ ਪਾਸਵਰਡ ਦੀ ਥਾਂ ਸਮੇਂ ਨਾਲ ਸੁਰੱਖਿਅਤ ਕਰਦਾ ਹੈ। ਹਰ ਤਬਦੀਲੀ ਲਾਗੂ ਹੋਣ ਤੋਂ ਪਹਿਲਾਂ ਉਹ ਕਾਊਂਟਡਾਊਨ ਉਡੀਕਦੀ ਹੈ ਜੋ ਤੁਸੀਂ ਪਹਿਲਾਂ ਤੈਅ ਕੀਤੀ ਹੁੰਦੀ ਹੈ। ਨਿਯਮਾਂ ਤੇ ਪੂਰਾ ਕਾਬੂ ਤੁਹਾਡਾ ਹੀ ਰਹਿੰਦਾ ਹੈ, ਪਰ ਤੁਸੀਂ ਇੱਕ ਜੋਸ਼ੀਲੇ ਪਲ ਵਿੱਚ ਉਨ੍ਹਾਂ ਨੂੰ ਬਦਲ ਨਹੀਂ ਸਕਦੇ। ਬਲੌਕ ਕਰਨਾ ਆਪ iOS ਸਕ੍ਰੀਨ ਟਾਈਮ ਰਾਹੀਂ ਲਾਗੂ ਕਰਦਾ ਹੈ — ਉਹੀ ਪ੍ਰਣਾਲੀ ਜੋ ਪੇਰੈਂਟਲ ਕੰਟਰੋਲ ਵਰਤਦੇ ਹਨ — ਇਸ ਲਈ ਇਸਨੂੰ ਚੁੱਪ-ਚਾਪ ਟੱਪਿਆ ਨਹੀਂ ਜਾ ਸਕਦਾ।",
    "Demora has two delays. The more-strict delay covers any change that tightens your rules: adding a limit, lowering its minutes, adding a schedule, or turning on the deletion lock. The less-strict delay covers changes that loosen them: raising a limit, removing a block, adding a free period, or disabling an override. The less-strict delay is usually set longer, since loosening is where temptation lives.\n\nA change doesn't apply right away — it becomes a pending change with a live countdown on the Home tab. You can cancel it any time before it lands, and when the countdown reaches zero it applies on its own, even if the app is closed.": "Demora ਵਿੱਚ ਦੋ ਦੇਰੀਆਂ ਹਨ। ਵੱਧ ਸਖ਼ਤ ਦੇਰੀ ਹਰ ਉਸ ਤਬਦੀਲੀ ਤੇ ਲਾਗੂ ਹੁੰਦੀ ਹੈ ਜੋ ਤੁਹਾਡੇ ਨਿਯਮ ਕੱਸਦੀ ਹੈ: ਹੱਦ ਜੋੜਨਾ, ਮਿੰਟ ਘਟਾਉਣਾ, ਸਮਾਂ-ਸਾਰਣੀ ਜੋੜਨਾ ਜਾਂ ਮਿਟਾਉਣ ਦਾ ਤਾਲਾ ਲਾਉਣਾ। ਘੱਟ ਸਖ਼ਤ ਦੇਰੀ ਉਨ੍ਹਾਂ ਤਬਦੀਲੀਆਂ ਤੇ ਲਾਗੂ ਹੁੰਦੀ ਹੈ ਜੋ ਨਿਯਮ ਢਿੱਲੇ ਕਰਦੀਆਂ ਹਨ: ਹੱਦ ਵਧਾਉਣਾ, ਬਲੌਕ ਹਟਾਉਣਾ, ਖੁੱਲ੍ਹਾ ਸਮਾਂ ਜੋੜਨਾ ਜਾਂ ਕੋਈ ਛੋਟ ਬੰਦ ਕਰਨਾ। ਘੱਟ ਸਖ਼ਤ ਦੇਰੀ ਆਮ ਤੌਰ ਤੇ ਲੰਮੀ ਰੱਖੀ ਜਾਂਦੀ ਹੈ, ਕਿਉਂਕਿ ਲਾਲਚ ਢਿੱਲ ਦੇਣ ਵਿੱਚ ਹੀ ਵੱਸਦਾ ਹੈ।\n\nਤਬਦੀਲੀ ਤੁਰੰਤ ਲਾਗੂ ਨਹੀਂ ਹੁੰਦੀ — ਇਹ ਹੋਮ ਟੈਬ ਤੇ ਚੱਲਦੀ ਕਾਊਂਟਡਾਊਨ ਵਾਲੀ ਉਡੀਕ ਵਿੱਚ ਪਈ ਤਬਦੀਲੀ ਬਣ ਜਾਂਦੀ ਹੈ। ਲੱਗਣ ਤੋਂ ਪਹਿਲਾਂ ਤੁਸੀਂ ਕਦੇ ਵੀ ਇਸਨੂੰ ਰੱਦ ਕਰ ਸਕਦੇ ਹੋ, ਅਤੇ ਕਾਊਂਟਡਾਊਨ ਜ਼ੀਰੋ ਹੋਣ ਤੇ ਇਹ ਆਪਣੇ ਆਪ ਲਾਗੂ ਹੋ ਜਾਂਦੀ ਹੈ, ਭਾਵੇਂ ਐਪ ਬੰਦ ਹੋਵੇ।",
    "A limit is a daily time budget for a set of apps or whole categories. When the minutes run out, those apps are blocked for the rest of the day and unlock again at midnight.\n\nThe Limits tab shows today's real usage for each limit, read straight from Screen Time, and tapping a limit reveals exactly which apps and categories it covers. Because usage is measured by iOS, time spent before you created the limit still counts toward it that day. Raising or removing a limit is a less-strict change; adding one or lowering its minutes is stricter.": "ਹੱਦ ਐਪਾਂ ਦੇ ਸਮੂਹ ਜਾਂ ਪੂਰੀਆਂ ਸ਼੍ਰੇਣੀਆਂ ਲਈ ਰੋਜ਼ਾਨਾ ਸਮੇਂ ਦੀ ਹੱਦ ਹੈ। ਮਿੰਟ ਮੁੱਕਣ ਤੇ ਉਹ ਐਪਾਂ ਬਾਕੀ ਦਿਨ ਲਈ ਬਲੌਕ ਹੋ ਜਾਂਦੀਆਂ ਹਨ ਅਤੇ ਅੱਧੀ ਰਾਤ ਨੂੰ ਫਿਰ ਖੁੱਲ੍ਹ ਜਾਂਦੀਆਂ ਹਨ।\n\nਹੱਦਾਂ ਟੈਬ ਹਰ ਹੱਦ ਦੀ ਅੱਜ ਦੀ ਅਸਲੀ ਵਰਤੋਂ ਦਿਖਾਉਂਦੀ ਹੈ, ਜੋ ਸਿੱਧੀ ਸਕ੍ਰੀਨ ਟਾਈਮ ਤੋਂ ਪੜ੍ਹੀ ਜਾਂਦੀ ਹੈ, ਅਤੇ ਕਿਸੇ ਹੱਦ ਨੂੰ ਛੂਹਣ ਤੇ ਠੀਕ ਪਤਾ ਲੱਗਦਾ ਹੈ ਕਿ ਉਹ ਕਿਹੜੀਆਂ ਐਪਾਂ ਅਤੇ ਸ਼੍ਰੇਣੀਆਂ ਨੂੰ ਕਵਰ ਕਰਦੀ ਹੈ। ਕਿਉਂਕਿ ਵਰਤੋਂ iOS ਮਾਪਦਾ ਹੈ, ਹੱਦ ਬਣਾਉਣ ਤੋਂ ਪਹਿਲਾਂ ਲੱਗਿਆ ਸਮਾਂ ਵੀ ਉਸ ਦਿਨ ਉਸ ਵਿੱਚ ਗਿਣਿਆ ਜਾਂਦਾ ਹੈ। ਹੱਦ ਵਧਾਉਣਾ ਜਾਂ ਹਟਾਉਣਾ ਘੱਟ ਸਖ਼ਤ ਤਬਦੀਲੀ ਹੈ; ਇੱਕ ਜੋੜਨਾ ਜਾਂ ਮਿੰਟ ਘਟਾਉਣਾ ਵੱਧ ਸਖ਼ਤ ਹੈ।",
    "Schedules block apps by time rather than by budget, in a few shapes. Recurring schedules repeat — every day, on chosen weekdays, or on a monthly pattern. Planned windows are one-offs for a specific date, like a trip or an exam. Sessions are immediate, timed blocks or unblocks you start right now. Free periods are windows where limits don't block and usage doesn't count toward them.\n\nEach blocking schedule either blocks the apps you pick, or blocks everything except the apps you pick. When rules overlap, the most specific one wins: a session beats a planned window, which beats a recurring schedule, and within the same kind the one added most recently takes priority.": "ਸਮਾਂ-ਸਾਰਣੀਆਂ ਐਪਾਂ ਨੂੰ ਸਮੇਂ ਨਾਲ ਬਲੌਕ ਕਰਦੀਆਂ ਹਨ, ਸਮੇਂ ਦੀ ਹੱਦ ਨਾਲ ਨਹੀਂ, ਕਈ ਰੂਪਾਂ ਵਿੱਚ। ਦੁਹਰਾਉਣ ਵਾਲੀਆਂ ਸਮਾਂ-ਸਾਰਣੀਆਂ ਦੁਹਰਾਈਆਂ ਜਾਂਦੀਆਂ ਹਨ — ਹਰ ਦਿਨ, ਚੁਣੇ ਹਫ਼ਤੇ ਦੇ ਦਿਨਾਂ ਤੇ, ਜਾਂ ਮਹੀਨਾਵਾਰ ਢੰਗ ਨਾਲ। ਯੋਜਨਾਬੱਧ ਸਮੇਂ ਕਿਸੇ ਖ਼ਾਸ ਤਾਰੀਖ਼ ਲਈ ਇੱਕ ਵਾਰ ਦੇ ਹੁੰਦੇ ਹਨ, ਜਿਵੇਂ ਸਫ਼ਰ ਜਾਂ ਇਮਤਿਹਾਨ। ਸੈਸ਼ਨ ਤੁਰੰਤ ਸਮੇਂ ਵਾਲੇ ਬਲੌਕ ਜਾਂ ਅਨਬਲੌਕ ਹਨ ਜੋ ਤੁਸੀਂ ਹੁਣੇ ਸ਼ੁਰੂ ਕਰਦੇ ਹੋ। ਖੁੱਲ੍ਹੇ ਸਮੇਂ ਉਹ ਖਿੜਕੀਆਂ ਹਨ ਜਿੱਥੇ ਹੱਦਾਂ ਬਲੌਕ ਨਹੀਂ ਕਰਦੀਆਂ ਅਤੇ ਵਰਤੋਂ ਉਨ੍ਹਾਂ ਵਿੱਚ ਗਿਣੀ ਨਹੀਂ ਜਾਂਦੀ।\n\nਹਰ ਬਲੌਕ ਕਰਨ ਵਾਲੀ ਸਮਾਂ-ਸਾਰਣੀ ਜਾਂ ਤਾਂ ਤੁਹਾਡੀਆਂ ਚੁਣੀਆਂ ਐਪਾਂ ਬਲੌਕ ਕਰਦੀ ਹੈ, ਜਾਂ ਤੁਹਾਡੀਆਂ ਚੁਣੀਆਂ ਐਪਾਂ ਨੂੰ ਛੱਡ ਕੇ ਸਭ ਕੁਝ ਬਲੌਕ ਕਰਦੀ ਹੈ। ਜਦੋਂ ਨਿਯਮ ਰਲਦੇ ਹਨ, ਸਭ ਤੋਂ ਖ਼ਾਸ ਜਿੱਤਦਾ ਹੈ: ਸੈਸ਼ਨ ਯੋਜਨਾਬੱਧ ਸਮੇਂ ਨੂੰ ਹਰਾਉਂਦਾ ਹੈ, ਜੋ ਦੁਹਰਾਉਣ ਵਾਲੀ ਸਮਾਂ-ਸਾਰਣੀ ਨੂੰ ਹਰਾਉਂਦਾ ਹੈ, ਅਤੇ ਇੱਕੋ ਕਿਸਮ ਵਿੱਚ ਸਭ ਤੋਂ ਹਾਲ ਹੀ ਵਿੱਚ ਜੋੜਿਆ ਹੋਇਆ ਅੱਗੇ ਰਹਿੰਦਾ ਹੈ।",
    "Overrides are optional escape hatches that let you skip a pending change's countdown. There are three: solve a set of math problems, enter a password, or ask a trusted contact to approve. They're all off by default, so out of the box your delays are absolute.\n\nTurning an override on, or making it easier, counts as a less-strict change and waits out that delay. Turning one off, or making it harder, is stricter — so you can't instantly weaken your own safety net.": "ਛੋਟਾਂ ਵਿਕਲਪਿਕ ਬਚ ਨਿਕਲਣ ਦੇ ਰਾਹ ਹਨ ਜੋ ਤੁਹਾਨੂੰ ਉਡੀਕ ਵਿੱਚ ਪਈ ਤਬਦੀਲੀ ਦੀ ਕਾਊਂਟਡਾਊਨ ਛੱਡਣ ਦਿੰਦੇ ਹਨ। ਤਿੰਨ ਹਨ: ਗਣਿਤ ਦੇ ਸਵਾਲ ਹੱਲ ਕਰੋ, ਪਾਸਵਰਡ ਭਰੋ, ਜਾਂ ਕਿਸੇ ਭਰੋਸੇਯੋਗ ਸੰਪਰਕ ਤੋਂ ਮਨਜ਼ੂਰੀ ਮੰਗੋ। ਇਹ ਸਾਰੇ ਮੂਲ ਰੂਪ ਵਿੱਚ ਬੰਦ ਹਨ, ਇਸ ਲਈ ਸ਼ੁਰੂ ਤੋਂ ਹੀ ਤੁਹਾਡੀਆਂ ਦੇਰੀਆਂ ਪੂਰੀਆਂ ਪੱਕੀਆਂ ਹਨ।\n\nਕਿਸੇ ਛੋਟ ਨੂੰ ਚਾਲੂ ਕਰਨਾ, ਜਾਂ ਸੌਖਾ ਬਣਾਉਣਾ, ਘੱਟ ਸਖ਼ਤ ਤਬਦੀਲੀ ਗਿਣਿਆ ਜਾਂਦਾ ਹੈ ਅਤੇ ਉਸ ਦੇਰੀ ਦੀ ਉਡੀਕ ਕਰਦਾ ਹੈ। ਇੱਕ ਨੂੰ ਬੰਦ ਕਰਨਾ, ਜਾਂ ਔਖਾ ਬਣਾਉਣਾ, ਵੱਧ ਸਖ਼ਤ ਹੈ — ਇਸ ਲਈ ਤੁਸੀਂ ਆਪਣੀ ਸੁਰੱਖਿਆ ਦੀ ਜਾਲੀ ਨੂੰ ਇੱਕਦਮ ਕਮਜ਼ੋਰ ਨਹੀਂ ਕਰ ਸਕਦੇ।",
    "A trusted contact is a person who can approve skipping a countdown for you. They can approve by entering a short code sent to their email, or directly from their own copy of Demora.\n\nAnyone you add has to accept the request before they can approve anything, so no one is involved without their knowledge. You can revoke a contact at any time, and they can step down on their side too. Adding the override is a less-strict change; removing it is stricter.": "ਭਰੋਸੇਯੋਗ ਸੰਪਰਕ ਉਹ ਵਿਅਕਤੀ ਹੈ ਜੋ ਤੁਹਾਡੇ ਲਈ ਕਾਊਂਟਡਾਊਨ ਛੱਡਣ ਨੂੰ ਮਨਜ਼ੂਰ ਕਰ ਸਕਦਾ ਹੈ। ਉਹ ਆਪਣੀ ਈਮੇਲ ਤੇ ਭੇਜਿਆ ਛੋਟਾ ਕੋਡ ਭਰ ਕੇ, ਜਾਂ ਸਿੱਧਾ ਆਪਣੀ Demora ਐਪ ਤੋਂ ਮਨਜ਼ੂਰ ਕਰ ਸਕਦੇ ਹਨ।\n\nਤੁਹਾਡੇ ਜੋੜੇ ਹਰ ਵਿਅਕਤੀ ਨੂੰ ਕੁਝ ਵੀ ਮਨਜ਼ੂਰ ਕਰਨ ਤੋਂ ਪਹਿਲਾਂ ਬੇਨਤੀ ਸਵੀਕਾਰ ਕਰਨੀ ਪੈਂਦੀ ਹੈ, ਇਸ ਲਈ ਕੋਈ ਵੀ ਉਸਦੀ ਜਾਣਕਾਰੀ ਤੋਂ ਬਿਨਾਂ ਸ਼ਾਮਲ ਨਹੀਂ ਹੁੰਦਾ। ਤੁਸੀਂ ਕਿਸੇ ਵੀ ਸਮੇਂ ਸੰਪਰਕ ਹਟਾ ਸਕਦੇ ਹੋ, ਅਤੇ ਉਹ ਆਪਣੇ ਪਾਸਿਓਂ ਵੀ ਪਿੱਛੇ ਹਟ ਸਕਦੇ ਹਨ। ਛੋਟ ਜੋੜਨਾ ਘੱਟ ਸਖ਼ਤ ਤਬਦੀਲੀ ਹੈ; ਇਸਨੂੰ ਹਟਾਉਣਾ ਵੱਧ ਸਖ਼ਤ ਹੈ।",
    "When the deletion lock is on, deleting any app from this iPhone is blocked — including Demora itself. That closes the most obvious loophole: uninstalling the app to wipe your rules.\n\nBecause turning the lock off makes things easier to bypass, it counts as a less-strict change and waits out that delay before it takes effect.": "ਮਿਟਾਉਣ ਦਾ ਤਾਲਾ ਚਾਲੂ ਹੋਵੇ ਤਾਂ ਇਸ iPhone ਤੋਂ ਕੋਈ ਵੀ ਐਪ ਮਿਟਾਉਣਾ ਬਲੌਕ ਹੁੰਦਾ ਹੈ — Demora ਆਪ ਸਮੇਤ। ਇਹ ਸਭ ਤੋਂ ਸਾਫ਼ ਕਮੀ ਬੰਦ ਕਰਦਾ ਹੈ: ਨਿਯਮ ਮਿਟਾਉਣ ਲਈ ਐਪ ਅਣਇੰਸਟਾਲ ਕਰ ਦੇਣਾ।\n\nਕਿਉਂਕਿ ਤਾਲਾ ਬੰਦ ਕਰਨ ਨਾਲ ਬਚ ਨਿਕਲਣਾ ਸੌਖਾ ਹੁੰਦਾ ਹੈ, ਇਹ ਘੱਟ ਸਖ਼ਤ ਤਬਦੀਲੀ ਗਿਣਿਆ ਜਾਂਦਾ ਹੈ ਅਤੇ ਲਾਗੂ ਹੋਣ ਤੋਂ ਪਹਿਲਾਂ ਉਸ ਦੇਰੀ ਦੀ ਉਡੀਕ ਕਰਦਾ ਹੈ।",
    "When on, deleting any app from this iPhone is blocked — including Demora itself — so your rules can't be bypassed by uninstalling. Turning it off goes through the less-strict delay.": "ਚਾਲੂ ਹੋਣ ਤੇ ਇਸ iPhone ਤੋਂ ਕੋਈ ਵੀ ਐਪ ਮਿਟਾਉਣਾ ਬਲੌਕ ਹੁੰਦਾ ਹੈ — Demora ਆਪ ਸਮੇਤ — ਤਾਂ ਜੋ ਤੁਹਾਡੇ ਨਿਯਮ ਅਣਇੰਸਟਾਲ ਕਰਕੇ ਟੱਪੇ ਨਾ ਜਾ ਸਕਣ। ਇਸਨੂੰ ਬੰਦ ਕਰਨਾ ਘੱਟ ਸਖ਼ਤ ਦੇਰੀ ਵਿੱਚੋਂ ਲੰਘਦਾ ਹੈ।",
    "Blocks": "ਬਲੌਕ",
    "New recurring": "ਨਵਾਂ ਦੁਹਰਾਉਣ ਵਾਲਾ",
    "Week": "ਹਫ਼ਤਾ",
    "Month": "ਮਹੀਨਾ",
    "Nothing on this day.": "ਇਸ ਦਿਨ ਕੁਝ ਨਹੀਂ।",
    "When things overlap": "ਜਦੋਂ ਚੀਜ਼ਾਂ ਰਲਦੀਆਂ ਹਨ",
    "One-off, right now: block or unblock chosen apps for a set number of minutes. Still delay-gated to start; ending early flips the rule.": "ਇੱਕ ਵਾਰ, ਹੁਣੇ: ਚੁਣੀਆਂ ਐਪਾਂ ਨੂੰ ਕੁਝ ਮਿੰਟਾਂ ਲਈ ਬਲੌਕ ਜਾਂ ਅਨਬਲੌਕ ਕਰੋ। ਸ਼ੁਰੂ ਕਰਨਾ ਫਿਰ ਵੀ ਦੇਰੀ ਦੇ ਅਧੀਨ ਹੈ; ਜਲਦੀ ਖ਼ਤਮ ਕਰਨ ਨਾਲ ਨਿਯਮ ਪਲਟ ਜਾਂਦਾ ਹੈ।",
    "One-off windows for specific dates — a trip, an exam. Block, allow-all-except, or a free period. Doesn't repeat.": "ਖ਼ਾਸ ਤਾਰੀਖ਼ਾਂ ਲਈ ਇੱਕ ਵਾਰ ਦੇ ਸਮੇਂ — ਸਫ਼ਰ, ਇਮਤਿਹਾਨ। ਬਲੌਕ, ਇਨ੍ਹਾਂ ਤੋਂ ਇਲਾਵਾ ਸਭ ਮਨਜ਼ੂਰ, ਜਾਂ ਖੁੱਲ੍ਹਾ ਸਮਾਂ। ਦੁਹਰਾਉਂਦਾ ਨਹੀਂ।",
    "Windows that repeat — daily, by weekday, or monthly. Each is either a block or a free period.": "ਦੁਹਰਾਉਣ ਵਾਲੇ ਸਮੇਂ — ਰੋਜ਼ਾਨਾ, ਹਫ਼ਤੇ ਦੇ ਦਿਨ ਮੁਤਾਬਕ, ਜਾਂ ਮਹੀਨਾਵਾਰ। ਹਰ ਇੱਕ ਜਾਂ ਬਲੌਕ ਹੈ ਜਾਂ ਖੁੱਲ੍ਹਾ ਸਮਾਂ।",
    "Limits don't block during the window, and time used inside it doesn't count against your daily budgets.": "ਇਸ ਸਮੇਂ ਦੌਰਾਨ ਹੱਦਾਂ ਬਲੌਕ ਨਹੀਂ ਕਰਦੀਆਂ, ਅਤੇ ਇਸ ਵਿੱਚ ਵਰਤਿਆ ਸਮਾਂ ਤੁਹਾਡੇ ਰੋਜ਼ਾਨਾ ਸਮੇਂ ਵਿੱਚ ਨਹੀਂ ਗਿਣਿਆ ਜਾਂਦਾ।",
    "Priority: a session beats a planned window, which beats a recurring schedule. Within the same kind, the one you added most recently wins.": "ਤਰਜੀਹ: ਸੈਸ਼ਨ ਯੋਜਨਾਬੱਧ ਸਮੇਂ ਨੂੰ ਹਰਾਉਂਦਾ ਹੈ, ਜੋ ਦੁਹਰਾਉਣ ਵਾਲੀ ਸਮਾਂ-ਸਾਰਣੀ ਨੂੰ ਹਰਾਉਂਦਾ ਹੈ। ਇੱਕੋ ਕਿਸਮ ਵਿੱਚ, ਤੁਹਾਡਾ ਸਭ ਤੋਂ ਹਾਲ ਹੀ ਵਿੱਚ ਜੋੜਿਆ ਜਿੱਤਦਾ ਹੈ।",
