    "Shown to people you ask to approve, so they know it's you.": "ਜਿਨ੍ਹਾਂ ਤੋਂ ਤੁਸੀਂ ਮਨਜ਼ੂਰੀ ਮੰਗਦੇ ਹੋ, ਉਨ੍ਹਾਂ ਨੂੰ ਦਿਖਾਇਆ ਜਾਂਦਾ ਹੈ, ਤਾਂ ਜੋ ਉਹ ਜਾਣ ਸਕਣ ਕਿ ਇਹ ਤੁਸੀਂ ਹੋ।",
    "People you approve for": "ਜਿਨ੍ਹਾਂ ਲਈ ਤੁਸੀਂ ਮਨਜ਼ੂਰੀ ਦਿੰਦੇ ਹੋ",
    "These people have you as a trusted contact. Removing yourself tells them and stops their requests.": "ਇਹ ਲੋਕ ਤੁਹਾਨੂੰ ਆਪਣਾ ਭਰੋਸੇਯੋਗ ਸੰਪਰਕ ਮੰਨਦੇ ਹਨ। ਆਪਣੇ ਆਪ ਨੂੰ ਹਟਾਉਣ ਨਾਲ ਉਨ੍ਹਾਂ ਨੂੰ ਪਤਾ ਲੱਗਦਾ ਹੈ ਅਤੇ ਉਨ੍ਹਾਂ ਦੀਆਂ ਬੇਨਤੀਆਂ ਬੰਦ ਹੋ ਜਾਂਦੀਆਂ ਹਨ।",
