    "Accept": "ਸਵੀਕਾਰ ਕਰੋ",
    "Decline": "ਠੁਕਰਾਓ",
    "Pending": "ਉਡੀਕ ਵਿੱਚ",
    "Waiting for them to accept in their Demora app.": "ਉਨ੍ਹਾਂ ਦੇ ਆਪਣੀ Demora ਐਪ ਵਿੱਚ ਸਵੀਕਾਰ ਕਰਨ ਦੀ ਉਡੀਕ ਹੈ।",
    "A trusted contact can let you skip a pending change's countdown — by emailing you a one-time code, or, if they use Demora, by approving from their own app.": "ਭਰੋਸੇਯੋਗ ਸੰਪਰਕ ਤੁਹਾਨੂੰ ਉਡੀਕ ਵਿੱਚ ਪਈ ਤਬਦੀਲੀ ਦੀ ਕਾਊਂਟਡਾਊਨ ਛੱਡਣ ਦੇ ਸਕਦਾ ਹੈ — ਤੁਹਾਨੂੰ ਇੱਕ-ਵਾਰ ਦਾ ਕੋਡ ਈਮੇਲ ਕਰਕੇ, ਜਾਂ, ਜੇ ਉਹ Demora ਵਰਤਦੇ ਹਨ, ਆਪਣੀ ਐਪ ਤੋਂ ਮਨਜ਼ੂਰ ਕਰਕੇ।",
    "Share this code so another Demora user can add you. You get a request to accept before it's active.": "ਇਹ ਕੋਡ ਸਾਂਝਾ ਕਰੋ ਤਾਂ ਜੋ ਕੋਈ ਹੋਰ Demora ਵਰਤੋਂਕਾਰ ਤੁਹਾਨੂੰ ਜੋੜ ਸਕੇ। ਚਾਲੂ ਹੋਣ ਤੋਂ ਪਹਿਲਾਂ ਤੁਹਾਨੂੰ ਸਵੀਕਾਰ ਕਰਨ ਲਈ ਬੇਨਤੀ ਮਿਲਦੀ ਹੈ।",
    "A Demora user (code %@) wants to add you as their trusted contact.": "ਇੱਕ Demora ਵਰਤੋਂਕਾਰ (ਕੋਡ %@) ਤੁਹਾਨੂੰ ਆਪਣਾ ਭਰੋਸੇਯੋਗ ਸੰਪਰਕ ਬਣਾਉਣਾ ਚਾਹੁੰਦਾ ਹੈ।",
    "%@ (code %@) wants to add you as their trusted contact.": "%@ (ਕੋਡ %@) ਤੁਹਾਨੂੰ ਆਪਣਾ ਭਰੋਸੇਯੋਗ ਸੰਪਰਕ ਬਣਾਉਣਾ ਚਾਹੁੰਦਾ ਹੈ।",
    "If you accept, they can ask you to approve skipping their delays.": "ਜੇ ਤੁਸੀਂ ਸਵੀਕਾਰ ਕਰੋ, ਤਾਂ ਉਹ ਆਪਣੀਆਂ ਦੇਰੀਆਂ ਛੱਡਣ ਲਈ ਤੁਹਾਡੀ ਮਨਜ਼ੂਰੀ ਮੰਗ ਸਕਦੇ ਹਨ।",
    "Email contacts work as soon as you add them. Demora-user contacts must accept first. Adding a contact is a less-strict change; removing one is stricter — both go through delays.": "ਈਮੇਲ ਸੰਪਰਕ ਜੋੜਦਿਆਂ ਹੀ ਕੰਮ ਕਰਨ ਲੱਗਦੇ ਹਨ। Demora ਵਰਤਣ ਵਾਲੇ ਸੰਪਰਕਾਂ ਨੂੰ ਪਹਿਲਾਂ ਸਵੀਕਾਰ ਕਰਨਾ ਪੈਂਦਾ ਹੈ। ਸੰਪਰਕ ਜੋੜਨਾ ਘੱਟ ਸਖ਼ਤ ਤਬਦੀਲੀ ਹੈ; ਹਟਾਉਣਾ ਵੱਧ ਸਖ਼ਤ ਹੈ — ਦੋਵੇਂ ਦੇਰੀਆਂ ਵਿੱਚੋਂ ਲੰਘਦੇ ਹਨ।",
