    "Adding a contact is a less-strict change; removing one is stricter — both go through delays.": "ਸੰਪਰਕ ਜੋੜਨਾ ਘੱਟ ਸਖ਼ਤ ਤਬਦੀਲੀ ਹੈ; ਹਟਾਉਣਾ ਵੱਧ ਸਖ਼ਤ ਹੈ — ਦੋਵੇਂ ਦੇਰੀਆਂ ਵਿੱਚੋਂ ਲੰਘਦੇ ਹਨ।",
