    "Ask them for the code shown in their Demora settings.": "ਉਨ੍ਹਾਂ ਦੀਆਂ Demora ਸੈਟਿੰਗਾਂ ਵਿੱਚ ਦਿਸਦਾ ਕੋਡ ਉਨ੍ਹਾਂ ਤੋਂ ਮੰਗੋ।",
    "Checking…": "ਜਾਂਚ ਹੋ ਰਹੀ ਹੈ…",
    "Checks automatically every few seconds. The request expires after 1 hour.": "ਹਰ ਕੁਝ ਸਕਿੰਟਾਂ ਬਾਅਦ ਆਪਣੇ ਆਪ ਜਾਂਚਦਾ ਹੈ। ਬੇਨਤੀ 1 ਘੰਟੇ ਬਾਅਦ ਮਿਆਦ ਪੁੱਗ ਜਾਂਦੀ ਹੈ।",
    "approvers, blocked": "ਮਨਜ਼ੂਰ ਕਰਨ ਵਾਲੇ, ਬਲੌਕ ਕੀਤੇ",
    "Couldn't send the request — check your connection and try again.": "ਬੇਨਤੀ ਨਹੀਂ ਭੇਜੀ ਜਾ ਸਕੀ — ਆਪਣਾ ਕੁਨੈਕਸ਼ਨ ਜਾਂਚੋ ਅਤੇ ਦੁਬਾਰਾ ਕੋਸ਼ਿਸ਼ ਕਰੋ।",
