    "Uses Apple's built-in filter to limit adult websites in Safari and other apps.": "Safari ਅਤੇ ਹੋਰ ਐਪਾਂ ਵਿੱਚ ਬਾਲਗ ਵੈੱਬਸਾਈਟਾਂ ਸੀਮਤ ਕਰਨ ਲਈ Apple ਦਾ ਆਪਣਾ ਫ਼ਿਲਟਰ ਵਰਤਦਾ ਹੈ।",
    "Website blocker": "ਵੈੱਬਸਾਈਟ ਬਲੌਕਰ",
