    "Queue: remove": "ਕਤਾਰ: ਹਟਾਓ",
    "Block specific websites by typing their domain — no need for Apple's site picker, which often comes up empty. Note: blocking sites also turns on Apple's adult-content filter. Adding a site is gated by your delays; removing one waits the longer delay.": "ਡੋਮੇਨ ਲਿਖ ਕੇ ਖ਼ਾਸ ਵੈੱਬਸਾਈਟਾਂ ਬਲੌਕ ਕਰੋ — Apple ਦੇ ਸਾਈਟ ਚੋਣਕਾਰ ਦੀ ਲੋੜ ਨਹੀਂ, ਜੋ ਅਕਸਰ ਖ਼ਾਲੀ ਆਉਂਦਾ ਹੈ। ਧਿਆਨ ਦਿਓ: ਸਾਈਟਾਂ ਬਲੌਕ ਕਰਨ ਨਾਲ Apple ਦਾ ਬਾਲਗ-ਸਮੱਗਰੀ ਫ਼ਿਲਟਰ ਵੀ ਚਾਲੂ ਹੋ ਜਾਂਦਾ ਹੈ। ਸਾਈਟ ਜੋੜਨਾ ਤੁਹਾਡੀਆਂ ਦੇਰੀਆਂ ਦੇ ਅਧੀਨ ਹੈ; ਹਟਾਉਣਾ ਲੰਮੀ ਦੇਰੀ ਦੀ ਉਡੀਕ ਕਰਦਾ ਹੈ।",
    "Blocked all day": "ਸਾਰਾ ਦਿਨ ਬਲੌਕ",
    "Adult websites": "ਬਾਲਗ ਵੈੱਬਸਾਈਟਾਂ",
    "%d sites": "%d ਸਾਈਟਾਂ",
    "Blocked sites": "ਬਲੌਕ ਕੀਤੀਆਂ ਸਾਈਟਾਂ",
    "Stop apps from being deleted, limit adult websites, or block specific sites by domain. Every change here goes through your delays.": "ਐਪਾਂ ਨੂੰ ਮਿਟਾਏ ਜਾਣ ਤੋਂ ਰੋਕੋ, ਬਾਲਗ ਵੈੱਬਸਾਈਟਾਂ ਸੀਮਤ ਕਰੋ, ਜਾਂ ਡੋਮੇਨ ਨਾਲ ਖ਼ਾਸ ਸਾਈਟਾਂ ਬਲੌਕ ਕਰੋ। ਇੱਥੇ ਹਰ ਤਬਦੀਲੀ ਤੁਹਾਡੀਆਂ ਦੇਰੀਆਂ ਵਿੱਚੋਂ ਲੰਘਦੀ ਹੈ।",
