    "Approval emails are at capacity right now. Try again later, or use a Demora contact.": "ਮਨਜ਼ੂਰੀ ਈਮੇਲਾਂ ਇਸ ਸਮੇਂ ਸਮਰੱਥਾ ਤੇ ਹਨ। ਬਾਅਦ ਵਿੱਚ ਦੁਬਾਰਾ ਕੋਸ਼ਿਸ਼ ਕਰੋ, ਜਾਂ Demora ਸੰਪਰਕ ਵਰਤੋ।",
