    "All users · this month": "ਸਾਰੇ ਵਰਤੋਂਕਾਰ · ਇਸ ਮਹੀਨੇ",
    "Email approvals": "ਈਮੇਲ ਮਨਜ਼ੂਰੀਆਂ",
    "Email contacts have a daily send limit; Demora-user contacts don't.": "ਈਮੇਲ ਸੰਪਰਕਾਂ ਦੀ ਰੋਜ਼ਾਨਾ ਭੇਜਣ ਦੀ ਹੱਦ ਹੈ; Demora ਵਰਤੋਂਕਾਰ ਸੰਪਰਕਾਂ ਦੀ ਨਹੀਂ।",
    "one-time, forever": "ਇੱਕ ਵਾਰ, ਹਮੇਸ਼ਾ ਲਈ",
