    "Enable trusted-contact override": "ਭਰੋਸੇਯੋਗ ਸੰਪਰਕ ਛੋਟ ਚਾਲੂ ਕਰੋ",
    "Friends who use Demora can add you as their trusted contact with this code.": "Demora ਵਰਤਣ ਵਾਲੇ ਦੋਸਤ ਇਸ ਕੋਡ ਨਾਲ ਤੁਹਾਨੂੰ ਆਪਣਾ ਭਰੋਸੇਯੋਗ ਸੰਪਰਕ ਬਣਾ ਸਕਦੇ ਹਨ।",
    "Demora user": "Demora ਵਰਤੋਂਕਾਰ",
