    "No Demora user found with that code.": "ਉਸ ਕੋਡ ਵਾਲਾ ਕੋਈ Demora ਵਰਤੋਂਕਾਰ ਨਹੀਂ ਮਿਲਿਆ।",
    "Remove trusted contact: %@": "ਭਰੋਸੇਯੋਗ ਸੰਪਰਕ ਹਟਾਓ: %@",
    "Send request": "ਬੇਨਤੀ ਭੇਜੋ",
    "Sending…": "ਭੇਜ ਰਿਹਾ ਹੈ…",
    "Someone set you as their trusted contact and wants to skip a waiting period.": "ਕਿਸੇ ਨੇ ਤੁਹਾਨੂੰ ਆਪਣਾ ਭਰੋਸੇਯੋਗ ਸੰਪਰਕ ਬਣਾਇਆ ਹੈ ਅਤੇ ਉਹ ਉਡੀਕ ਦੀ ਮਿਆਦ ਛੱਡਣੀ ਚਾਹੁੰਦਾ ਹੈ।",
    "Their Demora code": "ਉਨ੍ਹਾਂ ਦਾ Demora ਕੋਡ",
    "Trusted contacts": "ਭਰੋਸੇਯੋਗ ਸੰਪਰਕ",
    "Verify code": "ਕੋਡ ਪੁਸ਼ਟੀ ਕਰੋ",
    "When enabled, a trusted contact can let you skip a pending change's countdown — by emailing you a code, or by approving from their own Demora app.": "ਚਾਲੂ ਹੋਣ ਤੇ, ਭਰੋਸੇਯੋਗ ਸੰਪਰਕ ਤੁਹਾਨੂੰ ਉਡੀਕ ਵਿੱਚ ਪਈ ਤਬਦੀਲੀ ਦੀ ਕਾਊਂਟਡਾਊਨ ਛੱਡਣ ਦੇ ਸਕਦਾ ਹੈ — ਤੁਹਾਨੂੰ ਕੋਡ ਈਮੇਲ ਕਰਕੇ, ਜਾਂ ਆਪਣੀ Demora ਐਪ ਤੋਂ ਮਨਜ਼ੂਰ ਕਰਕੇ।",
    "Wrong or expired code.": "ਗ਼ਲਤ ਜਾਂ ਮਿਆਦ ਪੁੱਗਿਆ ਕੋਡ।",
    "Your contact received a code by email. Enter it here. It expires in 15 minutes.": "ਤੁਹਾਡੇ ਸੰਪਰਕ ਨੂੰ ਈਮੇਲ ਤੇ ਕੋਡ ਮਿਲਿਆ। ਇਹ ਇੱਥੇ ਭਰੋ। ਇਹ 15 ਮਿੰਟ ਵਿੱਚ ਮਿਆਦ ਪੁੱਗ ਜਾਂਦਾ ਹੈ।",
    "contact": "ਸੰਪਰਕ",
    "e.g. Mom, Alex": "ਜਿਵੇਂ ਮੰਮੀ, ਅਲੈਕਸ",
    "%@ (%d problems)": "%@ (%d ਸਵਾਲ)",
    "%@ session: %@ (%d min)": "%@ ਸੈਸ਼ਨ: %@ (%d ਮਿੰਟ)",
    "%@ — session starts in %@, then runs %d min": "%@ — ਸੈਸ਼ਨ %@ ਵਿੱਚ ਸ਼ੁਰੂ ਹੁੰਦਾ ਹੈ, ਫਿਰ %d ਮਿੰਟ ਚੱਲਦਾ ਹੈ",
    "%@ — takes effect in %@": "%@ — %@ ਵਿੱਚ ਲਾਗੂ ਹੁੰਦਾ ਹੈ",
    "%d apps, %d categories": "%d ਐਪਾਂ, %d ਸ਼੍ਰੇਣੀਆਂ",
    "%d hr": "%d ਘੰਟੇ",
    "%d min": "%d ਮਿੰਟ",
    "%d min/day": "%d ਮਿੰਟ/ਦਿਨ",
    "%d minutes": "%d ਮਿੰਟ",
    "%d minutes/day": "%d ਮਿੰਟ/ਦਿਨ",
    "%d selected": "%d ਚੁਣੇ",
    "ACTIVE": "ਚਾਲੂ",
    "Add a daily time limit. It activates after your 'more strict' delay (%@).": "ਰੋਜ਼ਾਨਾ ਸਮੇਂ ਦੀ ਹੱਦ ਜੋੜੋ। ਇਹ ਤੁਹਾਡੀ 'ਵੱਧ ਸਖ਼ਤ' ਦੇਰੀ (%@) ਤੋਂ ਬਾਅਦ ਚਾਲੂ ਹੁੰਦੀ ਹੈ।",
    "Add free period: %@ (%@)": "ਖੁੱਲ੍ਹਾ ਸਮਾਂ ਜੋੜੋ: %@ (%@)",
    "Add free period…": "ਖੁੱਲ੍ਹਾ ਸਮਾਂ ਜੋੜੋ…",
    "Add limit: %@ — %d min/day": "ਹੱਦ ਜੋੜੋ: %@ — %d ਮਿੰਟ/ਦਿਨ",
    "Add me": "ਮੈਨੂੰ ਜੋੜੋ",
    "Add my name…": "ਆਪਣਾ ਨਾਮ ਜੋੜੋ…",
    "Add schedule: %@ (%@ %@)": "ਸਮਾਂ-ਸਾਰਣੀ ਜੋੜੋ: %@ (%@ %@)",
    "Add schedule…": "ਸਮਾਂ-ਸਾਰਣੀ ਜੋੜੋ…",
    "Adding…": "ਜੋੜ ਰਿਹਾ ਹੈ…",
    "Allow app deletion": "ਐਪ ਮਿਟਾਉਣ ਦੀ ਇਜਾਜ਼ਤ ਦਿਓ",
    "App deletion": "ਐਪ ਮਿਟਾਉਣਾ",
    "Apply now…": "ਹੁਣੇ ਲਾਗੂ ਕਰੋ…",
    "Permissions": "ਇਜਾਜ਼ਤਾਂ",
    "Demora needs Screen Time access to set limits and block apps, and notifications to tell you when a pending change is ready. iOS will ask for each.": "Demora ਨੂੰ ਹੱਦਾਂ ਲਾਉਣ ਅਤੇ ਐਪਾਂ ਬਲੌਕ ਕਰਨ ਲਈ ਸਕ੍ਰੀਨ ਟਾਈਮ ਦੀ ਪਹੁੰਚ ਚਾਹੀਦੀ ਹੈ, ਅਤੇ ਉਡੀਕ ਵਿੱਚ ਪਈ ਤਬਦੀਲੀ ਤਿਆਰ ਹੋਣ ਤੇ ਦੱਸਣ ਲਈ ਸੂਚਨਾਵਾਂ। iOS ਹਰ ਇੱਕ ਲਈ ਪੁੱਛੇਗਾ।",
    "Grant access": "ਪਹੁੰਚ ਦਿਓ",
    "Welcome to Demora": "Demora ਵਿੱਚ ਜੀ ਆਇਆਂ ਨੂੰ",
    "Demora can be a lot at first, so let's set up your first limit together — a quick, hands-on walkthrough of how delays and overrides actually feel. It takes about a minute.": "ਸ਼ੁਰੂ ਵਿੱਚ Demora ਥੋੜ੍ਹਾ ਭਾਰੀ ਲੱਗ ਸਕਦਾ ਹੈ, ਇਸ ਲਈ ਆਓ ਮਿਲ ਕੇ ਤੁਹਾਡੀ ਪਹਿਲੀ ਹੱਦ ਸੈੱਟ ਕਰੀਏ — ਇੱਕ ਛੋਟੀ, ਹੱਥੀਂ ਸੈਰ ਕਿ ਦੇਰੀਆਂ ਅਤੇ ਛੋਟਾਂ ਅਸਲ ਵਿੱਚ ਕਿਹੋ ਜਿਹੀਆਂ ਲੱਗਦੀਆਂ ਹਨ। ਇਸ ਵਿੱਚ ਲਗਭਗ ਇੱਕ ਮਿੰਟ ਲੱਗਦਾ ਹੈ।",
    "Add my first limit": "ਮੇਰੀ ਪਹਿਲੀ ਹੱਦ ਜੋੜੋ",
    "Add your first limit": "ਆਪਣੀ ਪਹਿਲੀ ਹੱਦ ਜੋੜੋ",
    "Add a recurring schedule": "ਦੁਹਰਾਉਣ ਵਾਲੀ ਸਮਾਂ-ਸਾਰਣੀ ਜੋੜੋ",
    "Add a sample contact": "ਨਮੂਨੇ ਦਾ ਸੰਪਰਕ ਜੋੜੋ",
    "Adding a trusted contact normally waits out a delay. In this tutorial it's instant.": "ਭਰੋਸੇਯੋਗ ਸੰਪਰਕ ਜੋੜਨਾ ਆਮ ਤੌਰ ਤੇ ਦੇਰੀ ਦੀ ਉਡੀਕ ਕਰਦਾ ਹੈ। ਇਸ ਟਿਊਟੋਰੀਅਲ ਵਿੱਚ ਇਹ ਤੁਰੰਤ ਹੈ।",
    "Alex (sample)": "ਅਲੈਕਸ (ਨਮੂਨਾ)",
    "Now a schedule. Tap ‘Add a recurring schedule’, pick a time window and some apps, then queue it.": "ਹੁਣ ਇੱਕ ਸਮਾਂ-ਸਾਰਣੀ। ‘ਦੁਹਰਾਉਣ ਵਾਲੀ ਸਮਾਂ-ਸਾਰਣੀ ਜੋੜੋ’ ਛੂਹੋ, ਸਮੇਂ ਦੀ ਖਿੜਕੀ ਅਤੇ ਕੁਝ ਐਪਾਂ ਚੁਣੋ, ਫਿਰ ਇਸਨੂੰ ਕਤਾਰ ਵਿੱਚ ਲਾਓ।",
    "Two changes are waiting, and you can't wait them out. Tap Select, choose both, Apply — then use the password override. The password is: test": "ਦੋ ਤਬਦੀਲੀਆਂ ਉਡੀਕ ਵਿੱਚ ਹਨ, ਅਤੇ ਤੁਸੀਂ ਉਡੀਕ ਪੂਰੀ ਨਹੀਂ ਕਰ ਸਕਦੇ। ਚੁਣੋ ਛੂਹੋ, ਦੋਵੇਂ ਚੁਣੋ, ਲਾਗੂ ਕਰੋ — ਫਿਰ ਪਾਸਵਰਡ ਛੋਟ ਵਰਤੋ। ਪਾਸਵਰਡ ਹੈ: test",
    "Open Calendar to see everything laid out by day.": "ਹਰ ਚੀਜ਼ ਦਿਨ ਮੁਤਾਬਕ ਦੇਖਣ ਲਈ ਕੈਲੰਡਰ ਖੋਲ੍ਹੋ।",
    "Now tidy up: remove the recurring schedule here, and the limit over in Limits.": "ਹੁਣ ਸਫ਼ਾਈ ਕਰੋ: ਦੁਹਰਾਉਣ ਵਾਲੀ ਸਮਾਂ-ਸਾਰਣੀ ਇੱਥੇ ਹਟਾਓ, ਅਤੇ ਹੱਦ ਹੱਦਾਂ ਵਿੱਚ ਜਾ ਕੇ।",
    "Now tidy up: open Recurring and remove the schedule you made.": "ਹੁਣ ਸਫ਼ਾਈ ਕਰੋ: ਦੁਹਰਾਉਣ ਵਾਲਾ ਖੋਲ੍ਹੋ ਅਤੇ ਤੁਹਾਡੀ ਬਣਾਈ ਸਮਾਂ-ਸਾਰਣੀ ਹਟਾਓ।",
    "And the limit: tap it, then Remove this limit.": "ਅਤੇ ਹੱਦ: ਇਸਨੂੰ ਛੂਹੋ, ਫਿਰ ਇਹ ਹੱਦ ਹਟਾਓ।",
    "Let's add a backup approver. Open Rules → Overrides → Trusted contacts and add a sample contact.": "ਆਓ ਇੱਕ ਬਦਲਵਾਂ ਮਨਜ਼ੂਰ ਕਰਨ ਵਾਲਾ ਜੋੜੀਏ। ਨਿਯਮ → ਛੋਟਾਂ → ਭਰੋਸੇਯੋਗ ਸੰਪਰਕ ਖੋਲ੍ਹੋ ਅਤੇ ਨਮੂਨੇ ਦਾ ਸੰਪਰਕ ਜੋੜੋ।",
    "Home delays": "ਹੋਮ ਦੇਰੀਆਂ",
    "Home overrides": "ਹੋਮ ਛੋਟਾਂ",
    "shown": "ਦਿਖਾਇਆ",
    "hidden": "ਲੁਕਾਇਆ",
    "Rules": "ਨਿਯਮ",
    "Current overrides": "ਮੌਜੂਦਾ ਛੋਟਾਂ",
    "No overrides on": "ਕੋਈ ਛੋਟ ਚਾਲੂ ਨਹੀਂ",
    "Code": "ਕੋਡ",
    "Name (optional)": "ਨਾਮ (ਵਿਕਲਪਿਕ)",
    "Unnamed": "ਬਿਨਾਂ ਨਾਮ",
    "Waiting for them to enter their code.": "ਉਨ੍ਹਾਂ ਦੇ ਆਪਣਾ ਕੋਡ ਭਰਨ ਦੀ ਉਡੀਕ ਹੈ।",
    "Added as a trusted contact": "ਭਰੋਸੇਯੋਗ ਸੰਪਰਕ ਵਜੋਂ ਜੋੜਿਆ ਗਿਆ",
    "Add as trusted contact": "ਭਰੋਸੇਯੋਗ ਸੰਪਰਕ ਵਜੋਂ ਜੋੜੋ",
    "They get a request to accept right away. They can approve for you once the wait ends.": "ਉਨ੍ਹਾਂ ਨੂੰ ਤੁਰੰਤ ਸਵੀਕਾਰ ਕਰਨ ਲਈ ਬੇਨਤੀ ਮਿਲਦੀ ਹੈ। ਉਡੀਕ ਮੁੱਕਣ ਤੇ ਉਹ ਤੁਹਾਡੇ ਲਈ ਮਨਜ਼ੂਰ ਕਰ ਸਕਦੇ ਹਨ।",
    "Removing yourself tells them and stops their requests.": "ਆਪਣੇ ਆਪ ਨੂੰ ਹਟਾਉਣ ਨਾਲ ਉਨ੍ਹਾਂ ਨੂੰ ਪਤਾ ਲੱਗਦਾ ਹੈ ਅਤੇ ਉਨ੍ਹਾਂ ਦੀਆਂ ਬੇਨਤੀਆਂ ਬੰਦ ਹੋ ਜਾਂਦੀਆਂ ਹਨ।",
    "That's your own code.": "ਇਹ ਤੁਹਾਡਾ ਆਪਣਾ ਕੋਡ ਹੈ।",
    "These people have you as a trusted contact. Tap one to see their details or add them back. Removing yourself tells them and stops their requests.": "ਇਹ ਲੋਕ ਤੁਹਾਨੂੰ ਆਪਣਾ ਭਰੋਸੇਯੋਗ ਸੰਪਰਕ ਮੰਨਦੇ ਹਨ। ਕਿਸੇ ਨੂੰ ਛੂਹ ਕੇ ਉਸਦੇ ਵੇਰਵੇ ਦੇਖੋ ਜਾਂ ਉਸਨੂੰ ਵਾਪਸ ਜੋੜੋ। ਆਪਣੇ ਆਪ ਨੂੰ ਹਟਾਉਣ ਨਾਲ ਉਨ੍ਹਾਂ ਨੂੰ ਪਤਾ ਲੱਗਦਾ ਹੈ ਅਤੇ ਉਨ੍ਹਾਂ ਦੀਆਂ ਬੇਨਤੀਆਂ ਬੰਦ ਹੋ ਜਾਂਦੀਆਂ ਹਨ।",
    "Confirmed": "ਪੁਸ਼ਟੀ ਹੋਈ",
    "Send confirmation code": "ਪੁਸ਼ਟੀ ਕੋਡ ਭੇਜੋ",
    "Resend code": "ਕੋਡ ਦੁਬਾਰਾ ਭੇਜੋ",
    "Confirm contact": "ਸੰਪਰਕ ਦੀ ਪੁਸ਼ਟੀ ਕਰੋ",
    "We email a code to this address. Your contact gives you the code, you enter it here, and then they can approve for you. Until then they can't.": "ਅਸੀਂ ਇਸ ਪਤੇ ਤੇ ਇੱਕ ਕੋਡ ਈਮੇਲ ਕਰਦੇ ਹਾਂ। ਤੁਹਾਡਾ ਸੰਪਰਕ ਤੁਹਾਨੂੰ ਕੋਡ ਦਿੰਦਾ ਹੈ, ਤੁਸੀਂ ਇਹ ਇੱਥੇ ਭਰਦੇ ਹੋ, ਅਤੇ ਫਿਰ ਉਹ ਤੁਹਾਡੇ ਲਈ ਮਨਜ਼ੂਰ ਕਰ ਸਕਦੇ ਹਨ। ਉਦੋਂ ਤੱਕ ਨਹੀਂ ਕਰ ਸਕਦੇ।",
    "Code sent. Ask your contact for it.": "ਕੋਡ ਭੇਜਿਆ। ਆਪਣੇ ਸੰਪਰਕ ਤੋਂ ਮੰਗੋ।",
    "Daily email limit reached. Try again later.": "ਰੋਜ਼ਾਨਾ ਈਮੇਲ ਦੀ ਹੱਦ ਪੂਰੀ ਹੋ ਗਈ। ਬਾਅਦ ਵਿੱਚ ਦੁਬਾਰਾ ਕੋਸ਼ਿਸ਼ ਕਰੋ।",
    "You've sent too many codes today. Try again tomorrow.": "ਤੁਸੀਂ ਅੱਜ ਬਹੁਤ ਸਾਰੇ ਕੋਡ ਭੇਜ ਲਏ ਹਨ। ਕੱਲ੍ਹ ਦੁਬਾਰਾ ਕੋਸ਼ਿਸ਼ ਕਰੋ।",
    "Couldn't send the code. Check your connection and try again.": "ਕੋਡ ਨਹੀਂ ਭੇਜਿਆ ਜਾ ਸਕਿਆ। ਆਪਣਾ ਕੁਨੈਕਸ਼ਨ ਜਾਂਚੋ ਅਤੇ ਦੁਬਾਰਾ ਕੋਸ਼ਿਸ਼ ਕਰੋ।",
    "That code didn't match. Double-check and try again.": "ਉਹ ਕੋਡ ਮੇਲ ਨਹੀਂ ਖਾਂਦਾ। ਦੁਬਾਰਾ ਜਾਂਚ ਕੇ ਮੁੜ ਕੋਸ਼ਿਸ਼ ਕਰੋ।",
    "Elementary": "ਮੁੱਢਲਾ",
    "Middle school": "ਮਿਡਲ ਸਕੂਲ",
    "High school": "ਹਾਈ ਸਕੂਲ",
    "Very easy": "ਬਹੁਤ ਆਸਾਨ",
    "Your change is ready": "ਤੁਹਾਡੀ ਤਬਦੀਲੀ ਤਿਆਰ ਹੈ",
    "Your limits have reset": "ਤੁਹਾਡੀਆਂ ਹੱਦਾਂ ਰੀਸੈੱਟ ਹੋ ਗਈਆਂ ਹਨ",
    "If any apps still look blocked, open Demora to refresh them.": "ਜੇ ਕੋਈ ਐਪ ਅਜੇ ਵੀ ਬਲੌਕ ਦਿਸੇ, ਤਾਂ ਉਨ੍ਹਾਂ ਨੂੰ ਤਾਜ਼ਾ ਕਰਨ ਲਈ Demora ਖੋਲ੍ਹੋ।",
    "If you denied access, turn on Screen Time for Demora in Settings, then come back.": "ਜੇ ਤੁਸੀਂ ਪਹੁੰਚ ਤੋਂ ਇਨਕਾਰ ਕੀਤਾ ਸੀ, ਤਾਂ ਸੈਟਿੰਗਾਂ ਵਿੱਚ Demora ਲਈ ਸਕ੍ਰੀਨ ਟਾਈਮ ਚਾਲੂ ਕਰੋ, ਫਿਰ ਵਾਪਸ ਆਓ।",
    "Open Settings": "ਸੈਟਿੰਗਾਂ ਖੋਲ੍ਹੋ",
    "Couldn't check the code — check your connection and try again.": "ਕੋਡ ਨਹੀਂ ਜਾਂਚਿਆ ਜਾ ਸਕਿਆ — ਆਪਣਾ ਕੁਨੈਕਸ਼ਨ ਜਾਂਚੋ ਅਤੇ ਦੁਬਾਰਾ ਕੋਸ਼ਿਸ਼ ਕਰੋ।",
    "Couldn't send your response — check your connection and try again.": "ਤੁਹਾਡਾ ਜਵਾਬ ਨਹੀਂ ਭੇਜਿਆ ਜਾ ਸਕਿਆ — ਆਪਣਾ ਕੁਨੈਕਸ਼ਨ ਜਾਂਚੋ ਅਤੇ ਦੁਬਾਰਾ ਕੋਸ਼ਿਸ਼ ਕਰੋ।",
    "Those changes are still counting down. Wait them out, or turn on an override in Settings → Rules → Overrides to skip the wait.": "ਉਹ ਤਬਦੀਲੀਆਂ ਅਜੇ ਵੀ ਕਾਊਂਟਡਾਊਨ ਵਿੱਚ ਹਨ। ਉਡੀਕ ਪੂਰੀ ਕਰੋ, ਜਾਂ ਉਡੀਕ ਛੱਡਣ ਲਈ ਸੈਟਿੰਗਾਂ → ਨਿਯਮ → ਛੋਟਾਂ ਵਿੱਚ ਕੋਈ ਛੋਟ ਚਾਲੂ ਕਰੋ।",
