    "Compare this code with your contact in person or on a call. If it matches on both phones, no one has tampered with the connection.": "ਇਹ ਕੋਡ ਆਪਣੇ ਸੰਪਰਕ ਨਾਲ ਆਹਮੋ-ਸਾਹਮਣੇ ਜਾਂ ਕਾਲ ਤੇ ਮਿਲਾਓ। ਜੇ ਦੋਵੇਂ ਫ਼ੋਨਾਂ ਤੇ ਇਹ ਮਿਲ ਜਾਵੇ, ਤਾਂ ਕਿਸੇ ਨੇ ਕੁਨੈਕਸ਼ਨ ਨਾਲ ਛੇੜਛਾੜ ਨਹੀਂ ਕੀਤੀ।",
    "Background blocking may be incomplete": "ਬੈਕਗ੍ਰਾਊਂਡ ਬਲੌਕਿੰਗ ਅਧੂਰੀ ਹੋ ਸਕਦੀ ਹੈ",
    "Part of Demora's background blocking couldn't be set up. It keeps trying on its own.": "Demora ਦੀ ਬੈਕਗ੍ਰਾਊਂਡ ਬਲੌਕਿੰਗ ਦਾ ਕੁਝ ਹਿੱਸਾ ਸੈੱਟ ਨਹੀਂ ਹੋ ਸਕਿਆ। ਇਹ ਆਪਣੇ ਆਪ ਕੋਸ਼ਿਸ਼ ਜਾਰੀ ਰੱਖਦੀ ਹੈ।",
