    "No limit-reached signal today": "ਅੱਜ ਸੀਮਾ ਪੂਰੀ ਹੋਣ ਦਾ ਸੰਕੇਤ ਨਹੀਂ",
    "Free-time credit: %ld min": "ਫ੍ਰੀ ਟਾਈਮ ਕ੍ਰੈਡਿਟ: %ld ਮਿੰਟ",
    "Free time running since %@": "%@ ਤੋਂ ਫ੍ਰੀ ਟਾਈਮ ਚੱਲ ਰਿਹਾ ਹੈ",
    "iOS limits how many limits and schedules can run in the background at once. Removing a few restores full enforcement.": "iOS ਸੀਮਤ ਕਰਦਾ ਹੈ ਕਿ ਕਿੰਨੀਆਂ ਹੱਦਾਂ ਅਤੇ ਸਮਾਂ-ਸਾਰਣੀਆਂ ਇੱਕੋ ਵੇਲੇ ਬੈਕਗ੍ਰਾਊਂਡ ਵਿੱਚ ਚੱਲ ਸਕਦੀਆਂ ਹਨ। ਕੁਝ ਹਟਾਉਣ ਨਾਲ ਪੂਰੀ ਲਾਗੂਕਰਨ ਬਹਾਲ ਹੋ ਜਾਂਦੀ ਹੈ।",
