    "Blocked user": "ਬਲੌਕ ਕੀਤਾ ਵਰਤੋਂਕਾਰ",
    "Two removals are pending. Tap Select, choose both, Apply — then approve with your trusted contact instead of the password.": "ਦੋ ਹਟਾਉਣ ਉਡੀਕ ਵਿੱਚ ਹਨ। ਚੁਣੋ ਛੂਹੋ, ਦੋਵੇਂ ਚੁਣੋ, ਲਾਗੂ ਕਰੋ — ਫਿਰ ਪਾਸਵਰਡ ਦੀ ਥਾਂ ਆਪਣੇ ਭਰੋਸੇਯੋਗ ਸੰਪਰਕ ਨਾਲ ਮਨਜ਼ੂਰ ਕਰੋ।",
    "Waiting for approval…": "ਮਨਜ਼ੂਰੀ ਦੀ ਉਡੀਕ ਹੈ…",
    "%d changes: %@": "%d ਤਬਦੀਲੀਆਂ: %@",
