    "Privacy Policy": "ਪਰਦੇਦਾਰੀ ਨੀਤੀ",
    "Terms of Use": "ਵਰਤੋਂ ਦੀਆਂ ਸ਼ਰਤਾਂ",
    "Almost done": "ਲਗਭਗ ਹੋ ਗਿਆ",
    "Nice work — that's the whole loop. Now set the delays and overrides that will actually protect you.": "ਵਧੀਆ — ਇਹੀ ਪੂਰਾ ਚੱਕਰ ਹੈ। ਹੁਣ ਉਹ ਦੇਰੀਆਂ ਅਤੇ ਛੋਟਾਂ ਸੈੱਟ ਕਰੋ ਜੋ ਅਸਲ ਵਿੱਚ ਤੁਹਾਡੀ ਰੱਖਿਆ ਕਰਨਗੀਆਂ।",
    "Finish setup": "ਸੈੱਟਅੱਪ ਪੂਰਾ ਕਰੋ",
    "Tap ‘Add your first limit’, choose an app or two and a daily budget, then queue the change.": "‘ਆਪਣੀ ਪਹਿਲੀ ਹੱਦ ਜੋੜੋ’ ਛੂਹੋ, ਇੱਕ-ਦੋ ਐਪਾਂ ਅਤੇ ਰੋਜ਼ਾਨਾ ਸਮਾਂ ਚੁਣੋ, ਫਿਰ ਤਬਦੀਲੀ ਨੂੰ ਕਤਾਰ ਵਿੱਚ ਲਾਓ।",
    "Your change is waiting out its delay — and you can't wait this one out. Tap ‘Apply now…’ and use the password override. The password is: test": "ਤੁਹਾਡੀ ਤਬਦੀਲੀ ਆਪਣੀ ਦੇਰੀ ਦੀ ਉਡੀਕ ਕਰ ਰਹੀ ਹੈ — ਅਤੇ ਇਹ ਉਡੀਕ ਤੁਸੀਂ ਪੂਰੀ ਨਹੀਂ ਕਰ ਸਕਦੇ। ‘ਹੁਣੇ ਲਾਗੂ ਕਰੋ…’ ਛੂਹੋ ਅਤੇ ਪਾਸਵਰਡ ਛੋਟ ਵਰਤੋ। ਪਾਸਵਰਡ ਹੈ: test",
    "Now remove it: tap the limit, then ‘Remove this limit’.": "ਹੁਣ ਇਸਨੂੰ ਹਟਾਓ: ਹੱਦ ਨੂੰ ਛੂਹੋ, ਫਿਰ ‘ਇਹ ਹੱਦ ਹਟਾਓ’।",
    "Same again — tap ‘Apply now…’ and enter the password (test).": "ਫਿਰ ਉਹੀ — ‘ਹੁਣੇ ਲਾਗੂ ਕਰੋ…’ ਛੂਹੋ ਅਤੇ ਪਾਸਵਰਡ (test) ਭਰੋ।",
    "For this tutorial, only the password works. The password is: test": "ਇਸ ਟਿਊਟੋਰੀਅਲ ਲਈ ਸਿਰਫ਼ ਪਾਸਵਰਡ ਚੱਲਦਾ ਹੈ। ਪਾਸਵਰਡ ਹੈ: test",
    "Everything here is just a sample — nothing is saved and nothing is actually blocked. It's only to show how the app works.": "ਇੱਥੇ ਸਭ ਕੁਝ ਸਿਰਫ਼ ਨਮੂਨਾ ਹੈ — ਕੁਝ ਵੀ ਸੰਭਾਲਿਆ ਨਹੀਂ ਜਾਂਦਾ ਅਤੇ ਕੁਝ ਵੀ ਸੱਚਮੁੱਚ ਬਲੌਕ ਨਹੀਂ ਹੁੰਦਾ। ਇਹ ਸਿਰਫ਼ ਇਹ ਦਿਖਾਉਣ ਲਈ ਹੈ ਕਿ ਐਪ ਕਿਵੇਂ ਕੰਮ ਕਰਦੀ ਹੈ।",
