    "Changes that make things LESS STRICT (raise a limit, remove a block, add a free period) wait out your second delay — usually set longer.": "ਜਿਹੜੀਆਂ ਤਬਦੀਲੀਆਂ ਚੀਜ਼ਾਂ ਨੂੰ ਘੱਟ ਸਖ਼ਤ ਕਰਦੀਆਂ ਹਨ (ਹੱਦ ਵਧਾਉਣਾ, ਬਲੌਕ ਹਟਾਉਣਾ, ਖੁੱਲ੍ਹਾ ਸਮਾਂ ਜੋੜਨਾ) ਉਹ ਤੁਹਾਡੀ ਦੂਜੀ ਦੇਰੀ ਦੀ ਉਡੀਕ ਕਰਦੀਆਂ ਹਨ — ਆਮ ਤੌਰ ਤੇ ਲੰਮੀ ਰੱਖੀ ਜਾਂਦੀ ਹੈ।",
    "Changes that make things STRICTER (add a limit, lower minutes, add a schedule) wait out your first delay.": "ਜਿਹੜੀਆਂ ਤਬਦੀਲੀਆਂ ਚੀਜ਼ਾਂ ਨੂੰ ਵੱਧ ਸਖ਼ਤ ਕਰਦੀਆਂ ਹਨ (ਹੱਦ ਜੋੜਨਾ, ਮਿੰਟ ਘਟਾਉਣਾ, ਸਮਾਂ-ਸਾਰਣੀ ਜੋੜਨਾ) ਉਹ ਤੁਹਾਡੀ ਪਹਿਲੀ ਦੇਰੀ ਦੀ ਉਡੀਕ ਕਰਦੀਆਂ ਹਨ।",
    "Changes you make will appear here with a countdown.": "ਤੁਹਾਡੀਆਂ ਤਬਦੀਲੀਆਂ ਇੱਥੇ ਕਾਊਂਟਡਾਊਨ ਨਾਲ ਦਿਸਣਗੀਆਂ।",
