    "During a free period, limits don't block and usage inside the window doesn't count toward them — time used before the window still does.": "ਖੁੱਲ੍ਹੇ ਸਮੇਂ ਦੌਰਾਨ ਹੱਦਾਂ ਬਲੌਕ ਨਹੀਂ ਕਰਦੀਆਂ ਅਤੇ ਇਸ ਖਿੜਕੀ ਅੰਦਰ ਦੀ ਵਰਤੋਂ ਉਨ੍ਹਾਂ ਵਿੱਚ ਨਹੀਂ ਗਿਣੀ ਜਾਂਦੀ — ਖਿੜਕੀ ਤੋਂ ਪਹਿਲਾਂ ਵਰਤਿਆ ਸਮਾਂ ਫਿਰ ਵੀ ਗਿਣਿਆ ਜਾਂਦਾ ਹੈ।",
