    "Every change you make waits out a delay you chose, counting down in the background. You can always change your rules — just not in a moment of weakness.": "ਤੁਹਾਡੀ ਹਰ ਤਬਦੀਲੀ ਤੁਹਾਡੀ ਚੁਣੀ ਦੇਰੀ ਦੀ ਉਡੀਕ ਕਰਦੀ ਹੈ, ਜੋ ਬੈਕਗ੍ਰਾਊਂਡ ਵਿੱਚ ਗਿਣਤੀ ਕਰਦੀ ਰਹਿੰਦੀ ਹੈ। ਤੁਸੀਂ ਆਪਣੇ ਨਿਯਮ ਹਮੇਸ਼ਾ ਬਦਲ ਸਕਦੇ ਹੋ — ਬੱਸ ਕਮਜ਼ੋਰ ਪਲ ਵਿੱਚ ਨਹੀਂ।",
    "Every day": "ਹਰ ਦਿਨ",
    "Everything on the iPhone is blocked during the window except the apps picked here.": "ਇਸ ਖਿੜਕੀ ਦੌਰਾਨ iPhone ਤੇ ਸਭ ਕੁਝ ਬਲੌਕ ਹੈ, ਸਿਰਫ਼ ਇੱਥੇ ਚੁਣੀਆਂ ਐਪਾਂ ਨੂੰ ਛੱਡ ਕੇ।",
    "Free period": "ਖੁੱਲ੍ਹਾ ਸਮਾਂ",
    "Today's usage is reported by iOS Screen Time, which can be slow to load or briefly show nothing. If it looks empty, tap the refresh arrow a couple of times.": "ਅੱਜ ਦੀ ਵਰਤੋਂ iOS ਸਕ੍ਰੀਨ ਟਾਈਮ ਦੱਸਦਾ ਹੈ, ਜੋ ਲੋਡ ਹੋਣ ਵਿੱਚ ਹੌਲੀ ਹੋ ਸਕਦਾ ਹੈ ਜਾਂ ਥੋੜ੍ਹੀ ਦੇਰ ਕੁਝ ਨਹੀਂ ਦਿਖਾਉਂਦਾ। ਜੇ ਇਹ ਖ਼ਾਲੀ ਦਿਸੇ ਤਾਂ ਤਾਜ਼ਾ ਕਰਨ ਵਾਲਾ ਤੀਰ ਦੋ-ਤਿੰਨ ਵਾਰ ਛੂਹੋ।",
    "Free": "ਖੁੱਲ੍ਹਾ",
    "Free period: %@ (%d min)": "ਖੁੱਲ੍ਹਾ ਸਮਾਂ: %@ (%d ਮਿੰਟ)",
    "Free period — nothing is blocked": "ਖੁੱਲ੍ਹਾ ਸਮਾਂ — ਕੁਝ ਵੀ ਬਲੌਕ ਨਹੀਂ",
    "Temporarily lifts everything — no app blocks apply, and usage during the free period doesn't count toward your limits.": "ਸਭ ਕੁਝ ਅਸਥਾਈ ਤੌਰ ਤੇ ਹਟਾਉਂਦਾ ਹੈ — ਕੋਈ ਐਪ ਬਲੌਕ ਲਾਗੂ ਨਹੀਂ, ਅਤੇ ਖੁੱਲ੍ਹੇ ਸਮੇਂ ਦੌਰਾਨ ਦੀ ਵਰਤੋਂ ਤੁਹਾਡੀਆਂ ਹੱਦਾਂ ਵਿੱਚ ਨਹੀਂ ਗਿਣੀ ਜਾਂਦੀ।",
    "Free periods": "ਖੁੱਲ੍ਹੇ ਸਮੇਂ",
