    "Language": "ਭਾਸ਼ਾ",
    "Demora needs Screen Time authorization to set app limits and block apps. iOS will ask for your confirmation.": "Demora ਨੂੰ ਐਪ ਹੱਦਾਂ ਲਾਉਣ ਅਤੇ ਐਪਾਂ ਬਲੌਕ ਕਰਨ ਲਈ ਸਕ੍ਰੀਨ ਟਾਈਮ ਅਧਿਕਾਰ ਚਾਹੀਦਾ ਹੈ। iOS ਤੁਹਾਡੀ ਪੁਸ਼ਟੀ ਮੰਗੇਗਾ।",
    "Demora wouldn't exist without the people who tested it, broke it, and told me about it. Thank you. ❤️": "Demora ਉਨ੍ਹਾਂ ਲੋਕਾਂ ਬਿਨਾਂ ਨਹੀਂ ਹੋਣਾ ਸੀ ਜਿਨ੍ਹਾਂ ਨੇ ਇਸਨੂੰ ਪਰਖਿਆ, ਤੋੜਿਆ ਅਤੇ ਮੈਨੂੰ ਦੱਸਿਆ। ਧੰਨਵਾਦ। ❤️",
