    "Limits": "ਹੱਦਾਂ",
    "Limits won't block and usage won't count during this window.": "ਇਸ ਖਿੜਕੀ ਦੌਰਾਨ ਹੱਦਾਂ ਬਲੌਕ ਨਹੀਂ ਕਰਨਗੀਆਂ ਅਤੇ ਵਰਤੋਂ ਨਹੀਂ ਗਿਣੀ ਜਾਵੇਗੀ।",
    "Limits: daily time budgets per app. When the minutes run out, the app is blocked until midnight.": "ਹੱਦਾਂ: ਹਰ ਐਪ ਲਈ ਰੋਜ਼ਾਨਾ ਸਮੇਂ ਦੀ ਹੱਦ। ਮਿੰਟ ਮੁੱਕਣ ਤੇ ਐਪ ਅੱਧੀ ਰਾਤ ਤੱਕ ਬਲੌਕ ਹੋ ਜਾਂਦੀ ਹੈ।",
    "Looser changes": "ਢਿੱਲੀਆਂ ਤਬਦੀਲੀਆਂ",
    "Looser changes wait %@": "ਢਿੱਲੀਆਂ ਤਬਦੀਲੀਆਂ %@ ਉਡੀਕਦੀਆਂ ਹਨ",
    "Math problems": "ਗਣਿਤ ਦੇ ਸਵਾਲ",
