    "Mode": "ਢੰਗ",
    "Monthly schedules can't cross midnight — set the end time after the start time.": "ਮਹੀਨਾਵਾਰ ਸਮਾਂ-ਸਾਰਣੀਆਂ ਅੱਧੀ ਰਾਤ ਪਾਰ ਨਹੀਂ ਕਰ ਸਕਦੀਆਂ — ਅੰਤ ਦਾ ਸਮਾਂ ਸ਼ੁਰੂ ਤੋਂ ਬਾਅਦ ਰੱਖੋ।",
    "More strict": "ਵੱਧ ਸਖ਼ਤ",
    "More-strict delay": "ਵੱਧ ਸਖ਼ਤ ਦੇਰੀ",
    "Most screen-time apps protect your rules with a password — which you know, so you cave. Demora protects them with time instead.": "ਜ਼ਿਆਦਾਤਰ ਸਕ੍ਰੀਨ ਟਾਈਮ ਐਪਾਂ ਤੁਹਾਡੇ ਨਿਯਮਾਂ ਨੂੰ ਪਾਸਵਰਡ ਨਾਲ ਬਚਾਉਂਦੀਆਂ ਹਨ — ਜੋ ਤੁਹਾਨੂੰ ਪਤਾ ਹੁੰਦਾ ਹੈ, ਇਸ ਲਈ ਤੁਸੀਂ ਹਾਰ ਮੰਨ ਲੈਂਦੇ ਹੋ। Demora ਉਨ੍ਹਾਂ ਨੂੰ ਸਮੇਂ ਨਾਲ ਬਚਾਉਂਦਾ ਹੈ।",
    "Name": "ਨਾਮ",
