    "Nth weekday": "ਮਹੀਨੇ ਦਾ ਕੋਈ ਖ਼ਾਸ ਹਫ਼ਤੇ ਦਾ ਦਿਨ",
    "OK": "ਠੀਕ ਹੈ",
    "Off": "ਬੰਦ",
    "On": "ਚਾਲੂ",
    "One-off and unplanned, but still delay-gated. A block session waits %@; an unblock session waits %@. Ending early flips the rule (or use an override).": "ਇੱਕ ਵਾਰ ਦਾ ਅਤੇ ਬਿਨਾਂ ਯੋਜਨਾ ਦਾ, ਪਰ ਫਿਰ ਵੀ ਦੇਰੀ ਦੇ ਅਧੀਨ। ਬਲੌਕ ਸੈਸ਼ਨ %@ ਉਡੀਕਦਾ ਹੈ; ਅਨਬਲੌਕ ਸੈਸ਼ਨ %@ ਉਡੀਕਦਾ ਹੈ। ਜਲਦੀ ਖ਼ਤਮ ਕਰਨ ਨਾਲ ਨਿਯਮ ਪਲਟ ਜਾਂਦਾ ਹੈ (ਜਾਂ ਛੋਟ ਵਰਤੋ)।",
    "Only the apps picked here are blocked during the window.": "ਇਸ ਖਿੜਕੀ ਦੌਰਾਨ ਸਿਰਫ਼ ਇੱਥੇ ਚੁਣੀਆਂ ਐਪਾਂ ਬਲੌਕ ਹਨ।",
    "Overrides": "ਛੋਟਾਂ",
    "Overrides enabled": "ਛੋਟਾਂ ਚਾਲੂ",
    "Overrides let you skip a pending change's countdown. They're off by default. Adding one later counts as a less-strict change; removing one counts as stricter — both go through delays.": "ਛੋਟਾਂ ਤੁਹਾਨੂੰ ਉਡੀਕ ਵਿੱਚ ਪਈ ਤਬਦੀਲੀ ਦੀ ਕਾਊਂਟਡਾਊਨ ਛੱਡਣ ਦਿੰਦੀਆਂ ਹਨ। ਇਹ ਮੂਲ ਰੂਪ ਵਿੱਚ ਬੰਦ ਹਨ। ਬਾਅਦ ਵਿੱਚ ਇੱਕ ਜੋੜਨਾ ਘੱਟ ਸਖ਼ਤ ਤਬਦੀਲੀ ਗਿਣਿਆ ਜਾਂਦਾ ਹੈ; ਹਟਾਉਣਾ ਵੱਧ ਸਖ਼ਤ — ਦੋਵੇਂ ਦੇਰੀਆਂ ਵਿੱਚੋਂ ਲੰਘਦੇ ਹਨ।",
    "Overrides skip a pending change's countdown. Enabling or weakening one is a less-strict change; disabling or strengthening one is stricter. All edits here go through the matching delay.": "ਛੋਟਾਂ ਉਡੀਕ ਵਿੱਚ ਪਈ ਤਬਦੀਲੀ ਦੀ ਕਾਊਂਟਡਾਊਨ ਛੱਡਦੀਆਂ ਹਨ। ਕਿਸੇ ਨੂੰ ਚਾਲੂ ਜਾਂ ਕਮਜ਼ੋਰ ਕਰਨਾ ਘੱਟ ਸਖ਼ਤ ਤਬਦੀਲੀ ਹੈ; ਬੰਦ ਜਾਂ ਮਜ਼ਬੂਤ ਕਰਨਾ ਵੱਧ ਸਖ਼ਤ ਹੈ। ਇੱਥੇ ਹਰ ਤਬਦੀਲੀ ਸੰਬੰਧਿਤ ਦੇਰੀ ਵਿੱਚੋਂ ਲੰਘਦੀ ਹੈ।",
    "A change for this setting is already pending. Cancel it on the Home tab first if you want something different.": "ਇਸ ਸੈਟਿੰਗ ਲਈ ਇੱਕ ਤਬਦੀਲੀ ਪਹਿਲਾਂ ਹੀ ਉਡੀਕ ਵਿੱਚ ਹੈ। ਜੇ ਕੁਝ ਹੋਰ ਚਾਹੀਦਾ ਹੈ ਤਾਂ ਪਹਿਲਾਂ ਉਸਨੂੰ ਹੋਮ ਟੈਬ ਤੇ ਰੱਦ ਕਰੋ।",
