    "Cancels this request and lets you pick contacts again.": "ਇਹ ਬੇਨਤੀ ਰੱਦ ਕਰਦਾ ਹੈ ਅਤੇ ਤੁਹਾਨੂੰ ਸੰਪਰਕ ਦੁਬਾਰਾ ਚੁਣਨ ਦਿੰਦਾ ਹੈ।",
