    "an iPhone app that protects your screen-time rules with definition 1 instead of a password.": "ਇੱਕ iPhone ਐਪ ਜੋ ਤੁਹਾਡੇ ਸਕ੍ਰੀਨ ਟਾਈਮ ਨਿਯਮਾਂ ਨੂੰ ਪਾਸਵਰਡ ਦੀ ਥਾਂ ਪਰਿਭਾਸ਼ਾ 1 ਨਾਲ ਬਚਾਉਂਦੀ ਹੈ।",
