    "Pending changes show on the Home tab with a live countdown. You can cancel them anytime before they apply.": "ਉਡੀਕ ਵਿੱਚ ਪਈਆਂ ਤਬਦੀਲੀਆਂ ਹੋਮ ਟੈਬ ਤੇ ਚੱਲਦੀ ਕਾਊਂਟਡਾਊਨ ਨਾਲ ਦਿਸਦੀਆਂ ਹਨ। ਤੁਸੀਂ ਇਨ੍ਹਾਂ ਨੂੰ ਲਾਗੂ ਹੋਣ ਤੋਂ ਪਹਿਲਾਂ ਕਦੇ ਵੀ ਰੱਦ ਕਰ ਸਕਦੇ ਹੋ।",
