    "Remove…": "ਹਟਾਓ…",
    "Repeating windows: every day, chosen weekdays, or monthly patterns. Adding waits %@; removing waits %@.": "ਦੁਹਰਾਉਣ ਵਾਲੇ ਸਮੇਂ: ਹਰ ਦਿਨ, ਚੁਣੇ ਹਫ਼ਤੇ ਦੇ ਦਿਨ, ਜਾਂ ਮਹੀਨਾਵਾਰ ਢੰਗ। ਜੋੜਨਾ %@ ਉਡੀਕਦਾ ਹੈ; ਹਟਾਉਣਾ %@ ਉਡੀਕਦਾ ਹੈ।",
