    "Schedules: recurring or one-off windows that block chosen apps — or everything except a chosen few. Plus free periods where time doesn't count.": "ਸਮਾਂ-ਸਾਰਣੀਆਂ: ਦੁਹਰਾਉਣ ਵਾਲੇ ਜਾਂ ਇੱਕ ਵਾਰ ਦੇ ਸਮੇਂ ਜੋ ਚੁਣੀਆਂ ਐਪਾਂ ਨੂੰ — ਜਾਂ ਕੁਝ ਚੁਣੀਆਂ ਨੂੰ ਛੱਡ ਕੇ ਸਭ ਕੁਝ — ਬਲੌਕ ਕਰਦੇ ਹਨ। ਨਾਲ ਖੁੱਲ੍ਹੇ ਸਮੇਂ, ਜਿੱਥੇ ਸਮਾਂ ਨਹੀਂ ਗਿਣਿਆ ਜਾਂਦਾ।",
