    "Stricter changes wait %@": "ਸਖ਼ਤ ਤਬਦੀਲੀਆਂ %@ ਉਡੀਕਦੀਆਂ ਹਨ",
    "Temporarily lifts limits, schedules, and block sessions for the chosen apps.": "ਚੁਣੀਆਂ ਐਪਾਂ ਲਈ ਹੱਦਾਂ, ਸਮਾਂ-ਸਾਰਣੀਆਂ ਅਤੇ ਬਲੌਕ ਸੈਸ਼ਨ ਅਸਥਾਈ ਤੌਰ ਤੇ ਹਟਾਉਂਦਾ ਹੈ।",
    "Thanks for testing Demora!": "Demora ਪਰਖਣ ਲਈ ਧੰਨਵਾਦ!",
    "This app is blocked right now — by a limit, a schedule, or a session. Changing your rules takes a delay; open Demora to queue a change.": "ਇਹ ਐਪ ਹੁਣੇ ਬਲੌਕ ਹੈ — ਕਿਸੇ ਹੱਦ, ਸਮਾਂ-ਸਾਰਣੀ ਜਾਂ ਸੈਸ਼ਨ ਕਰਕੇ। ਨਿਯਮ ਬਦਲਣ ਲਈ ਦੇਰੀ ਲੱਗਦੀ ਹੈ; ਤਬਦੀਲੀ ਕਤਾਰ ਵਿੱਚ ਲਾਉਣ ਲਈ Demora ਖੋਲ੍ਹੋ।",
    "If it should already be unblocked, iOS is sometimes slow to apply a background change — open Demora for an immediate unblock.": "ਜੇ ਇਹ ਪਹਿਲਾਂ ਹੀ ਅਨਬਲੌਕ ਹੋਣੀ ਚਾਹੀਦੀ ਹੈ, ਤਾਂ iOS ਕਈ ਵਾਰ ਬੈਕਗ੍ਰਾਊਂਡ ਤਬਦੀਲੀ ਲਾਗੂ ਕਰਨ ਵਿੱਚ ਹੌਲੀ ਹੁੰਦਾ ਹੈ — ਤੁਰੰਤ ਅਨਬਲੌਕ ਲਈ Demora ਖੋਲ੍ਹੋ।",
    "Two delays rule everything": "ਦੋ ਦੇਰੀਆਂ ਸਭ ਕੁਝ ਚਲਾਉਂਦੀਆਂ ਹਨ",
    "Type": "ਕਿਸਮ",
    "Unblock": "ਅਨਬਲੌਕ ਕਰੋ",
    "Unblock apps": "ਐਪਾਂ ਅਨਬਲੌਕ ਕਰੋ",
    "Wait this long before any change that loosens your rules takes effect. Usually set longer than the first.": "ਤੁਹਾਡੇ ਨਿਯਮ ਢਿੱਲੇ ਕਰਨ ਵਾਲੀ ਕਿਸੇ ਵੀ ਤਬਦੀਲੀ ਦੇ ਲਾਗੂ ਹੋਣ ਤੋਂ ਪਹਿਲਾਂ ਇੰਨੀ ਦੇਰ ਉਡੀਕ ਕਰੋ। ਆਮ ਤੌਰ ਤੇ ਪਹਿਲੀ ਤੋਂ ਲੰਮੀ ਰੱਖੀ ਜਾਂਦੀ ਹੈ।",
    "Wait this long before any change that tightens your rules takes effect.": "ਤੁਹਾਡੇ ਨਿਯਮ ਕੱਸਣ ਵਾਲੀ ਕਿਸੇ ਵੀ ਤਬਦੀਲੀ ਦੇ ਲਾਗੂ ਹੋਣ ਤੋਂ ਪਹਿਲਾਂ ਇੰਨੀ ਦੇਰ ਉਡੀਕ ਕਰੋ।",
    "Want your name in the app's beta-tester thanks page? Pick whatever you'd like to be called.": "ਐਪ ਦੇ ਬੀਟਾ-ਟੈਸਟਰ ਧੰਨਵਾਦ ਪੰਨੇ ਤੇ ਆਪਣਾ ਨਾਮ ਚਾਹੁੰਦੇ ਹੋ? ਜਿਸ ਨਾਮ ਨਾਲ ਬੁਲਾਇਆ ਜਾਣਾ ਚਾਹੋ, ਉਹ ਚੁਣੋ।",
    "Weekday": "ਹਫ਼ਤੇ ਦਾ ਦਿਨ",
    "Weekdays": "ਹਫ਼ਤੇ ਦੇ ਦਿਨ",
    "What can it do?": "ਇਹ ਕੀ ਕਰ ਸਕਦਾ ਹੈ?",
    "What's in the box": "ਇਸ ਵਿੱਚ ਕੀ ਹੈ",
    "When": "ਕਦੋਂ",
    "When on, deleting ANY app from this iPhone is blocked — including Demora itself, so blocks can't be bypassed by uninstalling.": "ਚਾਲੂ ਹੋਣ ਤੇ, ਇਸ iPhone ਤੋਂ ਕੋਈ ਵੀ ਐਪ ਮਿਟਾਉਣਾ ਬਲੌਕ ਹੁੰਦਾ ਹੈ — Demora ਆਪ ਸਮੇਤ, ਤਾਂ ਜੋ ਬਲੌਕ ਅਣਇੰਸਟਾਲ ਕਰਕੇ ਟੱਪੇ ਨਾ ਜਾ ਸਕਣ।",
    "Which one": "ਕਿਹੜਾ",
    "Window": "ਖਿੜਕੀ",
    "Wrong — new problem": "ਗ਼ਲਤ — ਨਵਾਂ ਸਵਾਲ",
    "You're in! Your name will appear in the beta testers page once it's approved.": "ਤੁਸੀਂ ਅੰਦਰ ਹੋ! ਮਨਜ਼ੂਰੀ ਮਿਲਣ ਤੇ ਤੁਹਾਡਾ ਨਾਮ ਬੀਟਾ ਟੈਸਟਰਾਂ ਦੇ ਪੰਨੇ ਤੇ ਦਿਸੇਗਾ।",
    "You're set": "ਤੁਸੀਂ ਤਿਆਰ ਹੋ",
    "Your name is in — it'll show up once approved.": "ਤੁਹਾਡਾ ਨਾਮ ਆ ਗਿਆ — ਮਨਜ਼ੂਰੀ ਮਿਲਣ ਤੇ ਦਿਸੇਗਾ।",
    "Your name or nickname": "ਤੁਹਾਡਾ ਨਾਮ ਜਾਂ ਉਪਨਾਮ",
    "e.g. Airport, weekend trip": "ਜਿਵੇਂ ਹਵਾਈ ਅੱਡਾ, ਵੀਕਐਂਡ ਸਫ਼ਰ",
    "e.g. Bedtime": "ਜਿਵੇਂ ਸੌਣ ਦਾ ਵੇਲਾ",
    "e.g. Deep work": "ਜਿਵੇਂ ਡੂੰਘਾ ਕੰਮ",
    "e.g. Instagram": "ਜਿਵੇਂ Instagram",
    "e.g. Lunch break": "ਜਿਵੇਂ ਦੁਪਹਿਰ ਦੀ ਛੁੱਟੀ",
    "free period": "ਖੁੱਲ੍ਹਾ ਸਮਾਂ",
    "limit": "ਹੱਦ",
    "now": "ਹੁਣ",
    "planned window": "ਯੋਜਨਾਬੱਧ ਸਮਾਂ",
    "schedule": "ਸਮਾਂ-ਸਾਰਣੀ",
    "session": "ਸੈਸ਼ਨ",
    // Prevent disabling, walkthrough replay — added after the
    // 2026-07 update (App Attest, ContactCrypto, LatchReport extension).
    "A passcode is saved. Open the guide below to view it.": "ਇੱਕ ਪਾਸਕੋਡ ਸੰਭਾਲਿਆ ਹੋਇਆ ਹੈ। ਇਸਨੂੰ ਦੇਖਣ ਲਈ ਹੇਠਾਂ ਗਾਈਡ ਖੋਲ੍ਹੋ।",
    "Can't reach this contact right now — they may have removed Demora or signed out. They won't be able to approve until they're back.": "ਇਸ ਸੰਪਰਕ ਤੱਕ ਹੁਣ ਨਹੀਂ ਪਹੁੰਚਿਆ ਜਾ ਸਕਦਾ — ਹੋ ਸਕਦਾ ਹੈ ਉਨ੍ਹਾਂ ਨੇ Demora ਹਟਾ ਦਿੱਤਾ ਹੋਵੇ ਜਾਂ ਸਾਈਨ ਆਊਟ ਹੋ ਗਏ ਹੋਣ। ਉਨ੍ਹਾਂ ਦੇ ਵਾਪਸ ਆਉਣ ਤੱਕ ਉਹ ਮਨਜ਼ੂਰ ਨਹੀਂ ਕਰ ਸਕਣਗੇ।",
    "Couldn't start the walkthrough": "ਵਾਕਥਰੂ ਸ਼ੁਰੂ ਨਹੀਂ ਹੋ ਸਕਿਆ",
    "Bug tracker": "ਗੜਬੜ ਟ੍ਰੈਕਰ",
    "Demora can't stop you from turning off its Screen Time access in iOS Settings — but a friend can. If Screen Time itself is locked with someone else's passcode, iOS blocks any change to Demora's access, while Demora keeps doing all the blocking.": "Demora ਤੁਹਾਨੂੰ iOS ਸੈਟਿੰਗਾਂ ਵਿੱਚ ਆਪਣੀ ਸਕ੍ਰੀਨ ਟਾਈਮ ਪਹੁੰਚ ਬੰਦ ਕਰਨ ਤੋਂ ਨਹੀਂ ਰੋਕ ਸਕਦਾ — ਪਰ ਇੱਕ ਦੋਸਤ ਰੋਕ ਸਕਦਾ ਹੈ। ਜੇ ਸਕ੍ਰੀਨ ਟਾਈਮ ਆਪ ਕਿਸੇ ਹੋਰ ਦੇ ਪਾਸਕੋਡ ਨਾਲ ਤਾਲਾਬੰਦ ਹੋਵੇ, ਤਾਂ iOS Demora ਦੀ ਪਹੁੰਚ ਵਿੱਚ ਕੋਈ ਵੀ ਤਬਦੀਲੀ ਰੋਕ ਦਿੰਦਾ ਹੈ, ਜਦਕਿ Demora ਸਾਰੀ ਬਲੌਕਿੰਗ ਕਰਦਾ ਰਹਿੰਦਾ ਹੈ।",
    "Demora couldn't safely back up your current setup, so the replay was cancelled to protect your limits. Nothing was changed. Please try again in a moment.": "Demora ਤੁਹਾਡਾ ਮੌਜੂਦਾ ਸੈੱਟਅੱਪ ਸੁਰੱਖਿਅਤ ਢੰਗ ਨਾਲ ਬੈਕਅੱਪ ਨਹੀਂ ਕਰ ਸਕਿਆ, ਇਸ ਲਈ ਤੁਹਾਡੀਆਂ ਹੱਦਾਂ ਦੀ ਰੱਖਿਆ ਲਈ ਦੁਹਰਾਓ ਰੱਦ ਕਰ ਦਿੱਤਾ ਗਿਆ। ਕੁਝ ਵੀ ਨਹੀਂ ਬਦਲਿਆ। ਕਿਰਪਾ ਕਰਕੇ ਥੋੜ੍ਹੀ ਦੇਰ ਬਾਅਦ ਦੁਬਾਰਾ ਕੋਸ਼ਿਸ਼ ਕਰੋ।",
    "Done. Now you can't disable Demora's access — or change the passcode — without your friend. To undo it later, your friend enters the passcode and turns it off.": "ਹੋ ਗਿਆ। ਹੁਣ ਤੁਸੀਂ ਆਪਣੇ ਦੋਸਤ ਤੋਂ ਬਿਨਾਂ Demora ਦੀ ਪਹੁੰਚ ਬੰਦ ਜਾਂ ਪਾਸਕੋਡ ਨਹੀਂ ਬਦਲ ਸਕਦੇ। ਇਸਨੂੰ ਬਾਅਦ ਵਿੱਚ ਪਲਟਣ ਲਈ, ਤੁਹਾਡਾ ਦੋਸਤ ਪਾਸਕੋਡ ਭਰ ਕੇ ਇਸਨੂੰ ਬੰਦ ਕਰਦਾ ਹੈ।",
    "Email limit": "ਈਮੇਲ ਹੱਦ",
    "Emoji": "ਇਮੋਜੀ",
    "Friend: save the passcode here so it isn't lost. It's only shown from this page, which is behind your delay.": "ਦੋਸਤ: ਪਾਸਕੋਡ ਇੱਥੇ ਸੰਭਾਲੋ ਤਾਂ ਜੋ ਗੁਆਚ ਨਾ ਜਾਵੇ। ਇਹ ਸਿਰਫ਼ ਇਸ ਪੰਨੇ ਤੋਂ ਦਿਖਾਇਆ ਜਾਂਦਾ ਹੈ, ਜੋ ਤੁਹਾਡੀ ਦੇਰੀ ਦੇ ਪਿੱਛੇ ਹੈ।",
    "Hand your phone to your friend. Have THEM enter a 4-digit passcode you don't see — don't watch.": "ਆਪਣਾ ਫ਼ੋਨ ਆਪਣੇ ਦੋਸਤ ਨੂੰ ਫੜਾਓ। ਉਨ੍ਹਾਂ ਨੂੰ 4-ਅੰਕਾਂ ਦਾ ਪਾਸਕੋਡ ਭਰਨ ਦਿਓ ਜੋ ਤੁਸੀਂ ਨਾ ਦੇਖੋ — ਨਾ ਦੇਖਣਾ।",
    "Heads up: on your iOS version, a limit only counts screen time from the moment you add it — time you already spent earlier today isn't included. Update to iOS 17.4 or later for exact daily counting.": "ਧਿਆਨ ਦਿਓ: ਤੁਹਾਡੇ iOS ਸੰਸਕਰਣ ਤੇ, ਹੱਦ ਸਿਰਫ਼ ਉਸ ਪਲ ਤੋਂ ਸਕ੍ਰੀਨ ਟਾਈਮ ਗਿਣਦੀ ਹੈ ਜਦੋਂ ਤੁਸੀਂ ਇਸਨੂੰ ਜੋੜਦੇ ਹੋ — ਅੱਜ ਪਹਿਲਾਂ ਲੱਗਿਆ ਸਮਾਂ ਸ਼ਾਮਲ ਨਹੀਂ। ਸਟੀਕ ਰੋਜ਼ਾਨਾ ਗਿਣਤੀ ਲਈ iOS 17.4 ਜਾਂ ਨਵਾਂ ਅੱਪਡੇਟ ਕਰੋ।",
    "Onboarding demo — you can skip below. It's always available again in Settings → Help.": "ਆਨਬੋਰਡਿੰਗ ਡੈਮੋ — ਤੁਸੀਂ ਹੇਠਾਂ ਛੱਡ ਸਕਦੇ ਹੋ। ਇਹ ਹਮੇਸ਼ਾ ਸੈਟਿੰਗਾਂ → ਮਦਦ ਵਿੱਚ ਦੁਬਾਰਾ ਮਿਲਦਾ ਹੈ।",
    "One more safeguard": "ਇੱਕ ਹੋਰ ਸੁਰੱਖਿਆ",
    "Open Settings → Screen Time on this iPhone. If it's off, turn it on.": "ਇਸ iPhone ਤੇ ਸੈਟਿੰਗਾਂ → ਸਕ੍ਰੀਨ ਟਾਈਮ ਖੋਲ੍ਹੋ। ਜੇ ਇਹ ਬੰਦ ਹੈ, ਤਾਂ ਚਾਲੂ ਕਰੋ।",
    "Open the guide": "ਗਾਈਡ ਖੋਲ੍ਹੋ",
    "Passcode": "ਪਾਸਕੋਡ",
    "Pick someone you trust and can reach. If the passcode and its recovery Apple ID are both lost, removing it may require erasing the device.": "ਕਿਸੇ ਭਰੋਸੇਯੋਗ ਅਤੇ ਪਹੁੰਚ ਵਿੱਚ ਰਹਿਣ ਵਾਲੇ ਨੂੰ ਚੁਣੋ। ਜੇ ਪਾਸਕੋਡ ਅਤੇ ਉਸਦੀ ਰਿਕਵਰੀ Apple ID ਦੋਵੇਂ ਗੁਆਚ ਜਾਣ, ਤਾਂ ਇਸਨੂੰ ਹਟਾਉਣ ਲਈ ਡਿਵਾਈਸ ਮਿਟਾਉਣੀ ਪੈ ਸਕਦੀ ਹੈ।",
    "Prevent disabling": "ਬੰਦ ਕਰਨ ਤੋਂ ਰੋਕੋ",
    "Protection": "ਸੁਰੱਖਿਆ",
    "Replay walkthrough": "ਵਾਕਥਰੂ ਦੁਹਰਾਓ",
    "Request access": "ਪਹੁੰਚ ਮੰਗੋ",
    "Save": "ਸੰਭਾਲੋ",
    "Saved passcode: %@": "ਸੰਭਾਲਿਆ ਪਾਸਕੋਡ: %@",
    "Unlock viewing the stored passcode": "ਸੰਭਾਲਿਆ ਪਾਸਕੋਡ ਦੇਖਣਾ ਖੋਲ੍ਹੋ",
    "Screen Time passcode": "ਸਕ੍ਰੀਨ ਟਾਈਮ ਪਾਸਕੋਡ",
    "Enter passcode": "ਪਾਸਕੋਡ ਭਰੋ",
    "View passcode": "ਪਾਸਕੋਡ ਦੇਖੋ",
    "Change the passcode?": "ਪਾਸਕੋਡ ਬਦਲਣਾ ਹੈ?",
    "Are you sure? There is no way to undo this — the saved passcode is replaced only when you save a new one.": "ਕੀ ਤੁਹਾਨੂੰ ਯਕੀਨ ਹੈ? ਇਸਨੂੰ ਪਲਟਣ ਦਾ ਕੋਈ ਤਰੀਕਾ ਨਹੀਂ — ਸੰਭਾਲਿਆ ਪਾਸਕੋਡ ਸਿਰਫ਼ ਉਦੋਂ ਬਦਲਦਾ ਹੈ ਜਦੋਂ ਤੁਸੀਂ ਨਵਾਂ ਸੰਭਾਲਦੇ ਹੋ।",
    "The friend who set the Screen Time passcode can store it here so it isn't lost. Going back without saving keeps the current one.": "ਸਕ੍ਰੀਨ ਟਾਈਮ ਪਾਸਕੋਡ ਲਾਉਣ ਵਾਲਾ ਦੋਸਤ ਇਸਨੂੰ ਇੱਥੇ ਸੰਭਾਲ ਸਕਦਾ ਹੈ ਤਾਂ ਜੋ ਇਹ ਗੁਆਚੇ ਨਾ। ਬਿਨਾਂ ਸੰਭਾਲੇ ਪਿੱਛੇ ਜਾਣ ਨਾਲ ਮੌਜੂਦਾ ਪਾਸਕੋਡ ਰਹਿੰਦਾ ਹੈ।",
    "Viewing the stored passcode is behind your less-strict delay: request it, wait out the delay, and you get one look. After that it locks again.": "ਸੰਭਾਲਿਆ ਪਾਸਕੋਡ ਦੇਖਣਾ ਤੁਹਾਡੀ ਘੱਟ ਸਖ਼ਤ ਦੇਰੀ ਦੇ ਪਿੱਛੇ ਹੈ: ਇਹ ਮੰਗੋ, ਦੇਰੀ ਪੂਰੀ ਕਰੋ, ਅਤੇ ਤੁਹਾਨੂੰ ਇੱਕ ਝਲਕ ਮਿਲਦੀ ਹੈ। ਉਸ ਤੋਂ ਬਾਅਦ ਇਹ ਫਿਰ ਤਾਲਾਬੰਦ ਹੋ ਜਾਂਦਾ ਹੈ।",
    "Access is spent — viewing it again needs a new request.": "ਪਹੁੰਚ ਵਰਤੀ ਜਾ ਚੁੱਕੀ — ਇਸਨੂੰ ਫਿਰ ਦੇਖਣ ਲਈ ਨਵੀਂ ਬੇਨਤੀ ਚਾਹੀਦੀ ਹੈ।",
    "Screen Time usually only allows a 4-digit passcode — are you sure this is correct?": "ਸਕ੍ਰੀਨ ਟਾਈਮ ਆਮ ਤੌਰ ਤੇ ਸਿਰਫ਼ 4-ਅੰਕਾਂ ਦਾ ਪਾਸਕੋਡ ਮੰਨਦਾ ਹੈ — ਕੀ ਤੁਹਾਨੂੰ ਯਕੀਨ ਹੈ ਕਿ ਇਹ ਠੀਕ ਹੈ?",
    "Saved ✓": "ਸੰਭਾਲਿਆ ✓",
    "Show me how": "ਮੈਨੂੰ ਦਿਖਾਓ ਕਿਵੇਂ",
    "Skip and set up manually": "ਛੱਡੋ ਅਤੇ ਆਪ ਸੈੱਟ ਕਰੋ",
    "Skip walkthrough": "ਵਾਕਥਰੂ ਛੱਡੋ",
    "Skip — set up manually": "ਛੱਡੋ — ਆਪ ਸੈੱਟ ਕਰੋ",
    "Store the Screen Time passcode": "ਸਕ੍ਰੀਨ ਟਾਈਮ ਪਾਸਕੋਡ ਸੰਭਾਲੋ",
    "Take photo": "ਫ਼ੋਟੋ ਖਿੱਚੋ",
    "Takes about 2 minutes, and you need a second person physically with you.": "ਲਗਭਗ 2 ਮਿੰਟ ਲੱਗਦੇ ਹਨ, ਅਤੇ ਤੁਹਾਡੇ ਨਾਲ ਦੂਜਾ ਵਿਅਕਤੀ ਸਰੀਰਕ ਤੌਰ ਤੇ ਹੋਣਾ ਚਾਹੀਦਾ ਹੈ।",
    "Tap “Lock Screen Time Settings” (or “Use Screen Time Passcode”).": "“ਸਕ੍ਰੀਨ ਟਾਈਮ ਸੈਟਿੰਗਾਂ ਨੂੰ ਲਾਕ ਕਰੋ” (ਜਾਂ “ਸਕ੍ਰੀਨ ਟਾਈਮ ਪਾਸਕੋਡ ਵਰਤੋ”) ਛੂਹੋ।",
    "Thank you. ❤️": "ਧੰਨਵਾਦ। ❤️",
    "That's okay. Without Screen Time access Demora can't block apps, but you can continue and turn it on later.": "ਕੋਈ ਗੱਲ ਨਹੀਂ। ਸਕ੍ਰੀਨ ਟਾਈਮ ਦੀ ਪਹੁੰਚ ਬਿਨਾਂ Demora ਐਪਾਂ ਬਲੌਕ ਨਹੀਂ ਕਰ ਸਕਦਾ, ਪਰ ਤੁਸੀਂ ਅੱਗੇ ਵਧ ਕੇ ਇਸਨੂੰ ਬਾਅਦ ਵਿੱਚ ਚਾਲੂ ਕਰ ਸਕਦੇ ਹੋ।",
    "That's the whole loop. Your real limits, schedules, and settings are still here — nothing changed.": "ਇਹੀ ਪੂਰਾ ਚੱਕਰ ਹੈ। ਤੁਹਾਡੀਆਂ ਅਸਲੀ ਹੱਦਾਂ, ਸਮਾਂ-ਸਾਰਣੀਆਂ ਅਤੇ ਸੈਟਿੰਗਾਂ ਅਜੇ ਇੱਥੇ ਹੀ ਹਨ — ਕੁਝ ਨਹੀਂ ਬਦਲਿਆ।",
    "There's a way to make Demora impossible to turn off — with a friend's help. It takes about 2 minutes and needs a second person physically with you.": "Demora ਨੂੰ ਬੰਦ ਕਰਨਾ ਨਾਮੁਮਕਿਨ ਬਣਾਉਣ ਦਾ ਇੱਕ ਤਰੀਕਾ ਹੈ — ਕਿਸੇ ਦੋਸਤ ਦੀ ਮਦਦ ਨਾਲ। ਇਸ ਵਿੱਚ ਲਗਭਗ 2 ਮਿੰਟ ਲੱਗਦੇ ਹਨ ਅਤੇ ਤੁਹਾਡੇ ਨਾਲ ਦੂਜਾ ਵਿਅਕਤੀ ਸਰੀਰਕ ਤੌਰ ਤੇ ਹੋਣਾ ਚਾਹੀਦਾ ਹੈ।",
    "They call themselves “%@”.": "ਉਹ ਆਪਣੇ ਆਪ ਨੂੰ “%@” ਕਹਿੰਦੇ ਹਨ।",
    "This guide is behind your less-strict delay: request it, wait out the delay, and you get one open. After you view it, it locks again.": "ਇਹ ਗਾਈਡ ਤੁਹਾਡੀ ਘੱਟ ਸਖ਼ਤ ਦੇਰੀ ਦੇ ਪਿੱਛੇ ਹੈ: ਇਹ ਮੰਗੋ, ਦੇਰੀ ਪੂਰੀ ਕਰੋ, ਅਤੇ ਤੁਹਾਨੂੰ ਇੱਕ ਵਾਰ ਖੁੱਲ੍ਹੇਗੀ। ਦੇਖਣ ਤੋਂ ਬਾਅਦ ਇਹ ਫਿਰ ਤਾਲਾਬੰਦ ਹੋ ਜਾਂਦੀ ਹੈ।",
    "Unavailable": "ਉਪਲਬਧ ਨਹੀਂ",
    "Unlock the “Prevent disabling” guide": "“ਬੰਦ ਕਰਨ ਤੋਂ ਰੋਕੋ” ਗਾਈਡ ਖੋਲ੍ਹੋ",
    "Use photo": "ਫ਼ੋਟੋ ਵਰਤੋ",
    "When asked for Screen Time Passcode Recovery, your friend signs in with THEIR OWN Apple ID — not yours. That's what stops you from resetting the passcode on your own.": "ਜਦੋਂ ਸਕ੍ਰੀਨ ਟਾਈਮ ਪਾਸਕੋਡ ਰਿਕਵਰੀ ਮੰਗੀ ਜਾਵੇ, ਤੁਹਾਡਾ ਦੋਸਤ ਆਪਣੀ ਹੀ Apple ID ਨਾਲ ਸਾਈਨ ਇਨ ਕਰਦਾ ਹੈ — ਤੁਹਾਡੀ ਨਾਲ ਨਹੀਂ। ਇਹੀ ਤੁਹਾਨੂੰ ਆਪਣੇ ਆਪ ਪਾਸਕੋਡ ਰੀਸੈੱਟ ਕਰਨ ਤੋਂ ਰੋਕਦਾ ਹੈ।",
    "You can always find this later under Help — but there it's behind a delay.": "ਤੁਸੀਂ ਇਹ ਬਾਅਦ ਵਿੱਚ ਹਮੇਸ਼ਾ ਮਦਦ ਹੇਠ ਲੱਭ ਸਕਦੇ ਹੋ — ਪਰ ਉੱਥੇ ਇਹ ਦੇਰੀ ਦੇ ਪਿੱਛੇ ਹੈ।",
    "You can change these any time under General blocking. Each change then goes through your delays.": "ਤੁਸੀਂ ਇਹ ਕਦੇ ਵੀ ਆਮ ਬਲੌਕਿੰਗ ਹੇਠ ਬਦਲ ਸਕਦੇ ਹੋ। ਹਰ ਤਬਦੀਲੀ ਫਿਰ ਤੁਹਾਡੀਆਂ ਦੇਰੀਆਂ ਵਿੱਚੋਂ ਲੰਘਦੀ ਹੈ।",
    "Your one-time access is ready.": "ਤੁਹਾਡੀ ਇੱਕ-ਵਾਰ ਦੀ ਪਹੁੰਚ ਤਿਆਰ ਹੈ।",
    "your setup stays safe": "ਤੁਹਾਡਾ ਸੈੱਟਅੱਪ ਸੁਰੱਖਿਅਤ ਰਹਿੰਦਾ ਹੈ",
    "—": "—",
    "A backup, if you want one.": "ਬੈਕਅੱਪ, ਜੇ ਤੁਸੀਂ ਚਾਹੋ।",
    "Optional: add a trusted contact, a phrase, or a password. Choose exactly what each can approve or unlock.": "ਵਿਕਲਪਿਕ: ਭਰੋਸੇਯੋਗ ਸੰਪਰਕ, ਵਾਕ ਜਾਂ ਪਾਸਵਰਡ ਜੋੜੋ। ਠੀਕ ਚੁਣੋ ਕਿ ਹਰ ਇੱਕ ਕੀ ਮਨਜ਼ੂਰ ਜਾਂ ਖੋਲ੍ਹ ਸਕਦਾ ਹੈ।",
    "These choices apply when you finish setup. Later additions and permission changes follow your delays.": "ਇਹ ਚੋਣਾਂ ਸੈੱਟਅੱਪ ਪੂਰਾ ਹੋਣ ਤੇ ਲਾਗੂ ਹੁੰਦੀਆਂ ਹਨ। ਬਾਅਦ ਦੇ ਵਾਧੇ ਅਤੇ ਇਜਾਜ਼ਤਾਂ ਦੀਆਂ ਤਬਦੀਲੀਆਂ ਤੁਹਾਡੀਆਂ ਦੇਰੀਆਂ ਮੁਤਾਬਕ ਚੱਲਦੀਆਂ ਹਨ।",
    "Background monitoring limit": "ਬੈਕਗ੍ਰਾਊਂਡ ਨਿਗਰਾਨੀ ਦੀ ਹੱਦ",
    "This change needs %d background monitors, but iOS allows %d. Remove a schedule, split budget or pending change, then try again.": "ਇਸ ਤਬਦੀਲੀ ਨੂੰ %d ਬੈਕਗ੍ਰਾਊਂਡ ਨਿਗਰਾਨ ਚਾਹੀਦੇ ਹਨ, ਪਰ iOS %d ਦੀ ਇਜਾਜ਼ਤ ਦਿੰਦਾ ਹੈ। ਕੋਈ ਸਮਾਂ-ਸਾਰਣੀ, ਵੰਡਿਆ ਸਮਾਂ ਜਾਂ ਉਡੀਕ ਵਿੱਚ ਪਈ ਤਬਦੀਲੀ ਹਟਾਓ, ਫਿਰ ਦੁਬਾਰਾ ਕੋਸ਼ਿਸ਼ ਕਰੋ।",
