    "Access requested. It opens after your looser wait. Track it in Changes on Today, where a way to skip a wait can also open it early.": "ਪਹੁੰਚ ਮੰਗੀ ਗਈ ਹੈ। ਇਹ ਤੁਹਾਡੀ ਢਿੱਲੀ ਉਡੀਕ ਤੋਂ ਬਾਅਦ ਖੁੱਲ੍ਹਦੀ ਹੈ। ਇਸਨੂੰ ਅੱਜ ਦੀਆਂ ਤਬਦੀਲੀਆਂ ਵਿੱਚ ਦੇਖੋ, ਜਿੱਥੇ ਉਡੀਕ ਛੱਡਣ ਦਾ ਤਰੀਕਾ ਇਸਨੂੰ ਜਲਦੀ ਵੀ ਖੋਲ੍ਹ ਸਕਦਾ ਹੈ।",
    "Saved": "ਸੰਭਾਲਿਆ",
    "None saved": "ਕੋਈ ਸੰਭਾਲਿਆ ਨਹੀਂ",
    "Contact & feedback": "ਸੰਪਰਕ ਤੇ ਸੁਝਾਅ",
    "Open You": "ਤੁਸੀਂ ਖੋਲ੍ਹੋ",
    // Skip the wait (docs/you-redesign.md §5.13)
    "%d words, typed one by one": "%d ਸ਼ਬਦ, ਇੱਕ-ਇੱਕ ਕਰਕੇ ਲਿਖੇ ਜਾਂਦੇ ਹਨ",
    "+%d min": "+%d ਮਿੰਟ",
    "Any one approval is enough.": "ਕੋਈ ਇੱਕ ਮਨਜ਼ੂਰੀ ਕਾਫ਼ੀ ਹੈ।",
    "Ask again": "ਦੁਬਾਰਾ ਪੁੱਛੋ",
    "Can't reach right now": "ਹੁਣ ਪਹੁੰਚ ਨਹੀਂ ਹੋ ਰਹੀ",
    "Email approvals aren't available in this version": "ਈਮੇਲ ਮਨਜ਼ੂਰੀਆਂ ਇਸ ਸੰਸਕਰਣ ਵਿੱਚ ਉਪਲਬਧ ਨਹੀਂ",
    "Enter the code %@ received. It expires in 15 minutes.": "%@ ਨੂੰ ਮਿਲਿਆ ਕੋਡ ਭਰੋ। ਇਹ 15 ਮਿੰਟ ਵਿੱਚ ਮਿਆਦ ਪੁੱਗ ਜਾਂਦਾ ਹੈ।",
    "Lands %@ · in": "%@ ਨੂੰ ਲੱਗੇਗੀ · ਇੰਨੇ ਵਿੱਚ",
    "None of your ways can skip this change.": "ਤੁਹਾਡੇ ਕਿਸੇ ਵੀ ਤਰੀਕੇ ਨਾਲ ਇਹ ਤਬਦੀਲੀ ਛੱਡੀ ਨਹੀਂ ਜਾ ਸਕਦੀ।",
    "Only ways allowed to skip this change are listed.": "ਸਿਰਫ਼ ਉਹ ਤਰੀਕੇ ਦਿਖਾਏ ਗਏ ਹਨ ਜਿਨ੍ਹਾਂ ਨੂੰ ਇਹ ਤਬਦੀਲੀ ਛੱਡਣ ਦੀ ਇਜਾਜ਼ਤ ਹੈ।",
    "Phrase": "ਵਾਕ",
    "Sent · waiting": "ਭੇਜਿਆ · ਉਡੀਕ ਵਿੱਚ",
    "That password doesn't match, or this change is no longer waiting.": "ਉਹ ਪਾਸਵਰਡ ਮੇਲ ਨਹੀਂ ਖਾਂਦਾ, ਜਾਂ ਇਹ ਤਬਦੀਲੀ ਹੁਣ ਉਡੀਕ ਵਿੱਚ ਨਹੀਂ।",
    "Type the password": "ਪਾਸਵਰਡ ਲਿਖੋ",
    "Who or what can skip it": "ਕੌਣ ਜਾਂ ਕੀ ਇਸਨੂੰ ਛੱਡ ਸਕਦਾ ਹੈ",
    "Why you're asking — they'll see it": "ਤੁਸੀਂ ਕਿਉਂ ਪੁੱਛ ਰਹੇ ਹੋ — ਉਹ ਇਹ ਦੇਖਣਗੇ",
    "asks in their Demora app": "ਆਪਣੀ Demora ਐਪ ਵਿੱਚ ਪੁੱਛਦਾ ਹੈ",
    "gets an email code": "ਈਮੇਲ ਕੋਡ ਮਿਲਦਾ ਹੈ",
    // Ways to skip a wait: add, edit, remove (docs/you-redesign.md §5.9–5.10)
    "%@ gets the request now and can approve once they accept and the wait ends.": "%@ ਨੂੰ ਹੁਣ ਬੇਨਤੀ ਮਿਲਦੀ ਹੈ ਅਤੇ ਉਹ ਸਵੀਕਾਰ ਕਰਨ ਅਤੇ ਉਡੀਕ ਮੁੱਕਣ ਤੋਂ ਬਾਅਦ ਮਨਜ਼ੂਰ ਕਰ ਸਕਦੇ ਹਨ।",
    "%d random words": "%d ਬੇਤਰਤੀਬ ਸ਼ਬਦ",
    "A change is already waiting": "ਇੱਕ ਤਬਦੀਲੀ ਪਹਿਲਾਂ ਹੀ ਉਡੀਕ ਵਿੱਚ ਹੈ",
    "Adding, removing or pausing trusted contacts": "ਭਰੋਸੇਯੋਗ ਸੰਪਰਕ ਜੋੜਨਾ, ਹਟਾਉਣਾ ਜਾਂ ਰੋਕਣਾ",
    "Also needs a limit whose extra time asks for this.": "ਇੱਕ ਅਜਿਹੀ ਹੱਦ ਵੀ ਚਾਹੀਦੀ ਹੈ ਜਿਸਦਾ ਵੱਧ ਸਮਾਂ ਇਹ ਮੰਗਦਾ ਹੋਵੇ।",
    "Also turns on contact approvals": "ਸੰਪਰਕ ਮਨਜ਼ੂਰੀਆਂ ਵੀ ਚਾਲੂ ਕਰਦਾ ਹੈ",
    "App deletion lock, websites and Prevent disabling access": "ਐਪ ਮਿਟਾਉਣ ਦਾ ਤਾਲਾ, ਵੈੱਬਸਾਈਟਾਂ ਅਤੇ ਬੰਦ ਕਰਨ ਤੋਂ ਰੋਕਣ ਦੀ ਪਹੁੰਚ",
    "Ask them for the code under You → Your code. Yours is %@.": "ਉਨ੍ਹਾਂ ਤੋਂ ਤੁਸੀਂ → ਤੁਹਾਡਾ ਕੋਡ ਵਿੱਚ ਦਿਸਦਾ ਕੋਡ ਮੰਗੋ। ਤੁਹਾਡਾ ਕੋਡ %@ ਹੈ।",
    "Best if someone else keeps it, or it's written down somewhere out of reach.": "ਸਭ ਤੋਂ ਵਧੀਆ ਹੈ ਜੇ ਕੋਈ ਹੋਰ ਇਸਨੂੰ ਰੱਖੇ, ਜਾਂ ਇਹ ਕਿਤੇ ਪਹੁੰਚ ਤੋਂ ਦੂਰ ਲਿਖਿਆ ਹੋਵੇ।",
    "Change now": "ਹੁਣੇ ਬਦਲੋ",
    "Change the password": "ਪਾਸਵਰਡ ਬਦਲੋ",
    "Change the words": "ਸ਼ਬਦ ਬਦਲੋ",
    "Changes that wait": "ਜਿਹੜੀਆਂ ਤਬਦੀਲੀਆਂ ਉਡੀਕਦੀਆਂ ਹਨ",
    "Choose at least one thing it can skip.": "ਘੱਟੋ-ਘੱਟ ਇੱਕ ਚੀਜ਼ ਚੁਣੋ ਜੋ ਇਹ ਛੱਡ ਸਕਦਾ ਹੈ।",
    "Current password": "ਮੌਜੂਦਾ ਪਾਸਵਰਡ",
    "Demora code %@": "Demora ਕੋਡ %@",
    "From %@: %@": "%@ ਤੋਂ: %@",
    "Mistakes allowed: %d": "ਮਨਜ਼ੂਰ ਗ਼ਲਤੀਆਂ: %d",
    "Mistakes allowed: unlimited": "ਮਨਜ਼ੂਰ ਗ਼ਲਤੀਆਂ: ਬੇਹੱਦ",
    "Name, e.g. Mom or Alex": "ਨਾਮ, ਜਿਵੇਂ ਮੰਮੀ ਜਾਂ ਅਲੈਕਸ",
    "Part of this was saved and is waiting in Changes. The rest couldn't be saved.": "ਇਸਦਾ ਇੱਕ ਹਿੱਸਾ ਸੰਭਾਲਿਆ ਗਿਆ ਅਤੇ ਤਬਦੀਲੀਆਂ ਵਿੱਚ ਉਡੀਕ ਕਰ ਰਿਹਾ ਹੈ। ਬਾਕੀ ਸੰਭਾਲਿਆ ਨਹੀਂ ਜਾ ਸਕਿਆ।",
    "Password set": "ਪਾਸਵਰਡ ਸੈੱਟ ਹੋਇਆ",
    "Save changes": "ਤਬਦੀਲੀਆਂ ਸੰਭਾਲੋ",
    "Takes effect right away. What it can skip stays the same.": "ਤੁਰੰਤ ਲਾਗੂ ਹੁੰਦਾ ਹੈ। ਇਹ ਕੀ ਛੱਡ ਸਕਦਾ ਹੈ, ਉਹ ਉਹੀ ਰਹਿੰਦਾ ਹੈ।",
    "The current password is wrong or a change is already pending.": "ਮੌਜੂਦਾ ਪਾਸਵਰਡ ਗ਼ਲਤ ਹੈ ਜਾਂ ਇੱਕ ਤਬਦੀਲੀ ਪਹਿਲਾਂ ਹੀ ਉਡੀਕ ਵਿੱਚ ਹੈ।",
    "They approve from their Demora app, or with a code you email them.": "ਉਹ ਆਪਣੀ Demora ਐਪ ਤੋਂ, ਜਾਂ ਤੁਹਾਡੇ ਈਮੇਲ ਕੀਤੇ ਕੋਡ ਨਾਲ ਮਨਜ਼ੂਰ ਕਰਦੇ ਹਨ।",
    "They approve from their Demora app.": "ਉਹ ਆਪਣੀ Demora ਐਪ ਤੋਂ ਮਨਜ਼ੂਰ ਕਰਦੇ ਹਨ।",
    "This contact": "ਇਹ ਸੰਪਰਕ",
    "This is no longer available.": "ਇਹ ਹੁਣ ਉਪਲਬਧ ਨਹੀਂ।",
    "Typed word by word. Slow on purpose.": "ਸ਼ਬਦ-ਦਰ-ਸ਼ਬਦ ਲਿਖਿਆ ਜਾਂਦਾ ਹੈ। ਜਾਣ-ਬੁੱਝ ਕੇ ਹੌਲੀ।",
    "What it can skip": "ਇਹ ਕੀ ਛੱਡ ਸਕਦਾ ਹੈ",
    // You build: Guide, help and pointers to You (docs/you-redesign.md §8, Y10)
    "Demora protects deliberate decisions with time. In Rules → Your waits, choose separate waits for stricter and less-strict changes, one shared wait, or immediate tightening with a wait only for loosening. Lowering a budget tightens it; raising or removing it loosens it. Changing the policy follows your current policy, not the new one.": "Demora ਸੋਚ-ਸਮਝ ਕੇ ਕੀਤੇ ਫ਼ੈਸਲਿਆਂ ਨੂੰ ਸਮੇਂ ਨਾਲ ਬਚਾਉਂਦਾ ਹੈ। ਨਿਯਮ → ਤੁਹਾਡੀਆਂ ਉਡੀਕਾਂ ਵਿੱਚ, ਸਖ਼ਤ ਅਤੇ ਘੱਟ ਸਖ਼ਤ ਤਬਦੀਲੀਆਂ ਲਈ ਵੱਖਰੀਆਂ ਉਡੀਕਾਂ, ਇੱਕ ਸਾਂਝੀ ਉਡੀਕ, ਜਾਂ ਤੁਰੰਤ ਸਖ਼ਤ ਕਰਨਾ ਅਤੇ ਸਿਰਫ਼ ਢਿੱਲ ਦੇਣ ਤੇ ਉਡੀਕ ਚੁਣੋ। ਸਮਾਂ ਘਟਾਉਣਾ ਇਸਨੂੰ ਕੱਸਦਾ ਹੈ; ਵਧਾਉਣਾ ਜਾਂ ਹਟਾਉਣਾ ਢਿੱਲਾ ਕਰਦਾ ਹੈ। ਨੀਤੀ ਬਦਲਣਾ ਤੁਹਾਡੀ ਮੌਜੂਦਾ ਨੀਤੀ ਮੁਤਾਬਕ ਚੱਲਦਾ ਹੈ, ਨਵੀਂ ਮੁਤਾਬਕ ਨਹੀਂ।",
    "Changes on Today shows queued changes and their countdowns. Cancel one there before it applies, or skip its wait with an eligible way to skip a wait. Current rules stay active until the change applies. Existing countdowns keep their deadlines when you edit delay settings or reopen Demora. Background application depends on iOS callbacks; open Demora if a due change has not appeared.": "ਅੱਜ ਦੀਆਂ ਤਬਦੀਲੀਆਂ ਕਤਾਰ ਵਿੱਚ ਲੱਗੀਆਂ ਤਬਦੀਲੀਆਂ ਅਤੇ ਉਨ੍ਹਾਂ ਦੀਆਂ ਕਾਊਂਟਡਾਊਨਾਂ ਦਿਖਾਉਂਦੀਆਂ ਹਨ। ਲਾਗੂ ਹੋਣ ਤੋਂ ਪਹਿਲਾਂ ਉੱਥੇ ਇੱਕ ਨੂੰ ਰੱਦ ਕਰੋ, ਜਾਂ ਯੋਗ ਉਡੀਕ ਛੱਡਣ ਦੇ ਤਰੀਕੇ ਨਾਲ ਉਸਦੀ ਉਡੀਕ ਛੱਡੋ। ਤਬਦੀਲੀ ਲੱਗਣ ਤੱਕ ਮੌਜੂਦਾ ਨਿਯਮ ਚਾਲੂ ਰਹਿੰਦੇ ਹਨ। ਦੇਰੀ ਦੀਆਂ ਸੈਟਿੰਗਾਂ ਬਦਲਣ ਜਾਂ Demora ਦੁਬਾਰਾ ਖੋਲ੍ਹਣ ਤੇ ਮੌਜੂਦਾ ਕਾਊਂਟਡਾਊਨ ਆਪਣੀਆਂ ਆਖ਼ਰੀ ਤਾਰੀਖ਼ਾਂ ਰੱਖਦੀਆਂ ਹਨ। ਬੈਕਗ੍ਰਾਊਂਡ ਵਿੱਚ ਲਾਗੂ ਹੋਣਾ iOS ਕਾਲਬੈਕਾਂ ਤੇ ਨਿਰਭਰ ਹੈ; ਜੇ ਕੋਈ ਬਣਦੀ ਤਬਦੀਲੀ ਨਾ ਦਿਸੇ ਤਾਂ Demora ਖੋਲ੍ਹੋ।",
    "In Rules, tap New rule → Daily limit, name a limit, choose apps, categories or websites, and set usage minutes. A group shares one allowance across its selection. Zero minutes blocks it all day. Open an existing limit to edit it. Different limits by weekday replaces the default budget on each chosen day. Daily allowances reset at midnight; on iOS 17.4 or later, earlier usage that day also counts.": "ਨਿਯਮ ਵਿੱਚ, ਨਵਾਂ ਨਿਯਮ → ਰੋਜ਼ਾਨਾ ਹੱਦ ਛੂਹੋ, ਹੱਦ ਦਾ ਨਾਮ ਰੱਖੋ, ਐਪਾਂ, ਸ਼੍ਰੇਣੀਆਂ ਜਾਂ ਵੈੱਬਸਾਈਟਾਂ ਚੁਣੋ, ਅਤੇ ਵਰਤੋਂ ਦੇ ਮਿੰਟ ਤੈਅ ਕਰੋ। ਗਰੁੱਪ ਆਪਣੀ ਚੋਣ ਵਿੱਚ ਇੱਕ ਸਮਾਂ ਸਾਂਝਾ ਕਰਦਾ ਹੈ। ਜ਼ੀਰੋ ਮਿੰਟ ਸਾਰਾ ਦਿਨ ਬਲੌਕ ਕਰਦੇ ਹਨ। ਮੌਜੂਦਾ ਹੱਦ ਬਦਲਣ ਲਈ ਖੋਲ੍ਹੋ। ਹਫ਼ਤੇ ਦੇ ਦਿਨ ਮੁਤਾਬਕ ਵੱਖਰੀਆਂ ਹੱਦਾਂ ਹਰ ਚੁਣੇ ਦਿਨ ਮੂਲ ਸਮੇਂ ਦੀ ਥਾਂ ਲੈਂਦੀਆਂ ਹਨ। ਰੋਜ਼ਾਨਾ ਸਮਾਂ ਅੱਧੀ ਰਾਤ ਨੂੰ ਰੀਸੈੱਟ ਹੁੰਦਾ ਹੈ; iOS 17.4 ਜਾਂ ਨਵੇਂ ਤੇ, ਉਸ ਦਿਨ ਦੀ ਪਹਿਲਾਂ ਦੀ ਵਰਤੋਂ ਵੀ ਗਿਣੀ ਜਾਂਦੀ ਹੈ।",
    "In a limit's editor, Manual extra time sets up to five ordered uses, each with its own usage minutes and a wait, named password, phrase or contact approval. Request a use on Today only after the full daily budget is spent. These are app-usage minutes, not a timed unblock session. Requests survive reopening Demora and reset at midnight. Extra time does not skip an early split portion, wake wait or unrelated block.": "ਹੱਦ ਦੇ ਸੰਪਾਦਕ ਵਿੱਚ, ਹੱਥੀਂ ਵੱਧ ਸਮਾਂ ਪੰਜ ਤੱਕ ਕ੍ਰਮਵਾਰ ਵਰਤੋਂ ਬਣਾਉਂਦਾ ਹੈ, ਹਰ ਇੱਕ ਦੇ ਆਪਣੇ ਵਰਤੋਂ ਮਿੰਟ ਅਤੇ ਇੱਕ ਉਡੀਕ, ਨਾਮ ਵਾਲਾ ਪਾਸਵਰਡ, ਵਾਕ ਜਾਂ ਸੰਪਰਕ ਮਨਜ਼ੂਰੀ ਨਾਲ। ਅੱਜ ਵਿੱਚ ਵਰਤੋਂ ਤਾਂ ਹੀ ਮੰਗੋ ਜਦੋਂ ਪੂਰਾ ਰੋਜ਼ਾਨਾ ਸਮਾਂ ਮੁੱਕ ਚੁੱਕਾ ਹੋਵੇ। ਇਹ ਐਪ-ਵਰਤੋਂ ਦੇ ਮਿੰਟ ਹਨ, ਸਮੇਂ ਵਾਲਾ ਅਨਬਲੌਕ ਸੈਸ਼ਨ ਨਹੀਂ। ਬੇਨਤੀਆਂ Demora ਦੁਬਾਰਾ ਖੋਲ੍ਹਣ ਤੇ ਵੀ ਬਚੀਆਂ ਰਹਿੰਦੀਆਂ ਹਨ ਅਤੇ ਅੱਧੀ ਰਾਤ ਨੂੰ ਰੀਸੈੱਟ ਹੁੰਦੀਆਂ ਹਨ। ਵੱਧ ਸਮਾਂ ਕਿਸੇ ਸ਼ੁਰੂਆਤੀ ਵੰਡ ਵਾਲੇ ਹਿੱਸੇ, ਜਾਗਣ ਦੀ ਉਡੀਕ ਜਾਂ ਕਿਸੇ ਬੇਮੇਲ ਬਲੌਕ ਨੂੰ ਨਹੀਂ ਛੱਡਦਾ।",
    "In Rules, tap New rule → Day & night to create up to five named groups. Check existing limits and choose extra apps, then set wake-up and sleep times and weekdays. One optional all-other-apps group automatically excludes explicitly timed groups; whole-category exceptions are not supported. Existing general wake/sleep settings and Group wake-up gates still apply alongside these groups.": "ਨਿਯਮ ਵਿੱਚ, ਨਵਾਂ ਨਿਯਮ → ਦਿਨ ਤੇ ਰਾਤ ਛੂਹ ਕੇ ਪੰਜ ਤੱਕ ਨਾਮ ਵਾਲੇ ਗਰੁੱਪ ਬਣਾਓ। ਮੌਜੂਦਾ ਹੱਦਾਂ ਜਾਂਚੋ ਅਤੇ ਵਾਧੂ ਐਪਾਂ ਚੁਣੋ, ਫਿਰ ਜਾਗਣ ਅਤੇ ਨੀਂਦ ਦੇ ਸਮੇਂ ਤੇ ਹਫ਼ਤੇ ਦੇ ਦਿਨ ਤੈਅ ਕਰੋ। ਇੱਕ ਵਿਕਲਪਿਕ ਬਾਕੀ-ਸਾਰੀਆਂ-ਐਪਾਂ ਵਾਲਾ ਗਰੁੱਪ ਸਪਸ਼ਟ ਸਮੇਂ ਵਾਲੇ ਗਰੁੱਪਾਂ ਨੂੰ ਆਪਣੇ ਆਪ ਬਾਹਰ ਰੱਖਦਾ ਹੈ; ਪੂਰੀ-ਸ਼੍ਰੇਣੀ ਦੀਆਂ ਛੋਟਾਂ ਸਮਰਥਿਤ ਨਹੀਂ ਹਨ। ਮੌਜੂਦਾ ਆਮ ਜਾਗਣ/ਨੀਂਦ ਸੈਟਿੰਗਾਂ ਅਤੇ ਗਰੁੱਪ ਜਾਗਣ ਦੇ ਗੇਟ ਇਨ੍ਹਾਂ ਗਰੁੱਪਾਂ ਦੇ ਨਾਲ ਹੀ ਲਾਗੂ ਰਹਿੰਦੇ ਹਨ।",
    "Set a wake-up start and wait, with optional per-weekday start and wait overrides. Tap Wake up on Today to start every eligible group's wait together; tapping again does not restart it. An optional latest wake-up time, also configurable by weekday, ends only that wake gate even without a tap or during a wait. It does not end sleep blocking or restore a spent daily budget.": "ਜਾਗਣ ਦੀ ਸ਼ੁਰੂਆਤ ਅਤੇ ਉਡੀਕ ਤੈਅ ਕਰੋ, ਚਾਹੋ ਤਾਂ ਹਫ਼ਤੇ ਦੇ ਦਿਨ ਮੁਤਾਬਕ ਸ਼ੁਰੂਆਤ ਅਤੇ ਉਡੀਕ ਦੇ ਬਦਲਾਂ ਸਮੇਤ। ਹਰ ਯੋਗ ਗਰੁੱਪ ਦੀ ਉਡੀਕ ਇਕੱਠੀ ਸ਼ੁਰੂ ਕਰਨ ਲਈ ਅੱਜ ਤੇ ਜਾਗੋ ਛੂਹੋ; ਦੁਬਾਰਾ ਛੂਹਣ ਨਾਲ ਇਹ ਮੁੜ ਸ਼ੁਰੂ ਨਹੀਂ ਹੁੰਦੀ। ਇੱਕ ਵਿਕਲਪਿਕ ਸਭ ਤੋਂ ਦੇਰ ਨਾਲ ਜਾਗਣ ਦਾ ਸਮਾਂ, ਜੋ ਹਫ਼ਤੇ ਦੇ ਦਿਨ ਮੁਤਾਬਕ ਵੀ ਤੈਅ ਹੋ ਸਕਦਾ ਹੈ, ਸਿਰਫ਼ ਉਹ ਜਾਗਣ ਦਾ ਗੇਟ ਖ਼ਤਮ ਕਰਦਾ ਹੈ, ਛੂਹ ਤੋਂ ਬਿਨਾਂ ਜਾਂ ਉਡੀਕ ਦੌਰਾਨ ਵੀ। ਇਹ ਨੀਂਦ ਦੀ ਬਲੌਕਿੰਗ ਖ਼ਤਮ ਨਹੀਂ ਕਰਦਾ ਅਤੇ ਮੁੱਕਿਆ ਰੋਜ਼ਾਨਾ ਸਮਾਂ ਬਹਾਲ ਨਹੀਂ ਕਰਦਾ।",
    "In Rules, tap New rule and choose New session, Plan a block or Repeating block; New session also sits at the bottom of Today. Create a block, unblock or free period. New session starts after any required delay; its duration starts when it takes effect. Planned uses a specific date. Repeating runs daily, on weekdays or on a monthly pattern, and can cross midnight. Blocking rules can target selected apps or everything except a selection. Rules → Calendar shows occurrences.": "ਨਿਯਮ ਵਿੱਚ, ਨਵਾਂ ਨਿਯਮ ਛੂਹੋ ਅਤੇ ਨਵਾਂ ਸੈਸ਼ਨ, ਬਲੌਕ ਦੀ ਯੋਜਨਾ ਬਣਾਓ ਜਾਂ ਦੁਹਰਾਉਣ ਵਾਲਾ ਬਲੌਕ ਚੁਣੋ; ਨਵਾਂ ਸੈਸ਼ਨ ਅੱਜ ਦੇ ਹੇਠਾਂ ਵੀ ਹੈ। ਬਲੌਕ, ਅਨਬਲੌਕ ਜਾਂ ਖੁੱਲ੍ਹਾ ਸਮਾਂ ਬਣਾਓ। ਨਵਾਂ ਸੈਸ਼ਨ ਕਿਸੇ ਵੀ ਲੋੜੀਂਦੀ ਦੇਰੀ ਤੋਂ ਬਾਅਦ ਸ਼ੁਰੂ ਹੁੰਦਾ ਹੈ; ਇਸਦੀ ਮਿਆਦ ਲਾਗੂ ਹੋਣ ਤੋਂ ਸ਼ੁਰੂ ਹੁੰਦੀ ਹੈ। ਯੋਜਨਾਬੱਧ ਖ਼ਾਸ ਤਾਰੀਖ਼ ਵਰਤਦਾ ਹੈ। ਦੁਹਰਾਉਣ ਵਾਲਾ ਰੋਜ਼ਾਨਾ, ਹਫ਼ਤੇ ਦੇ ਦਿਨਾਂ ਤੇ ਜਾਂ ਮਹੀਨਾਵਾਰ ਢੰਗ ਨਾਲ ਚੱਲਦਾ ਹੈ, ਅਤੇ ਅੱਧੀ ਰਾਤ ਪਾਰ ਕਰ ਸਕਦਾ ਹੈ। ਬਲੌਕ ਕਰਨ ਵਾਲੇ ਨਿਯਮ ਚੁਣੀਆਂ ਐਪਾਂ ਜਾਂ ਚੋਣ ਤੋਂ ਇਲਾਵਾ ਸਭ ਕੁਝ ਨਿਸ਼ਾਨਾ ਬਣਾ ਸਕਦੇ ਹਨ। ਨਿਯਮ → ਕੈਲੰਡਰ ਵਾਰੀਆਂ ਦਿਖਾਉਂਦਾ ਹੈ।",
    "In Rules, tap Conflicts to review the next week's potential overlaps. Default application order is wake/sleep → recurring → planned → sessions. Later effects apply only within their scope: an allowlist is not a global unblock, does not reset daily usage, and does not clear unrelated specific blocks. Category membership is hidden by Apple, and untapped wake windows are estimates, so some overlaps are uncertain.": "ਨਿਯਮ ਵਿੱਚ, ਅਗਲੇ ਹਫ਼ਤੇ ਦੇ ਸੰਭਾਵੀ ਰਲਾਅ ਦੇਖਣ ਲਈ ਟਕਰਾਅ ਛੂਹੋ। ਮੂਲ ਲਾਗੂ ਕਰਨ ਦਾ ਕ੍ਰਮ ਹੈ ਜਾਗਣਾ/ਨੀਂਦ → ਦੁਹਰਾਉਣ ਵਾਲੇ → ਯੋਜਨਾਬੱਧ → ਸੈਸ਼ਨ। ਬਾਅਦ ਦੇ ਅਸਰ ਸਿਰਫ਼ ਆਪਣੇ ਦਾਇਰੇ ਵਿੱਚ ਲਾਗੂ ਹੁੰਦੇ ਹਨ: ਮਨਜ਼ੂਰ ਸੂਚੀ ਸਾਰਿਆਂ ਲਈ ਅਨਬਲੌਕ ਨਹੀਂ, ਰੋਜ਼ਾਨਾ ਵਰਤੋਂ ਰੀਸੈੱਟ ਨਹੀਂ ਕਰਦੀ, ਅਤੇ ਬੇਮੇਲ ਖ਼ਾਸ ਬਲੌਕ ਸਾਫ਼ ਨਹੀਂ ਕਰਦੀ। ਸ਼੍ਰੇਣੀ ਦੀ ਮੈਂਬਰੀ Apple ਲੁਕਾਉਂਦਾ ਹੈ, ਅਤੇ ਬਿਨਾਂ ਛੂਹੇ ਜਾਗਣ ਦੀਆਂ ਖਿੜਕੀਆਂ ਅੰਦਾਜ਼ੇ ਹਨ, ਇਸ ਲਈ ਕੁਝ ਰਲਾਅ ਅਨਿਸ਼ਚਿਤ ਹਨ।",
    "Open You → Ways to skip a wait to add, change or remove named passwords and phrases. Each has its own allowed uses; it cannot approve an unrelated change. Phrases can be custom or random on-device words, typed word by word with your chosen mistake allowance. Adding one or expanding what it may skip waits through the less-strict delay. Knowing the current password permits an immediate secret-only change, not an immediate permissions change.": "ਨਾਮ ਵਾਲੇ ਪਾਸਵਰਡ ਅਤੇ ਵਾਕ ਜੋੜਨ, ਬਦਲਣ ਜਾਂ ਹਟਾਉਣ ਲਈ ਤੁਸੀਂ → ਉਡੀਕ ਛੱਡਣ ਦੇ ਤਰੀਕੇ ਖੋਲ੍ਹੋ। ਹਰ ਇੱਕ ਦੀਆਂ ਆਪਣੀਆਂ ਮਨਜ਼ੂਰ ਵਰਤੋਂ ਹਨ; ਉਹ ਕਿਸੇ ਬੇਮੇਲ ਤਬਦੀਲੀ ਨੂੰ ਮਨਜ਼ੂਰ ਨਹੀਂ ਕਰ ਸਕਦਾ। ਵਾਕ ਆਪਣੇ ਹੋ ਸਕਦੇ ਹਨ ਜਾਂ ਡਿਵਾਈਸ ਤੇ ਬਣੇ ਬੇਤਰਤੀਬ ਸ਼ਬਦ, ਜੋ ਤੁਹਾਡੇ ਚੁਣੇ ਗ਼ਲਤੀ-ਭੱਤੇ ਨਾਲ ਸ਼ਬਦ-ਦਰ-ਸ਼ਬਦ ਲਿਖੇ ਜਾਂਦੇ ਹਨ। ਇੱਕ ਜੋੜਨਾ ਜਾਂ ਉਹ ਜੋ ਛੱਡ ਸਕਦਾ ਹੈ ਉਹ ਵਧਾਉਣਾ ਘੱਟ ਸਖ਼ਤ ਦੇਰੀ ਵਿੱਚੋਂ ਲੰਘ ਕੇ ਉਡੀਕਦਾ ਹੈ। ਮੌਜੂਦਾ ਪਾਸਵਰਡ ਜਾਣਨ ਨਾਲ ਸਿਰਫ਼ ਗੁਪਤ-ਸ਼ਬਦ ਦੀ ਤਬਦੀਲੀ ਤੁਰੰਤ ਹੁੰਦੀ ਹੈ, ਇਜਾਜ਼ਤਾਂ ਦੀ ਤਬਦੀਲੀ ਨਹੀਂ।",
    "In Rules, Recheck blocked limits takes around 30 seconds and keeps current blocks in place while iOS verifies usage. Confirmed spent limits stay blocked; a failed or interrupted check changes nothing. This is not a bypass for a real spent budget, split boundary, wake wait or schedule. Safe rechecking needs iOS 17.4 or later; wait until an active free period ends before trying.": "ਨਿਯਮ ਵਿੱਚ, ਬਲੌਕ ਹੱਦਾਂ ਦੁਬਾਰਾ ਜਾਂਚੋ ਲਗਭਗ 30 ਸਕਿੰਟ ਲੈਂਦਾ ਹੈ ਅਤੇ iOS ਵਰਤੋਂ ਦੀ ਪੁਸ਼ਟੀ ਕਰਦੇ ਸਮੇਂ ਮੌਜੂਦਾ ਬਲੌਕ ਕਾਇਮ ਰੱਖਦਾ ਹੈ। ਪੁਸ਼ਟੀ ਹੋਈਆਂ ਮੁੱਕੀਆਂ ਹੱਦਾਂ ਬਲੌਕ ਰਹਿੰਦੀਆਂ ਹਨ; ਫ਼ੇਲ੍ਹ ਜਾਂ ਵਿਚਾਲੇ ਰੁਕੀ ਜਾਂਚ ਕੁਝ ਨਹੀਂ ਬਦਲਦੀ। ਇਹ ਅਸਲ ਮੁੱਕੇ ਸਮੇਂ, ਵੰਡ ਦੀ ਹੱਦ, ਜਾਗਣ ਦੀ ਉਡੀਕ ਜਾਂ ਸਮਾਂ-ਸਾਰਣੀ ਤੋਂ ਬਚਣ ਦਾ ਰਾਹ ਨਹੀਂ। ਸੁਰੱਖਿਅਤ ਦੁਬਾਰਾ ਜਾਂਚ ਲਈ iOS 17.4 ਜਾਂ ਨਵਾਂ ਚਾਹੀਦਾ ਹੈ; ਕੋਸ਼ਿਸ਼ ਤੋਂ ਪਹਿਲਾਂ ਚਾਲੂ ਖੁੱਲ੍ਹੇ ਸਮੇਂ ਦੇ ਮੁੱਕਣ ਦੀ ਉਡੀਕ ਕਰੋ।",
    "In You → Notifications, choose five-minute limit warnings and optional free-period boundary reminders. Limit warnings are only for budgets longer than five minutes and are suppressed during free periods. iOS notification permission is separate from Screen Time access, and alerts can arrive late or not at all. Now & Next and Pending Change widgets are read-only summaries; they do not apply overrides or show raw usage.": "ਤੁਸੀਂ → ਸੂਚਨਾਵਾਂ ਵਿੱਚ, ਪੰਜ-ਮਿੰਟ ਦੀਆਂ ਹੱਦ ਚੇਤਾਵਨੀਆਂ ਅਤੇ ਵਿਕਲਪਿਕ ਖੁੱਲ੍ਹੇ-ਸਮੇਂ ਦੀ ਹੱਦ ਦੀਆਂ ਯਾਦ-ਦਹਾਨੀਆਂ ਚੁਣੋ। ਹੱਦ ਚੇਤਾਵਨੀਆਂ ਸਿਰਫ਼ ਪੰਜ ਮਿੰਟ ਤੋਂ ਲੰਮੇ ਸਮੇਂ ਲਈ ਹਨ ਅਤੇ ਖੁੱਲ੍ਹੇ ਸਮੇਂ ਦੌਰਾਨ ਦਬਾਈਆਂ ਜਾਂਦੀਆਂ ਹਨ। iOS ਸੂਚਨਾ ਇਜਾਜ਼ਤ ਸਕ੍ਰੀਨ ਟਾਈਮ ਪਹੁੰਚ ਤੋਂ ਵੱਖਰੀ ਹੈ, ਅਤੇ ਚੇਤਾਵਨੀਆਂ ਦੇਰ ਨਾਲ ਜਾਂ ਬਿਲਕੁਲ ਨਾ ਵੀ ਆ ਸਕਦੀਆਂ ਹਨ। ਹੁਣ ਤੇ ਅੱਗੇ ਅਤੇ ਉਡੀਕ-ਵਿੱਚ-ਤਬਦੀਲੀ ਵਿਜਟ ਸਿਰਫ਼-ਪੜ੍ਹਨ ਵਾਲੇ ਸਾਰ ਹਨ; ਉਹ ਛੋਟਾਂ ਲਾਗੂ ਨਹੀਂ ਕਰਦੇ ਜਾਂ ਕੱਚੀ ਵਰਤੋਂ ਨਹੀਂ ਦਿਖਾਉਂਦੇ।",
    "contacts, passwords and phrases": "ਸੰਪਰਕ, ਪਾਸਵਰਡ ਅਤੇ ਵਾਕ",
    "How Demora works": "Demora ਕਿਵੇਂ ਕੰਮ ਕਰਦਾ ਹੈ",
    "four short pages": "ਚਾਰ ਛੋਟੇ ਪੰਨੇ",
    "Your past decision wins": "ਤੁਹਾਡਾ ਪਿਛਲਾ ਫ਼ੈਸਲਾ ਜਿੱਤਦਾ ਹੈ",
    "You set your rules when you're calm. Later, when an impulse says \"just this once\", the rule you chose still holds.": "ਤੁਸੀਂ ਆਪਣੇ ਨਿਯਮ ਸ਼ਾਂਤ ਮਨ ਨਾਲ ਤੈਅ ਕਰਦੇ ਹੋ। ਬਾਅਦ ਵਿੱਚ, ਜਦੋਂ ਕੋਈ ਇੱਛਾ ਕਹੇ “ਬੱਸ ਇੱਕ ਵਾਰ”, ਤਾਂ ਤੁਹਾਡਾ ਚੁਣਿਆ ਨਿਯਮ ਫਿਰ ਵੀ ਟਿਕਿਆ ਰਹਿੰਦਾ ਹੈ।",
    "Stricter is quick, looser waits": "ਸਖ਼ਤ ਤੁਰੰਤ, ਢਿੱਲ ਉਡੀਕਦੀ ਹੈ",
    "Making a rule stricter can apply right away. Making it looser waits through the wait you chose in Rules → Your waits.": "ਨਿਯਮ ਨੂੰ ਸਖ਼ਤ ਕਰਨਾ ਤੁਰੰਤ ਲਾਗੂ ਹੋ ਸਕਦਾ ਹੈ। ਇਸਨੂੰ ਢਿੱਲਾ ਕਰਨਾ ਉਸ ਉਡੀਕ ਵਿੱਚੋਂ ਲੰਘਦਾ ਹੈ ਜੋ ਤੁਸੀਂ ਨਿਯਮ → ਤੁਹਾਡੀਆਂ ਉਡੀਕਾਂ ਵਿੱਚ ਚੁਣੀ।",
    "Changes wait in Changes": "ਤਬਦੀਲੀਆਂ ਤਬਦੀਲੀਆਂ ਵਿੱਚ ਉਡੀਕਦੀਆਂ ਹਨ",
    "A looser change waits in Changes on Today with its countdown. Until it lands nothing changes, and you can cancel it any time.": "ਢਿੱਲੀ ਤਬਦੀਲੀ ਅੱਜ ਦੀਆਂ ਤਬਦੀਲੀਆਂ ਵਿੱਚ ਆਪਣੀ ਕਾਊਂਟਡਾਊਨ ਨਾਲ ਉਡੀਕਦੀ ਹੈ। ਲੱਗਣ ਤੱਕ ਕੁਝ ਨਹੀਂ ਬਦਲਦਾ, ਅਤੇ ਤੁਸੀਂ ਇਸਨੂੰ ਕਦੇ ਵੀ ਰੱਦ ਕਰ ਸਕਦੇ ਹੋ।",
    "A trusted contact, a password or a phrase can let a change apply early, but only for the kinds of change you allowed. Changes to them wait too. Set them up in You → Ways to skip a wait.": "ਭਰੋਸੇਯੋਗ ਸੰਪਰਕ, ਪਾਸਵਰਡ ਜਾਂ ਵਾਕ ਤਬਦੀਲੀ ਨੂੰ ਜਲਦੀ ਲਾਗੂ ਕਰਵਾ ਸਕਦਾ ਹੈ, ਪਰ ਸਿਰਫ਼ ਉਨ੍ਹਾਂ ਕਿਸਮਾਂ ਦੀਆਂ ਤਬਦੀਲੀਆਂ ਲਈ ਜਿਨ੍ਹਾਂ ਦੀ ਤੁਸੀਂ ਇਜਾਜ਼ਤ ਦਿੱਤੀ। ਇਨ੍ਹਾਂ ਵਿੱਚ ਤਬਦੀਲੀਆਂ ਵੀ ਉਡੀਕਦੀਆਂ ਹਨ। ਇਨ੍ਹਾਂ ਨੂੰ ਤੁਸੀਂ → ਉਡੀਕ ਛੱਡਣ ਦੇ ਤਰੀਕੇ ਵਿੱਚ ਸੈੱਟ ਕਰੋ।",
    "How Demora works is always in You → Help & guide.": "Demora ਕਿਵੇਂ ਕੰਮ ਕਰਦਾ ਹੈ, ਇਹ ਹਮੇਸ਼ਾ ਤੁਸੀਂ → ਮਦਦ ਤੇ ਗਾਈਡ ਵਿੱਚ ਹੈ।",
    "Find practical instructions and troubleshooting in You → Help & guide → Guide.": "ਅਮਲੀ ਹਦਾਇਤਾਂ ਅਤੇ ਸਮੱਸਿਆ ਹੱਲ ਤੁਸੀਂ → ਮਦਦ ਤੇ ਗਾਈਡ → ਗਾਈਡ ਵਿੱਚ ਲੱਭੋ।",
    "Contact invitations are sent after setup. Contacts must confirm before they can approve; manage them in You → Ways to skip a wait.": "ਸੈੱਟਅੱਪ ਤੋਂ ਬਾਅਦ ਸੰਪਰਕਾਂ ਨੂੰ ਸੱਦੇ ਭੇਜੇ ਜਾਂਦੇ ਹਨ। ਮਨਜ਼ੂਰੀ ਦੇਣ ਤੋਂ ਪਹਿਲਾਂ ਸੰਪਰਕਾਂ ਨੂੰ ਪੁਸ਼ਟੀ ਕਰਨੀ ਪੈਂਦੀ ਹੈ; ਉਨ੍ਹਾਂ ਨੂੰ ਤੁਸੀਂ → ਉਡੀਕ ਛੱਡਣ ਦੇ ਤਰੀਕੇ ਵਿੱਚ ਸੰਭਾਲੋ।",
    "A person you choose approves skipping a countdown — by email code or from their own Demora app. You can also add more later in You → Ways to skip a wait.": "ਤੁਹਾਡਾ ਚੁਣਿਆ ਵਿਅਕਤੀ ਕਾਊਂਟਡਾਊਨ ਛੱਡਣ ਨੂੰ ਮਨਜ਼ੂਰ ਕਰਦਾ ਹੈ — ਈਮੇਲ ਕੋਡ ਨਾਲ ਜਾਂ ਆਪਣੀ Demora ਐਪ ਤੋਂ। ਤੁਸੀਂ ਬਾਅਦ ਵਿੱਚ ਵੀ ਤੁਸੀਂ → ਉਡੀਕ ਛੱਡਣ ਦੇ ਤਰੀਕੇ ਵਿੱਚ ਹੋਰ ਜੋੜ ਸਕਦੇ ਹੋ।",
    "Choose your language here. You can change it anytime under You → Appearance → Language.": "ਆਪਣੀ ਭਾਸ਼ਾ ਇੱਥੇ ਚੁਣੋ। ਤੁਸੀਂ ਇਸਨੂੰ ਕਦੇ ਵੀ ਤੁਸੀਂ → ਦਿੱਖ → ਭਾਸ਼ਾ ਹੇਠ ਬਦਲ ਸਕਦੇ ਹੋ।",
    "Ask them for the code under You → Your code in their Demora. They'll get a request to accept before they can approve for you.": "ਉਨ੍ਹਾਂ ਦੀ Demora ਵਿੱਚ ਤੁਸੀਂ → ਤੁਹਾਡਾ ਕੋਡ ਵਿੱਚ ਦਿਸਦਾ ਕੋਡ ਉਨ੍ਹਾਂ ਤੋਂ ਮੰਗੋ। ਤੁਹਾਡੇ ਲਈ ਮਨਜ਼ੂਰ ਕਰਨ ਤੋਂ ਪਹਿਲਾਂ ਉਨ੍ਹਾਂ ਨੂੰ ਸਵੀਕਾਰ ਕਰਨ ਲਈ ਬੇਨਤੀ ਮਿਲੇਗੀ।",
    // You review fix: what can never be skipped early
