    "%d × %@ unblocked": "%d × %@ ਅਨਬਲੌਕ",
    "A block starts when you check in at a place or in a country, and runs until the end you choose. Leaving doesn't end it. It blocks only the apps you choose.": "ਬਲੌਕ ਉਦੋਂ ਸ਼ੁਰੂ ਹੁੰਦਾ ਹੈ ਜਦੋਂ ਤੁਸੀਂ ਕਿਸੇ ਥਾਂ ਜਾਂ ਦੇਸ਼ ਵਿੱਚ ਚੈੱਕ ਇਨ ਕਰਦੇ ਹੋ, ਅਤੇ ਤੁਹਾਡੇ ਚੁਣੇ ਅੰਤ ਤੱਕ ਚੱਲਦਾ ਹੈ। ਛੱਡ ਜਾਣ ਨਾਲ ਇਹ ਖ਼ਤਮ ਨਹੀਂ ਹੁੰਦਾ। ਇਹ ਸਿਰਫ਼ ਤੁਹਾਡੀਆਂ ਚੁਣੀਆਂ ਐਪਾਂ ਬਲੌਕ ਕਰਦਾ ਹੈ।",
