    "Free time or a block that depends on place, day or time": "ਖੁੱਲ੍ਹਾ ਸਮਾਂ ਜਾਂ ਕਿਸੇ ਥਾਂ, ਦਿਨ ਜਾਂ ਸਮੇਂ ਤੇ ਨਿਰਭਰ ਬਲੌਕ",
