    "Use at most four conditions.": "ਵੱਧ ਤੋਂ ਵੱਧ ਚਾਰ ਸ਼ਰਤਾਂ ਵਰਤੋ।",
    "With “any of”, a block can use times, places and countries, not days or dates.": "“ਇਨ੍ਹਾਂ ਵਿੱਚੋਂ ਕੋਈ ਵੀ” ਨਾਲ, ਬਲੌਕ ਸਮੇਂ, ਥਾਵਾਂ ਅਤੇ ਦੇਸ਼ਾਂ ਨੂੰ ਵਰਤ ਸਕਦਾ ਹੈ, ਦਿਨਾਂ ਜਾਂ ਤਾਰੀਖ਼ਾਂ ਨੂੰ ਨਹੀਂ।",
    "With “any of”, a time on its own blocks every day, like a repeating block.": "“ਇਨ੍ਹਾਂ ਵਿੱਚੋਂ ਕੋਈ ਵੀ” ਨਾਲ, ਇਕੱਲਾ ਸਮਾਂ ਹਰ ਦਿਨ ਬਲੌਕ ਕਰਦਾ ਹੈ, ਦੁਹਰਾਉਣ ਵਾਲੇ ਬਲੌਕ ਵਾਂਗ।",
    "You can add up to four conditions.": "ਤੁਸੀਂ ਚਾਰ ਤੱਕ ਸ਼ਰਤਾਂ ਜੋੜ ਸਕਦੇ ਹੋ।",
