    // When & where step 3: check-in sheet and Today rows.
    "Free time needs all of these.": "ਖੁੱਲ੍ਹੇ ਸਮੇਂ ਲਈ ਇਹ ਸਾਰੇ ਚਾਹੀਦੇ ਹਨ।",
    "Free time needs any of these.": "ਖੁੱਲ੍ਹੇ ਸਮੇਂ ਲਈ ਇਨ੍ਹਾਂ ਵਿੱਚੋਂ ਕੋਈ ਇੱਕ ਚਾਹੀਦਾ ਹੈ।",
    "The block needs all of these.": "ਬਲੌਕ ਲਈ ਇਹ ਸਾਰੇ ਚਾਹੀਦੇ ਹਨ।",
    "The block needs any of these.": "ਬਲੌਕ ਲਈ ਇਨ੍ਹਾਂ ਵਿੱਚੋਂ ਕੋਈ ਇੱਕ ਚਾਹੀਦਾ ਹੈ।",
    "This rule changed. Check in again.": "ਇਹ ਨਿਯਮ ਬਦਲ ਗਿਆ। ਦੁਬਾਰਾ ਚੈੱਕ ਇਨ ਕਰੋ।",
