    "Less than a minute is left in this window.": "ਇਸ ਖਿੜਕੀ ਵਿੱਚ ਇੱਕ ਮਿੰਟ ਤੋਂ ਘੱਟ ਬਾਕੀ ਹੈ।",
    "It's waiting in Changes instead.": "ਇਸ ਦੀ ਥਾਂ ਇਹ ਤਬਦੀਲੀਆਂ ਵਿੱਚ ਉਡੀਕ ਕਰ ਰਿਹਾ ਹੈ।",
    "This check is more than two minutes old. Check in again.": "ਇਹ ਜਾਂਚ ਦੋ ਮਿੰਟ ਤੋਂ ਵੱਧ ਪੁਰਾਣੀ ਹੈ। ਦੁਬਾਰਾ ਚੈੱਕ ਇਨ ਕਰੋ।",
    "A new day started. Check in again.": "ਨਵਾਂ ਦਿਨ ਸ਼ੁਰੂ ਹੋ ਗਿਆ। ਦੁਬਾਰਾ ਚੈੱਕ ਇਨ ਕਰੋ।",
    "Your time zone changed. Check in again.": "ਤੁਹਾਡਾ ਸਮਾਂ ਖੇਤਰ ਬਦਲ ਗਿਆ। ਦੁਬਾਰਾ ਚੈੱਕ ਇਨ ਕਰੋ।",
    "The conditions aren't met any more.": "ਸ਼ਰਤਾਂ ਹੁਣ ਪੂਰੀਆਂ ਨਹੀਂ ਹਨ।",
    "Choose a length this rule allows.": "ਇਸ ਨਿਯਮ ਦੀ ਇਜਾਜ਼ਤ ਵਾਲੀ ਮਿਆਦ ਚੁਣੋ।",
    "Free time from this rule is already on.": "ਇਸ ਨਿਯਮ ਤੋਂ ਖੁੱਲ੍ਹਾ ਸਮਾਂ ਪਹਿਲਾਂ ਹੀ ਚਾਲੂ ਹੈ।",
    "This check-in was already used. Check in again.": "ਇਹ ਚੈੱਕ ਇਨ ਪਹਿਲਾਂ ਹੀ ਵਰਤਿਆ ਜਾ ਚੁੱਕਾ ਹੈ। ਦੁਬਾਰਾ ਚੈੱਕ ਇਨ ਕਰੋ।",
    "A change is still being applied. Try again in a moment.": "ਇੱਕ ਤਬਦੀਲੀ ਅਜੇ ਲਾਗੂ ਹੋ ਰਹੀ ਹੈ। ਥੋੜ੍ਹੀ ਦੇਰ ਬਾਅਦ ਦੁਬਾਰਾ ਕੋਸ਼ਿਸ਼ ਕਰੋ।",
    "Free time couldn't start safely. iOS may not be able to track another session right now. Nothing changed.": "ਖੁੱਲ੍ਹਾ ਸਮਾਂ ਸੁਰੱਖਿਅਤ ਢੰਗ ਨਾਲ ਸ਼ੁਰੂ ਨਹੀਂ ਹੋ ਸਕਿਆ। ਹੋ ਸਕਦਾ ਹੈ iOS ਹੁਣ ਇੱਕ ਹੋਰ ਸੈਸ਼ਨ ਨੂੰ ਟਰੈਕ ਨਾ ਕਰ ਸਕੇ। ਕੁਝ ਨਹੀਂ ਬਦਲਿਆ।",
