    "Your clock was changed recently. The block can start once it's set right again.": "ਤੁਹਾਡੀ ਘੜੀ ਹਾਲ ਹੀ ਵਿੱਚ ਬਦਲੀ ਗਈ ਸੀ। ਇਸਦੇ ਦੁਬਾਰਾ ਠੀਕ ਹੋਣ ਤੇ ਬਲੌਕ ਸ਼ੁਰੂ ਹੋ ਸਕਦਾ ਹੈ।",
    "Leaving doesn't end it. Ending it early waits like any looser change.": "ਛੱਡ ਜਾਣ ਨਾਲ ਇਹ ਖ਼ਤਮ ਨਹੀਂ ਹੁੰਦਾ। ਇਸਨੂੰ ਜਲਦੀ ਖ਼ਤਮ ਕਰਨਾ ਕਿਸੇ ਵੀ ਢਿੱਲੀ ਤਬਦੀਲੀ ਵਾਂਗ ਉਡੀਕਦਾ ਹੈ।",
    "Its time blocks on its own, without a check-in.": "ਇਸਦਾ ਸਮਾਂ ਬਿਨਾਂ ਚੈੱਕ ਇਨ ਦੇ ਆਪਣੇ ਆਪ ਬਲੌਕ ਕਰਦਾ ਹੈ।",
    "It waits your stricter delay, like New session. It's in Changes.": "ਇਹ ਤੁਹਾਡੀ ਸਖ਼ਤ ਦੇਰੀ ਉਡੀਕਦਾ ਹੈ, ਨਵੇਂ ਸੈਸ਼ਨ ਵਾਂਗ। ਇਹ ਤਬਦੀਲੀਆਂ ਵਿੱਚ ਹੈ।",
    "A block from this rule is already on.": "ਇਸ ਨਿਯਮ ਦਾ ਇੱਕ ਬਲੌਕ ਪਹਿਲਾਂ ਹੀ ਚਾਲੂ ਹੈ।",
    "The block couldn't start safely. iOS may not be able to track another session right now. Nothing changed.": "ਬਲੌਕ ਸੁਰੱਖਿਅਤ ਢੰਗ ਨਾਲ ਸ਼ੁਰੂ ਨਹੀਂ ਹੋ ਸਕਿਆ। ਹੋ ਸਕਦਾ ਹੈ iOS ਹੁਣ ਇੱਕ ਹੋਰ ਸੈਸ਼ਨ ਨੂੰ ਟਰੈਕ ਨਾ ਕਰ ਸਕੇ। ਕੁਝ ਨਹੀਂ ਬਦਲਿਆ।",
    "Review": "ਸਮੀਖਿਆ",
