    "A change to this rule lands first. Check in after it lands.": "ਇਸ ਨਿਯਮ ਦੀ ਇੱਕ ਤਬਦੀਲੀ ਪਹਿਲਾਂ ਲੱਗੇਗੀ। ਉਸਦੇ ਲੱਗਣ ਤੋਂ ਬਾਅਦ ਚੈੱਕ ਇਨ ਕਰੋ।",
