    "Demora reads your location once when you tap Check in, set a place or use the country you're in, to see if a rule's place or country applies. Your location isn't sent anywhere; only the places you save are kept.": "Demora ਤੁਹਾਡੀ ਲੋਕੇਸ਼ਨ ਇੱਕ ਵਾਰ ਪੜ੍ਹਦਾ ਹੈ ਜਦੋਂ ਤੁਸੀਂ ਚੈੱਕ ਇਨ ਛੂਹਦੇ ਹੋ, ਕੋਈ ਥਾਂ ਤੈਅ ਕਰਦੇ ਹੋ ਜਾਂ ਉਹ ਦੇਸ਼ ਵਰਤਦੇ ਹੋ ਜਿਸ ਵਿੱਚ ਤੁਸੀਂ ਹੋ, ਇਹ ਦੇਖਣ ਲਈ ਕਿ ਨਿਯਮ ਦੀ ਥਾਂ ਜਾਂ ਦੇਸ਼ ਲਾਗੂ ਹੁੰਦਾ ਹੈ ਜਾਂ ਨਹੀਂ। ਤੁਹਾਡੀ ਲੋਕੇਸ਼ਨ ਕਿਤੇ ਨਹੀਂ ਭੇਜੀ ਜਾਂਦੀ; ਸਿਰਫ਼ ਉਹ ਥਾਵਾਂ ਰੱਖੀਆਂ ਜਾਂਦੀਆਂ ਹਨ ਜੋ ਤੁਸੀਂ ਸੰਭਾਲਦੇ ਹੋ।",
    "Demora needs your precise location for this check, to tell whether you're inside a rule's place or country.": "Demora ਨੂੰ ਇਸ ਜਾਂਚ ਲਈ ਤੁਹਾਡੀ ਸਟੀਕ ਲੋਕੇਸ਼ਨ ਚਾਹੀਦੀ ਹੈ, ਇਹ ਦੱਸਣ ਲਈ ਕਿ ਤੁਸੀਂ ਕਿਸੇ ਨਿਯਮ ਦੀ ਥਾਂ ਜਾਂ ਦੇਸ਼ ਦੇ ਅੰਦਰ ਹੋ ਜਾਂ ਨਹੀਂ।",
